import { CoreExporter } from './core-exporter.js';
import { zipSync, strToU8 } from 'fflate';
import { Color } from '../../core/math/color.js';
import { Mat3 } from '../../core/math/mat3.js';
import { Mat4 } from '../../core/math/mat4.js';
import { Vec3 } from '../../core/math/vec3.js';

import {
    SEMANTIC_POSITION,
    SEMANTIC_NORMAL,
    SEMANTIC_TEXCOORD0,
    SEMANTIC_TEXCOORD1,
    SEMANTIC_BLENDINDICES,
    SEMANTIC_BLENDWEIGHT
} from '../../platform/graphics/constants.js';

/**
 * @import { Entity } from '../../framework/entity.js'
 * @import { Material } from '../../scene/materials/material.js'
 * @import { Mesh } from '../../scene/mesh.js'
 * @import { SkinInstance } from '../../scene/skin-instance.js'
 * @import { Texture } from '../../platform/graphics/texture.js'
 */

const ROOT_FILE_NAME = 'root';

const _skinMatrix = new Mat4();
const _normalMatrix = new Mat3();
const _vec = new Vec3();

/**
 * Moves the vertices of a skinned mesh from its bind pose to where its bones currently place
 * them in world space.
 *
 * @param {Mesh} mesh - The skinned mesh.
 * @param {SkinInstance} skinInstance - The skin instance that holds the bones.
 * @param {number[]} positions - The vertex positions, transformed in place.
 * @param {number[]} normals - The vertex normals, transformed in place. Can be empty.
 */
const skinVertices = (mesh, skinInstance, positions, normals) => {

    const boneIndices = [];
    const boneWeights = [];
    mesh.getVertexStream(SEMANTIC_BLENDINDICES, boneIndices);
    const numVerts = mesh.getVertexStream(SEMANTIC_BLENDWEIGHT, boneWeights);
    const numInfluences = boneWeights.length / numVerts;

    // transforms from the bind pose to the current pose of each bone
    const { bones, skin } = skinInstance;
    const boneMatrices = bones.map((bone, i) => {
        return new Mat4().mul2(bone.getWorldTransform(), skin.inverseBindPose[i]);
    });

    const m = _skinMatrix.data;
    for (let v = 0; v < numVerts; v++) {

        // blend the bone matrices by the vertex weights
        m.fill(0);
        let totalWeight = 0;
        for (let j = v * numInfluences; j < (v + 1) * numInfluences; j++) {
            const weight = boneWeights[j];
            if (weight > 0) {
                const bm = boneMatrices[boneIndices[j]].data;
                for (let k = 0; k < 16; k++) {
                    m[k] += weight * bm[k];
                }
                totalWeight += weight;
            }
        }

        // weights stored as normalized integers are read back unnormalized
        if (totalWeight > 0) {
            for (let k = 0; k < 16; k++) {
                m[k] /= totalWeight;
            }
        }

        const i = v * 3;
        _vec.set(positions[i], positions[i + 1], positions[i + 2]);
        _skinMatrix.transformPoint(_vec, _vec);
        positions[i] = _vec.x;
        positions[i + 1] = _vec.y;
        positions[i + 2] = _vec.z;

        if (normals.length) {
            _normalMatrix.invertMat4(_skinMatrix).transpose();
            _vec.set(normals[i], normals[i + 1], normals[i + 2]);
            _normalMatrix.transformVector(_vec, _vec).normalize();
            normals[i] = _vec.x;
            normals[i + 1] = _vec.y;
            normals[i + 2] = _vec.z;
        }
    }
};

const header = `#usda 1.0
(
    customLayerData = {
        string creator = "PlayCanvas UsdzExporter"
    }
    metersPerUnit = 1
    upAxis = "Y"
)
`;

const materialListTemplate = materials => `
def "Materials"
{
    ${materials.join('\n')}
}
`;

const meshTemplate = (faceVertexCounts, indices, normals, positions, uv0, uv1) => `
def "Mesh"
{
    def Mesh "Mesh"
    {
        int[] faceVertexCounts = [${faceVertexCounts}]
        int[] faceVertexIndices = [${indices}]
        normal3f[] normals = [${normals}] (
            interpolation = "vertex"
        )
        point3f[] points = [${positions}]
        texCoord2f[] primvars:st = [${uv0}] (
            interpolation = "vertex"
        )
        texCoord2f[] primvars:st1 = [${uv1}] (
            interpolation = "vertex"
        )
        uniform token subdivisionScheme = "none"
    }
}
`;

const meshInstanceTemplate = (nodeName, meshRefPath, worldMatrix, materialRefPath) => /* usd */`
def Xform "${nodeName}" (
    prepend references = ${meshRefPath}
)
{
    matrix4d xformOp:transform = ${worldMatrix}
    uniform token[] xformOpOrder = ["xformOp:transform"]

    rel material:binding = ${materialRefPath}
}
`;

const materialValueTemplate = (type, name, value) => `                    ${type} inputs:${name} = ${value}`;

/**
 * Implementation of the USDZ format exporter. Note that ASCII version of the format (USDA) is used.
 *
 * @category Exporter
 */
class UsdzExporter extends CoreExporter {
    /**
     * Maps a mesh to a reference (path) inside the usdz container
     *
     * @type {Map<Mesh, string>}
     * @ignore
     */
    meshMap;

    /**
     * Maps a material to a reference (path) inside the usdz container
     *
     * @type {Map<Material, string>}
     * @ignore
     */
    materialMap;

    /**
     * A list of generated material usda contents, which are processed at the end
     *
     * @ignore
     */
    materials;

    /**
     * A map of texture requests
     *
     * @type {Map<Texture, string>}
     * @ignore
     */
    textureMap;

    /**
     * A set of used node names. Used in order to keep them unique.
     *
     * @type {Set<string>}
     * @ignore
     */
    nodeNames;

    /**
     * An object, storing a mapping between the file name and its content. Used as input to fflate to
     * zip up the data.
     *
     * @type {object}
     * @ignore
     */
    files;

    init() {
        this.meshMap = new Map();
        this.textureMap = new Map();
        this.materialMap = new Map();
        this.materials = [];
        this.files = {};
        this.nodeNames = new Set();
    }

    done() {
        this.meshMap = null;
        this.textureMap = null;
        this.materialMap = null;
        this.materials = null;
        this.files = null;
        this.nodeNames = null;
    }

