        const isRGBA = true;
        const mimeType = isRGBA ? 'image/png' : 'image/jpeg';

        // convert texture data to canvas
        const texture = textureArray[i];
        const texturePromise = this.textureToCanvas(texture, textureOptions).then((canvas) => {

