            stencil: this.supportsStencil,
            samples: this.samples
        });

        this.initDeviceCaps();

        // no-op dynamic buffers so the (unconditional) view uniform buffer path runs harmlessly
        this.dynamicBuffers = new NullDynamicBuffers(this);

        this.postInit();
    }

