import { Entity } from '../../../src/framework/entity.js';
import { Mesh } from '../../../src/scene/mesh.js';
import { StandardMaterial } from '../../../src/scene/materials/standard-material.js';
import { NullGraphicsDevice } from '../../../src/platform/graphics/null/null-graphics-device.js';

let dom = null;

/**
 * Installs a minimal browser environment used by the texture export paths. The exporters use
 * document.createElement('canvas'), FileReader, Blob and the HTMLCanvasElement / HTMLImageElement
 * globals.
 *
 * @returns {JSDOM} The jsdom instance.
 */
export function setupDom() {
    if (dom) {
        return dom;
    }

    dom = new JSDOM('<!doctype html><html><body></body></html>', { pretendToBeVisual: true });
    globalThis.window = dom.window;
    globalThis.document = dom.window.document;
    globalThis.HTMLCanvasElement = dom.window.HTMLCanvasElement;
    globalThis.HTMLImageElement = dom.window.HTMLImageElement;
    globalThis.OffscreenCanvas = dom.window.OffscreenCanvas;
    globalThis.ImageBitmap = dom.window.ImageBitmap;
    globalThis.FileReader = dom.window.FileReader;
    globalThis.Blob = dom.window.Blob;

    return dom;
}

export function teardownDom() {
    if (dom) {
        dom.window.close();
        dom = null;
    }
}

export function createDevice() {
    return new NullGraphicsDevice();
}

/**
 * Creates a small triangle mesh with sensible defaults.
 *
 * @param {object} device - The graphics device.
 * @param {object} [options] - Optional geometry overrides. Pass null to omit a stream.
 * @returns {Mesh} The mesh.
 */
export function createTriangleMesh(device, options = {}) {
    const {
        positions = [0, 0, 0, 1, 0, 0, 0, 1, 0],
        normals = [0, 0, 1, 0, 0, 1, 0, 0, 1],
        uv0 = [0, 0, 1, 0, 0, 1],
        uv1 = null,
        colors = null,
        indices = [0, 1, 2]
    } = options;

    const mesh = new Mesh(device);
    mesh.setPositions(positions);

    if (normals) {
        mesh.setNormals(normals);
    }
    if (uv0) {
        mesh.setUvs(0, uv0);
    }
    if (uv1) {
        mesh.setUvs(1, uv1);
    }
    if (colors) {
        mesh.setColors(colors);
    }
    if (indices) {
        mesh.setIndices(indices);
    }

    mesh.update();
    return mesh;
}

export function createMaterial(overrides = {}) {
    return Object.assign(new StandardMaterial(), overrides);
}

export function createEntity(name = 'root') {
    return new Entity(name, { systems: {} });
}

export function attachRender(entity, meshInstances) {
    entity.render = { enabled: true, meshInstances };
    entity.c = { ...(entity.c ?? {}), render: entity.render };
    return entity;
}

export function meshInstance(mesh, material, node, extra = {}) {
    return { mesh, material, node, ...extra };
}

/**
 * Creates a 2D canvas filled with a solid color.
 *
 * @param {number} width - Canvas width.
 * @param {number} height - Canvas height.
 * @param {string} fillStyle - CSS color used to fill the canvas.
 * @returns {HTMLCanvasElement} The canvas.
 */
export function createCanvas(width = 2, height = 2, fillStyle = 'rgba(255, 0, 0, 1)') {
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext('2d');
    context.fillStyle = fillStyle;
    context.fillRect(0, 0, width, height);
    return canvas;
}

/**
 * Parses a GLB container produced by GltfExporter.
 *
 * @param {ArrayBuffer} buffer - The GLB data.
 * @returns {object} Parsed header, JSON and binary chunk information.
 */
export function parseGlb(buffer) {
    const view = new DataView(buffer);
    const magic = view.getUint32(0, true);
    const version = view.getUint32(4, true);
    const length = view.getUint32(8, true);

    const jsonChunkLength = view.getUint32(12, true);
    const jsonChunkType = view.getUint32(16, true);
    const jsonText = new TextDecoder().decode(new Uint8Array(buffer, 20, jsonChunkLength));
    const json = JSON.parse(jsonText);

    let binary = null;
    const binaryChunkOffset = 20 + jsonChunkLength;
    if (binaryChunkOffset < length) {
        const binaryChunkLength = view.getUint32(binaryChunkOffset, true);
        const binaryChunkType = view.getUint32(binaryChunkOffset + 4, true);
        binary = {
            length: binaryChunkLength,
            type: binaryChunkType,
            data: new Uint8Array(buffer, binaryChunkOffset + 8, binaryChunkLength)
        };
    }

    return {
        magic,
        version,
        length,
        jsonChunkLength,
        jsonChunkType,
        json,
        binary
    };
}
