import {
    afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, jest
} from '@jest/globals';

import { CoreExporter } from '../../../src/extras/exporters/core-exporter.js';
import { Color } from '../../../src/core/math/color.js';
import { Texture } from '../../../src/platform/graphics/texture.js';
import {
    createCanvas, createDevice, setupDom, teardownDom
} from './helpers.js';

describe('CoreExporter', () => {
    let exporter;
    let device;

    beforeAll(() => {
        setupDom();
    });

    afterAll(() => {
        teardownDom();
    });

    beforeEach(() => {
        exporter = new CoreExporter();
        device = createDevice();
    });

    afterEach(() => {
        device.destroy();
    });

    describe('#calcTextureSize()', () => {

        it('returns the original dimensions when no maximum size is supplied', () => {
            expect(exporter.calcTextureSize(128, 64)).toEqual({ width: 128, height: 64 });
        });

        it('scales the longest side down to the maximum size and keeps the aspect ratio', () => {
            expect(exporter.calcTextureSize(100, 50, 25)).toEqual({ width: 25, height: 13 });
            expect(exporter.calcTextureSize(50, 100, 25)).toEqual({ width: 13, height: 25 });
        });

        it('does not upscale textures that are already smaller than the maximum', () => {
            expect(exporter.calcTextureSize(100, 50, 200)).toEqual({ width: 100, height: 50 });
        });

        it('ignores a zero maximum size', () => {
            expect(exporter.calcTextureSize(100, 50, 0)).toEqual({ width: 100, height: 50 });
        });

        it('rounds fractional scaled dimensions', () => {
            expect(exporter.calcTextureSize(3, 3, 2)).toEqual({ width: 2, height: 2 });
        });
    });

    describe('#textureToCanvas()', () => {

        function createTextureFromCanvas(canvas, name = 'texture') {
            const texture = new Texture(device, {
                name,
                width: canvas.width,
                height: canvas.height
            });
            texture.setSource(canvas);
            return texture;
        }

        it('copies a canvas backed texture into a new canvas of the same size', async () => {
            const source = createCanvas(4, 2, 'rgba(200, 100, 50, 255)');
            const texture = createTextureFromCanvas(source);

            const result = await exporter.textureToCanvas(texture);

            expect(result).toBeInstanceOf(HTMLCanvasElement);
            expect(result).not.toBe(source);
            expect(result.width).toBe(4);
            expect(result.height).toBe(2);

            const pixel = result.getContext('2d').getImageData(0, 0, 1, 1).data;
            expect(Array.from(pixel)).toEqual([200, 100, 50, 255]);
        });

        it('resizes the output canvas when maxTextureSize is supplied', async () => {
            const source = createCanvas(8, 4, 'rgba(10, 20, 30, 255)');
            const texture = createTextureFromCanvas(source);

            const result = await exporter.textureToCanvas(texture, { maxTextureSize: 2 });

            expect(result.width).toBe(2);
            expect(result.height).toBe(1);
        });

        it('multiplies the rgb channels by the tint color', async () => {
            const source = createCanvas(2, 2, 'rgba(200, 100, 50, 255)');
            const texture = createTextureFromCanvas(source);

            const result = await exporter.textureToCanvas(texture, {
                color: new Color(0.5, 0.5, 0.5, 1)
            });

            const pixel = result.getContext('2d').getImageData(0, 0, 1, 1).data;
            expect(Array.from(pixel)).toEqual([100, 50, 25, 255]);
        });

        it('leaves the alpha channel untouched when tinting', async () => {
            const source = createCanvas(2, 2, 'rgba(200, 100, 50, 0.5)');
            const texture = createTextureFromCanvas(source);
            const originalAlpha = source.getContext('2d').getImageData(0, 0, 1, 1).data[3];

            const result = await exporter.textureToCanvas(texture, {
                color: new Color(0.5, 1, 1, 1)
            });

            const pixel = result.getContext('2d').getImageData(0, 0, 1, 1).data;
            expect(Array.from(pixel)).toEqual([100, 100, 50, originalAlpha]);
        });

        it('resolves undefined when a 2d context cannot be created', async () => {
            const source = createCanvas(2, 2);
            const texture = createTextureFromCanvas(source);
            const spy = jest.spyOn(HTMLCanvasElement.prototype, 'getContext').mockReturnValue(null);

            try {
                await expect(exporter.textureToCanvas(texture)).resolves.toBeUndefined();
            } finally {
                spy.mockRestore();
            }
        });
    });
});
