                componentType: UNSIGNED_SHORT,
                count: 3
            });
            expect(json.bufferViews[indexAccessor.bufferView].target).toBe(ELEMENT_ARRAY_BUFFER);
            expect(json.buffers[0].byteLength % 4).toBe(0);
        });

        it('writes the entity hierarchy with local transforms and child indices', async () => {
            const mesh = createTriangleMesh(device);
            const material = createMaterial({ useMetalness: true });
