        it('exports unlit materials using the emissive color as base color', async () => {
            const mesh = createTriangleMesh(device);
            const material = createMaterial({
                useMetalness: true,
                useLighting: false,
                diffuse: new Color(1, 1, 1),
                emissive: new Color(0, 0, 1)
            });

