            mesh.setVertexStream(SEMANTIC_BLENDINDICES, [0, 0, 0, 0, 0, 0], 2);
            mesh.setVertexStream(SEMANTIC_BLENDWEIGHT, [1, 0, 1, 0, 1, 0], 2);
            mesh.update();

            mesh.skin = {
                inverseBindPose: [new Mat4()],
                boneNames: ['bone']
            };

            const root = createEntity('root');
            const bone = createEntity('bone');
            root.addChild(bone);
            const skinned = createEntity('skinned');
            root.addChild(skinned);
            attachRender(skinned, [meshInstance(mesh, createMaterial({ useMetalness: true }), skinned)]);

            const parsed = parseGlb(await exporter.build(root));
            const { json } = parsed;
            const boneIndex = json.nodes.findIndex(node => node.name === 'bone');
            const skinnedNode = json.nodes.find(node => node.name === 'skinned');

            expect(skinnedNode.skin).toBe(0);
            expect(json.skins).toEqual([{
                inverseBindMatrices: json.accessors.length - 1,
                joints: [boneIndex]
            }]);
            expect(json.accessors[json.skins[0].inverseBindMatrices]).toMatchObject({
                type: 'MAT4',
                componentType: FLOAT,
                count: 1
            });
            expect(json.meshes[0].primitives[0].attributes).toHaveProperty('JOINTS_0');
            expect(json.meshes[0].primitives[0].attributes).toHaveProperty('WEIGHTS_0');
        });
    });

    describe('#getPaddedArrayBuffer()', () => {

        it('pads a buffer to a four byte boundary', () => {
            const source = new Uint8Array([1, 2, 3, 4, 5]).buffer;
            const padded = exporter.getPaddedArrayBuffer(source);

            expect(padded.byteLength).toBe(8);
            expect(Array.from(new Uint8Array(padded))).toEqual([1, 2, 3, 4, 5, 0, 0, 0]);
        });

        it('uses the requested padding byte', () => {
            const source = new Uint8Array([1, 2, 3, 4, 5]).buffer;
            const padded = exporter.getPaddedArrayBuffer(source, 0xff);

            expect(padded.byteLength).toBe(8);
            expect(Array.from(new Uint8Array(padded))).toEqual([1, 2, 3, 4, 5, 0xff, 0xff, 0xff]);
        });

        it('returns an already aligned buffer unchanged', () => {
            const source = new Uint8Array([1, 2, 3, 4]).buffer;
            expect(exporter.getPaddedArrayBuffer(source)).toBe(source);
        });
    });
});
