from pathlib import Path
p=Path('/testbed/test/framework/components/element/test-utils.js')
s=p.read_text()
addition = '''
/**
 * Creates a deterministic fake bitmap font. Each glyph is 8x8 units and advances 8 units, which
 * makes text layout results easy to reason about.
 */
function createFakeFont({ type = 'bitmap', advance = 8, size = 8, textures = [{ width: 128, height: 128 }] } = {}) {
    const chars = {};
    const characterSource = ' abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,!?-[]"\\\\/';
    for (const character of characterSource) {
        chars[character] = {
            width: size,
            height: size,
            xadvance: advance,
            xoffset: 0,
            yoffset: 0,
            map: 0
        };
    }

    return {
        type,
        intensity: 1,
        textures,
        data: {
            info: {
                face: 'test-font',
                maps: textures.map(texture => ({ width: texture.width, height: texture.height }))
            },
            chars
        }
    };
}
'''
s=s.replace("export {\n    FakeAssetRegistry,", addition + "\nexport {\n    FakeAssetRegistry,")
s=s.replace("    createFakeScreen,", "    createFakeFont,\n    createFakeScreen,")
p.write_text(s)
PY
cd /testbed && node -e "import('./test/framework/components/element/test-utils.js').then(m=>{const f=m.createFakeFont(); console.log(Object.keys(f.data.chars).length, f.data.chars['a']);})""}

