import { Markup } from '../../../../src/framework/components/element/markup.js';

const symbols = text => Array.from(text);

describe('Markup.evaluate', () => {
    describe('plain text', () => {
        it('returns the input symbols and null tags when the text has no markup', () => {
            const result = Markup.evaluate(symbols('Hello'));

            expect(result.symbols).toEqual(symbols('Hello'));
            expect(result.tags).toBeNull();
        });

        it('returns an empty symbol list for empty text', () => {
            const result = Markup.evaluate([]);

            expect(result.symbols).toEqual([]);
            expect(result.tags).toBeNull();
        });

        it('removes escaped opening brackets from the output', () => {
            const result = Markup.evaluate(symbols('\\[not a tag]'));

            expect(result.symbols.join('')).toBe('[not a tag]');
            expect(result.tags).toBeNull();
        });
    });

    describe('color tags', () => {
        it('strips a color tag and applies its value to every enclosed symbol', () => {
            const result = Markup.evaluate(symbols('[color="#ff0000"]red[/color]'));

            expect(result.symbols.join('')).toBe('red');
            expect(result.tags).toHaveLength(3);
            for (const tag of result.tags) {
                expect(tag.color.value).toBe('#ff0000');
                expect(tag.color.attributes).toEqual({});
            }
        });

        it('lets an inner tag override an outer tag only for its own range', () => {
            const result = Markup.evaluate(symbols('[color="#ff0000"]a[color="#00ff00"]b[/color]c[/color]'));

            expect(result.symbols).toEqual(['a', 'b', 'c']);
            expect(result.tags[0].color.value).toBe('#ff0000');
            expect(result.tags[1].color.value).toBe('#00ff00');
            expect(result.tags[2].color.value).toBe('#ff0000');
        });

        it('applies tags to the correct symbol indices', () => {
            const result = Markup.evaluate(symbols('a[color="#0000ff"]bc[/color]'));

            expect(result.symbols).toEqual(['a', 'b', 'c']);
            expect(result.tags[0]).toBeNull();
            expect(result.tags[1].color.value).toBe('#0000ff');
            expect(result.tags[2].color.value).toBe('#0000ff');
        });
    });

    describe('attribute tags', () => {
        it('captures outline attributes', () => {
            const result = Markup.evaluate(symbols('[outline color="#ffffff" thickness="0.5"]x[/outline]'));

            expect(result.symbols).toEqual(['x']);
            expect(result.tags[0].outline.value).toBeNull();
            expect(result.tags[0].outline.attributes).toEqual({
                color: '#ffffff',
                thickness: '0.5'
            });
        });

        it('captures shadow attributes', () => {
            const result = Markup.evaluate(symbols('[shadow color="#000000" offsetX="0.1" offsetY="0.2"]x[/shadow]'));

            expect(result.symbols).toEqual(['x']);
            expect(result.tags[0].shadow.attributes).toEqual({
                color: '#000000',
                offsetX: '0.1',
                offsetY: '0.2'
            });
        });

        it('keeps unrelated nested tags on the same symbol', () => {
            const result = Markup.evaluate(symbols('[color="#ff0000"][outline thickness="1"]x[/outline][/color]'));

            expect(result.symbols).toEqual(['x']);
            expect(result.tags[0].color.value).toBe('#ff0000');
            expect(result.tags[0].outline.attributes.thickness).toBe('1');
        });
    });

    describe('invalid markup', () => {
        it('warns and returns the original symbols for an unclosed tag', () => {
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
            const input = symbols('[color="#ff0000"]unclosed');

            const result = Markup.evaluate(input);

            expect(result.symbols).toEqual(input);
            expect(result.tags).toBeNull();
            expect(warn).toHaveBeenCalledWith(expect.stringContaining('unclosed tag'));
            warn.mockRestore();
        });

        it('warns and returns the original symbols for an unquoted attribute value', () => {
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
            const input = symbols('[color=red]x[/color]');

            const result = Markup.evaluate(input);

            expect(result.symbols).toEqual(input);
            expect(result.tags).toBeNull();
            expect(warn).toHaveBeenCalled();
            warn.mockRestore();
        });

        it('warns and returns the original symbols for a closing tag with no opener', () => {
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});
            const input = symbols('[/color]');

            const result = Markup.evaluate(input);

            expect(result.symbols).toEqual(input);
            expect(result.tags).toBeNull();
            expect(warn).toHaveBeenCalledWith(expect.stringContaining('matching tag'));
            warn.mockRestore();
        });
    });
});
