import {
    FakeLayer,
    createElement,
    createEnabledEntity,
    createFakeScreen,
    createTestApp
} from './test-utils.js';

/**
 * Builds a 400x200 parent element and a child element that exactly fills it through split
 * anchors and zero margins.
 */
function createSizedChild(app) {
    const parentEntity = new Entity('parent', app);
    const parent = parentEntity.addComponent('element', { width: 400, height: 200 });

    const entity = new Entity('child', app);
    parentEntity.addChild(entity);
    const component = entity.addComponent('element');
    component.margin = new Vec4(0, 0, 0, 0);
    component.anchor = [0, 0, 1, 1];

    return { parentEntity, parent, entity, component };
}

describe('ElementComponent', () => {
    describe('construction', () => {
        it('starts as a group element with the documented defaults', () => {
            const app = createTestApp();
            const { component } = createElement(app);

            expect(component.type).toBe(ELEMENTTYPE_GROUP);
            expect(component.width).toBe(32);
            expect(component.height).toBe(32);
            expect(component.calculatedWidth).toBe(32);
            expect(component.calculatedHeight).toBe(32);
            expect(component.anchor).toEqual(new Vec4(0, 0, 0, 0));
            expect(component.pivot).toEqual(new Vec2(0, 0));
            expect(component.margin).toEqual(new Vec4(0, 0, -32, -32));
            expect(component.drawOrder).toBe(0);
            expect(component.batchGroupId).toBe(-1);
            expect(component.useInput).toBe(false);
            expect(component.layers).toEqual([LAYERID_UI]);
            expect(component.screen).toBeNull();
            expect(component.aabb).toBeNull();
        });

        it('returns null for content-specific properties on a group element', () => {
            const app = createTestApp();
            const { component } = createElement(app);

            expect(component.color).toBeNull();
            expect(component.opacity).toBeNull();
            expect(component.text).toBeNull();
            expect(component.fontSize).toBeNull();
            expect(component.texture).toBeNull();
            expect(component.rect).toBeNull();
            expect(component.lines).toBeNull();
            expect(component.textWidth).toBe(0);
            expect(component.textHeight).toBe(0);
        });

        it('patches the entity position setters until the component is removed', () => {
            const app = createTestApp();
            const { entity, component } = createElement(app);

            expect(entity.setLocalPosition).toBe(component._setLocalPosition);
            expect(entity.setPosition).toBe(component._setPosition);

            entity.removeComponent('element');

            expect(entity.setLocalPosition).toBe(Entity.prototype.setLocalPosition);
            expect(entity.setPosition).toBe(Entity.prototype.setPosition);
        });
    });

    describe('#width and #height', () => {
        it('updates the calculated size and margins when set on a point anchor', () => {
            const app = createTestApp();
            const { component } = createElement(app);

            component.width = 100;
            component.height = 50;

            expect(component.width).toBe(100);
            expect(component.height).toBe(50);
            expect(component.calculatedWidth).toBe(100);
            expect(component.calculatedHeight).toBe(50);
            expect(component.margin).toEqual(new Vec4(0, 0, -100, -50));
        });

        it('fires set:width, set:calculatedWidth and resize events', () => {
            const app = createTestApp();
            const { component } = createElement(app);
            const events = [];

            component.on('set:width', width => events.push(['width', width]));
