{"command": "cat > /testbed/test/framework/components/element/image-element.test.js <<'EOF'
import { Color } from '../../../../src/core/math/color.js';
import { Vec2 } from '../../../../src/core/math/vec2.js';
import { Vec4 } from '../../../../src/core/math/vec4.js';
import { EventHandler } from '../../../../src/core/event-handler.js';
import { Entity } from '../../../../src/framework/entity.js';
import { Texture } from '../../../../src/platform/graphics/texture.js';
import { StandardMaterial } from '../../../../src/scene/materials/standard-material.js';
import { Mesh } from '../../../../src/scene/mesh.js';
import { SPRITE_RENDERMODE_SIMPLE, SPRITE_RENDERMODE_SLICED } from '../../../../src/scene/constants.js';
import { ELEMENTTYPE_IMAGE } from '../../../../src/framework/components/element/constants.js';
import {
    createAsset,
    createElement,
    createFakeScreen,
    createTestApp
} from './test-utils.js';

function createSprite(app, { renderMode = SPRITE_RENDERMODE_SIMPLE, frames = ['f0', 'f1'], pixelWidth = 256, pixelHeight = 256 } = {}) {
    const sprite = new EventHandler();
    sprite.renderMode = renderMode;
    sprite.frameKeys = frames;
    sprite.pixelsPerUnit = 100;
    sprite.atlas = new EventHandler();
    sprite.atlas.texture = { width: pixelWidth, height: pixelHeight };
    sprite.atlas.frames = {};
    for (let i = 0; i < frames.length; i++) {
        sprite.atlas.frames[frames[i]] = {
            rect: new Vec4(i * 64, 0, 64, 64),
            border: new Vec4(0, 0, 0, 0)
        };
    }
    sprite.meshes = frames.map(() => new Mesh(app.graphicsDevice));
    return sprite;
}

function readVertexData(mesh) {
    const data = new Float32Array(mesh.vertexBuffer.lock());
    mesh.vertexBuffer.unlock();
    return data;
}

describe('ImageElement', () => {
    describe('initialization', () => {
        it('uses image defaults', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });

            expect(component.type).toBe(ELEMENTTYPE_IMAGE);
            expect(component.color).toEqual(new Color(1, 1, 1, 1));
            expect(component.opacity).toBe(1);
            expect(component.rect).toEqual(new Vec4(0, 0, 1, 1));
            expect(component.texture).toBeNull();
            expect(component.textureAsset).toBeNull();
            expect(component.sprite).toBeNull();
            expect(component.spriteAsset).toBeNull();
            expect(component.spriteFrame).toBe(0);
            expect(component.pixelsPerUnit).toBeNull();
            expect(component.mask).toBe(false);
            expect(component.fitMode).toBe('stretch');
            expect(component.material).toBe(component.system.defaultImageMaterial);
            expect(component.material.name).toBe('defaultImageMaterial');
            expect(component.aabb).not.toBeNull();
        });
    });

    describe('#color and #opacity', () => {
        it('changes only the RGB channels through color and keeps opacity separate', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });
            const colors = [];
            const opacities = [];
            component.on('set:color', color => colors.push(color.clone()));
            component.on('set:opacity', opacity => opacities.push(opacity));

            component.color = new Color(1, 0, 0, 0.25);

            expect(component.color.r).toBe(1);
            expect(component.color.g).toBe(0);
            expect(component.color.b).toBe(0);
            expect(component.opacity).toBe(1);
            expect(colors[0]).toEqual(new Color(1, 0, 0, 1));

            component.opacity = 0.4;

            expect(component.opacity).toBe(0.4);
            expect(opacities).toEqual([0.4]);
        });

        it('writes color and opacity into the mesh instance color uniform', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });
            const meshColor = () => component._image._renderable.meshInstance.parameters.get('mesh_color').data;

            component.color = new Color(1, 0, 0);

            expect(Array.from(meshColor())).toEqual([1, 0, 0, 1]);

            component.opacity = 0.5;

            expect(Array.from(meshColor())).toEqual([1, 0, 0, 0.5]);
        });
    });

    describe('#rect', () => {
        it('accepts an array and updates the mesh texture coordinates', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE, width: 100, height: 100 });

            component.rect = [0.25, 0.25, 0.5, 0.5];

            expect(component.rect).toEqual(new Vec4(0.25, 0.25, 0.5, 0.5));

            const vertexData = readVertexData(component._image.mesh);
            expect(vertexData[6]).toBeCloseTo(0.75);
            expect(vertexData[14]).toBeCloseTo(0.75);
            expect(vertexData[22]).toBeCloseTo(0.25);
            expect(vertexData[30]).toBeCloseTo(0.25);
        });

        it('accepts a Vec4', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });

            component.rect = new Vec4(0.1, 0.2, 0.3, 0.4);

            expect(component.rect).toEqual(new Vec4(0.1, 0.2, 0.3, 0.4));
        });
    });

    describe('#texture', () => {
        it('stores a texture and sets it on the default material parameters', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });
            const texture = new Texture(app.graphicsDevice, { width: 32, height: 16, name: 'test-texture' });

            component.texture = texture;

            expect(component.texture).toBe(texture);
            const parameters = component._image._renderable.meshInstance.parameters;
            expect(parameters.get('texture_emissiveMap').data).toBe(texture);
            expect(parameters.get('texture_opacityMap').data).toBe(texture);
        });

        it('preserves the aspect ratio in contain mode when a texture is assigned', () => {
            const app = createTestApp();
            const { component } = createElement(app, {
                type: ELEMENTTYPE_IMAGE,
                width: 100,
                height: 100,
                fitMode: 'contain'
            });
            const texture = new Texture(app.graphicsDevice, { width: 200, height: 100, name: 'wide' });

            component.texture = texture;

            expect(component.aabb.halfExtents.x).toBeCloseTo(50);
            expect(component.aabb.halfExtents.y).toBeCloseTo(25);
        });

        it('returns to a stretched mesh when the texture is cleared', () => {
            const app = createTestApp();
            const { component } = createElement(app, {
                type: ELEMENTTYPE_IMAGE,
                width: 100,
                height: 100,
