{"command": "cat > /testbed/test/framework/components/element/text-element.test.js <<'EOF'
import { Color } from '../../../../src/core/math/color.js';
import { Vec2 } from '../../../../src/core/math/vec2.js';
import { ELEMENTTYPE_TEXT } from '../../../../src/framework/components/element/constants.js';
import {
    createAsset,
    createElement,
    createFakeFont,
    createTestApp
} from './test-utils.js';

function createText(app, data = {}, options) {
    return createElement(app, { type: ELEMENTTYPE_TEXT, ...data }, options).component;
}

function silenceWarnings(callback) {
    const warnings = [];
    const originalWarn = console.warn;
    console.warn = (...args) => warnings.push(args.join(' '));
    try {
        callback();
    } finally {
        console.warn = originalWarn;
    }
    return warnings;
}

describe('TextElement', () => {
    describe('initialization', () => {
        it('uses text defaults before a font is assigned', () => {
            const app = createTestApp();
            const component = createText(app);

            expect(component.type).toBe(ELEMENTTYPE_TEXT);
            expect(component.text).toBe('');
            expect(component.key).toBeNull();
            expect(component.font).toBeNull();
            expect(component.fontSize).toBe(32);
            expect(component.minFontSize).toBe(8);
            expect(component.maxFontSize).toBe(32);
            expect(component.lineHeight).toBe(32);
            expect(component.spacing).toBe(1);
            expect(component.letterSpacing).toBe(0);
            expect(component.wrapLines).toBe(false);
            expect(component.justify).toBe(false);
            expect(component.autoWidth).toBe(true);
            expect(component.autoHeight).toBe(true);
            expect(component.alignment).toEqual(new Vec2(0.5, 0.5));
            expect(component.color).toEqual(new Color(1, 1, 1, 1));
            expect(component.opacity).toBe(1);
            expect(component.outlineThickness).toBe(0);
            expect(component.shadowOffset).toEqual(new Vec2(0, 0));
            expect(component.enableMarkup).toBe(false);
            expect(component.rtlReorder).toBe(false);
            expect(component.unicodeConverter).toBe(false);
            expect(component.lines).toBeUndefined();
            expect(component.textWidth).toBe(0);
            expect(component.textHeight).toBe(0);
        });

        it('keeps the raw symbols unchanged until a font lays the text out', () => {
            const app = createTestApp();
            const component = createText(app);

            component.text = 'abc';

            expect(component.text).toBe('abc');
            expect(component._text.symbols).toEqual([]);
            expect(component.lines).toBeUndefined();
        });
    });

    describe('layout', () => {
        it('lays out text into lines and report the text size', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'abc' });

            expect(component.font).toBe(font);
            expect(component._text.symbols).toEqual(['a', 'b', 'c']);
            expect(component.lines).toEqual(['abc']);
            expect(component.textWidth).toBe(24);
            expect(component.textHeight).toBe(8);
            expect(component.width).toBe(24);
            expect(component.height).toBe(8);
        });

        it('splits lines on explicit line breaks', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'a\nb' });

            expect(component.lines).toEqual(['a', 'b']);
            expect(component.textWidth).toBe(8);
            expect(component.textHeight).toBe(40);
        });

        it('wraps words at the element width when wrapLines is enabled', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, {
                font,
                text: 'a b c d',
                autoWidth: false,
                width: 20,
                wrapLines: true
            });

            expect(component.lines).toEqual(['a ', 'b ', 'c ', 'd']);
        });

        it('limits the number of wrapped lines with maxLines', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, {
                font,
                text: 'a b c d',
                autoWidth: false,
                width: 20,
                wrapLines: true,
                maxLines: 2
            });

            expect(component.lines).toHaveLength(2);
            expect(component.maxLines).toBe(2);
        });

        it('applies spacing between glyphs', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'abc' });

            component.spacing = 2;

            expect(component.spacing).toBe(2);
            expect(component.textWidth).toBe(48);
        });

        it('updates the element size through autoWidth and autoHeight', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'abc' });

            component.autoWidth = false;
            component.autoHeight = false;
            component.text = 'abcdef';

            expect(component.textWidth).toBe(48);
            expect(component.width).toBe(24);
            expect(component.height).toBe(8);

            component.autoWidth = true;

            expect(component.width).toBe(48);
        });

        it('restores the element height through autoHeight', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'a\nb' });
            component.autoWidth = false;
            component.autoHeight = false;
            component.text = 'a\nb\nc';

            expect(component.height).toBe(40);
            expect(component.textHeight).toBe(72);

            component.autoHeight = true;

            expect(component.height).toBe(72);
        });

        it('shrinks the font size to fit a constrained width with autoFitWidth', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, {
                font,
                text: 'abc',
                autoWidth: false,
                width: 10,
                autoFitWidth: true,
                minFontSize: 4,
                maxFontSize: 16
            });

            expect(component.autoFitWidth).toBe(true);
            expect(component.fontSize).toBeGreaterThan(4);
            expect(component.fontSize).toBeLessThan(16);
            expect(component.textWidth).toBeLessThanOrEqual(10);
        });
    });

    describe('text properties', () => {
        it('stores alignment from an array and a Vec2', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'abc' });

            component.alignment = [0, 1];

            expect(component.alignment).toEqual(new Vec2(0, 1));

            component.alignment = new Vec2(0.25, 0.75);

            expect(component.alignment).toEqual(new Vec2(0.25, 0.75));
        });

        it('exposes the remaining layout options through the component', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font });

            component.lineHeight = 20;
            component.wrapLines = true;
            component.justify = true;
            component.letterSpacing = 2;
            component.fontSize = 16;
            component.minFontSize = 4;
            component.maxFontSize = 24;
            component.autoFitWidth = true;
            component.autoFitHeight = true;
            component.rtlReorder = true;
            component.unicodeConverter = true;

            expect(component.lineHeight).toBe(20);
            expect(component.wrapLines).toBe(true);
            expect(component.justify).toBe(true);
            expect(component.letterSpacing).toBe(2);
            expect(component.fontSize).toBe(16);
            expect(component.minFontSize).toBe(4);
            expect(component.maxFontSize).toBe(24);
            expect(component.autoFitWidth).toBe(true);
            expect(component.autoFitHeight).toBe(true);
            expect(component.rtlReorder).toBe(true);
            expect(component.unicodeConverter).toBe(true);
        });
    });

    describe('#color and #opacity', () => {
        it('keeps color alpha separate from opacity and updates the mesh color uniform', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'abc' });
            const meshColor = () => component._text._model.meshInstances[0].parameters.get('mesh_color').data;
            const colors = [];
            const opacities = [];
            component.on('set:color', color => colors.push(color.clone()));
            component.on('set:opacity', opacity => opacities.push(opacity));

            component.color = new Color(1, 0, 0, 0.25);

            expect(component.color).toEqual(new Color(1, 0, 0, 1));
            expect(component.opacity).toBe(1);
            expect(Array.from(meshColor())).toEqual([1, 0, 0, 1]);
            expect(colors).toHaveLength(1);

            component.opacity = 0.5;

            expect(component.opacity).toBe(0.5);
            expect(Array.from(meshColor())).toEqual([1, 0, 0, 0.5]);
            expect(opacities).toEqual([0.5]);
        });
    });

    describe('effects', () => {
        it('applies outline color and thickness to the text mesh instance', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const component = createText(app, { font, text: 'abc' });
            const meshInstance = component._text._model.meshInstances[0];
            const outlines = [];
            component.on('set:outline', color => outlines.push(color.clone()));

