import { Texture } from '../../../../src/platform/graphics/texture.js';
import { PIXELFORMAT_SRGBA8 } from '../../../../src/platform/graphics/constants.js';
import { BLEND_PREMULTIPLIED, LAYERID_UI } from '../../../../src/scene/constants.js';
import { ElementComponent } from '../../../../src/framework/components/element/component.js';
import {
    ELEMENTTYPE_GROUP,
    ELEMENTTYPE_IMAGE,
    ELEMENTTYPE_TEXT
} from '../../../../src/framework/components/element/constants.js';
import {
    createElement,
    createFakeFont,
    createTestApp
} from './test-utils.js';

describe('ElementComponentSystem', () => {
    describe('construction', () => {
        it('registers itself for the element component type', () => {
            const app = createTestApp();
            const system = app.systems.element;

            expect(system.id).toBe('element');
            expect(system.ComponentType).toBe(ElementComponent);
            expect(system._defaultTexture.width).toBe(1);
            expect(system._defaultTexture.height).toBe(1);
            expect(system._defaultTexture.format).toBe(PIXELFORMAT_SRGBA8);
        });

        it('creates default image and text materials lazily', () => {
            const app = createTestApp();
            const system = app.systems.element;

            expect(system.defaultImageMaterial).toBeNull();
            expect(system.defaultImageMaterials).toEqual([]);
            expect(system._defaultTextMaterials).toEqual({});

            const textMaterial = system.getTextElementMaterial(false, false, false);
            const imageMaterial = system.getImageElementMaterial(false, false, false, false);

            expect(textMaterial).toBeTruthy();
            expect(imageMaterial).toBe(system.defaultImageMaterial);
            expect(system.defaultImageMaterials).toContain(imageMaterial);
        });
    });

    describe('component events', () => {
        it('fires add on the system and element:add on the entity', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const entity = new Entity('event-element', app);
            const adds = [];
            const entityEvents = [];
            system.on('add', (eventEntity, component) => adds.push([eventEntity, component]));
            entity.on('element:add', () => entityEvents.push(true));

            const component = entity.addComponent('element');

            expect(adds).toEqual([[entity, component]]);
            expect(entityEvents).toEqual([true]);
        });

        it('fires beforeremove and cleans up the component on removal', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const entity = new Entity('remove-element', app);
            const component = entity.addComponent('element', { type: ELEMENTTYPE_IMAGE });
            const removals = [];
            system.on('beforeremove', (eventEntity, removedComponent) => removals.push([eventEntity, removedComponent]));

            entity.removeComponent('element');

            expect(removals).toEqual([[entity, component]]);
            expect(entity.element).toBeUndefined();
            expect(entity.children).toHaveLength(0);
        });
    });

    describe('initializeComponentData', () => {
        it('initializes image properties from arrays and scalars', () => {
            const app = createTestApp();
            const { component } = createElement(app, {
                type: ELEMENTTYPE_IMAGE,
                anchor: [0, 0, 0, 0],
                pivot: [0.25, 0.75],
                margin: [1, 2, 3, 4],
                width: 50,
                height: 60,
                layers: [LAYERID_UI, 9],
                batchGroupId: null,
                color: [1, 0, 0],
                opacity: 0.5,
                rect: [0, 0, 0.5, 0.5],
                fitMode: 'contain',
                mask: true,
                pixelsPerUnit: 10,
                spriteFrame: 2
            });

            expect(component.type).toBe(ELEMENTTYPE_IMAGE);
            expect(component.anchor).toEqual(new Vec4(0, 0, 0, 0));
            expect(component.pivot).toEqual(new Vec2(0.25, 0.75));
            expect(component.margin).toEqual(new Vec4(1, 2, 3, 4));
            expect(component.width).toBe(50);
            expect(component.height).toBe(60);
            expect(component.layers).toEqual([LAYERID_UI, 9]);
            expect(component.batchGroupId).toBe(-1);
            expect(component.color).toEqual(new Color(1, 0, 0, 1));
            expect(component.opacity).toBe(0.5);
            expect(component.rect).toEqual(new Vec4(0, 0, 0.5, 0.5));
            expect(component.fitMode).toBe('contain');
            expect(component.mask).toBe(true);
            expect(component.pixelsPerUnit).toBe(10);
            expect(component.spriteFrame).toBe(2);
        });

        it('copies the layers array instead of keeping the input reference', () => {
            const app = createTestApp();
            const layers = [LAYERID_UI];
            const { component } = createElement(app, { layers });

            expect(component.layers).toEqual(layers);
            expect(component.layers).not.toBe(layers);
        });

        it('resizes a split-anchor child to the parent bounds during initialization', () => {
            const app = createTestApp();
            const parentEntity = new Entity('parent', app);
            parentEntity.addComponent('element', { width: 400, height: 200 });
            const childEntity = new Entity('child', app);
            parentEntity.addChild(childEntity);

            const component = childEntity.addComponent('element', {
                anchor: [0, 0, 1, 1],
                margin: [0, 0, 0, 0],
                width: 123,
                height: 456
            });

            expect(component.calculatedWidth).toBe(400);
            expect(component.calculatedHeight).toBe(200);
            expect(component.width).toBe(400);
            expect(component.height).toBe(200);
        });

        it('keeps an explicit width and height for a point anchor', () => {
            const app = createTestApp();
            const { component } = createElement(app, { width: 123, height: 456 });

            expect(component.width).toBe(123);
            expect(component.height).toBe(456);
            expect(component.calculatedWidth).toBe(123);
            expect(component.calculatedHeight).toBe(456);
        });

        it('initializes text properties', () => {
            const app = createTestApp();
            const font = createFakeFont();
            const { component } = createElement(app, {
                type: ELEMENTTYPE_TEXT,
                font,
                text: 'Hello',
                autoWidth: false,
                autoHeight: false,
                color: [0, 1, 0],
                opacity: 0.4,
                alignment: [1, 0],
                spacing: 2,
                letterSpacing: 3,
                lineHeight: 20,
                wrapLines: true,
                justify: true,
                fontSize: 16,
                minFontSize: 4,
                maxFontSize: 24,
                maxLines: 2,
                enableMarkup: true,
                outlineColor: [1, 1, 0, 1],
                outlineThickness: 0.3,
                shadowColor: [0, 0, 1, 1],
                shadowOffset: [0.2, 0.3]
            });

            expect(component.type).toBe(ELEMENTTYPE_TEXT);
            expect(component.text).toBe('Hello');
            expect(component.autoWidth).toBe(false);
            expect(component.autoHeight).toBe(false);
            expect(component.color).toEqual(new Color(0, 1, 0, 1));
            expect(component.opacity).toBe(0.4);
            expect(component.alignment).toEqual(new Vec2(1, 0));
            expect(component.spacing).toBe(2);
            expect(component.letterSpacing).toBe(3);
            expect(component.lineHeight).toBe(20);
            expect(component.wrapLines).toBe(true);
            expect(component.justify).toBe(true);
            expect(component.fontSize).toBe(16);
            expect(component.minFontSize).toBe(4);
            expect(component.maxFontSize).toBe(24);
            expect(component.maxLines).toBe(2);
            expect(component.enableMarkup).toBe(true);
            expect(component.outlineColor).toEqual(new Color(1, 1, 0, 1));
            expect(component.outlineThickness).toBe(0.3);
            expect(component.shadowColor).toEqual(new Color(0, 0, 1, 1));
            expect(component.shadowOffset).toEqual(new Vec2(0.2, 0.3));
        });

        it('uses text instead of key when both are supplied', () => {
            const app = createTestApp();
            app.i18n.addData({
                header: { version: 1 },
                data: [{ info: { locale: 'en-US' }, messages: { hello: 'Hello' } }]
            });

            const { component } = createElement(app, {
                type: ELEMENTTYPE_TEXT,
                text: 'Literal',
                key: 'hello'
            });

            expect(component.text).toBe('Literal');
            expect(component.key).toBeNull();
        });

        it('uses the localization key when text is not supplied', () => {
            const app = createTestApp();
            app.i18n.addData({
                header: { version: 1 },
                data: [{ info: { locale: 'en-US' }, messages: { hello: 'Hello' } }]
            });

            const { component } = createElement(app, {
                type: ELEMENTTYPE_TEXT,
                text: null,
                key: 'hello'
            });

            expect(component.key).toBe('hello');
            expect(component.text).toBe('Hello');
        });

        it('applies a directly supplied image material and texture', () => {
            const app = createTestApp();
            const material = new StandardMaterial();
            material.name = 'direct-material';
            material.blendType = 2;
            material.update();
            const texture = new Texture(app.graphicsDevice, { width: 4, height: 4, name: 'direct-texture' });

            const { component } = createElement(app, {
                type: ELEMENTTYPE_IMAGE,
                material,
                texture
            });

            expect(component.material).toBe(material);
            expect(component.texture).toBe(texture);
        });

        it('applies enabled, useInput and batch group values', () => {
            const app = createTestApp();
            const input = {
                added: [],
                removed: [],
                addElement(element) { this.added.push(element); },
                removeElement(element) { this.removed.push(element); }
            };
            app.elementInput = input;
            const { component } = createElement(app, {
                enabled: false,
                useInput: true,
                batchGroupId: 4
            });

            expect(component.enabled).toBe(false);
            expect(component.useInput).toBe(true);
            expect(component.batchGroupId).toBe(4);
            expect(input.added).toHaveLength(0);
        });
    });

    describe('cloneComponent', () => {
        it('clones image element data into independent objects', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const { entity: sourceEntity, component: source } = createElement(app, {
                type: ELEMENTTYPE_IMAGE,
                width: 11,
                height: 12,
                anchor: new Vec4(0.1, 0.2, 0.3, 0.4),
                pivot: new Vec2(0.2, 0.3),
                margin: new Vec4(1, 2, 3, 4),
                color: new Color(0.5, 0.25, 0.125),
                opacity: 0.7,
                rect: new Vec4(0, 0, 0.5, 0.5),
                fitMode: 'cover',
                mask: true,
                batchGroupId: 3
            });
            source.layers = [LAYERID_UI];
            const cloneEntity = new Entity('clone', app);

            const clone = system.cloneComponent(sourceEntity, cloneEntity);

            expect(clone).not.toBe(source);
            expect(clone.type).toBe(ELEMENTTYPE_IMAGE);
            expect(clone.width).toBe(11);
            expect(clone.height).toBe(12);
            expect(clone.anchor).toEqual(source.anchor);
            expect(clone.pivot).toEqual(source.pivot);
            expect(clone.margin).toEqual(source.margin);
            expect(clone.color).toEqual(source.color);
            expect(clone.opacity).toBe(0.7);
            expect(clone.rect).toEqual(source.rect);
            expect(clone.fitMode).toBe('cover');
            expect(clone.mask).toBe(true);
            expect(clone.layers).toEqual([LAYERID_UI]);
            expect(clone.batchGroupId).toBe(3);

            expect(clone.anchor).not.toBe(source.anchor);
            expect(clone.pivot).not.toBe(source.pivot);
            expect(clone.margin).not.toBe(source.margin);
            expect(clone.color).not.toBe(source.color);
            expect(clone.rect).not.toBe(source.rect);
            expect(clone.layers).not.toBe(source.layers);
        });

        it('clones text and keeps a localized key', () => {
            const app = createTestApp();
            const system = app.systems.element;
            app.i18n.addData({
                header: { version: 1 },
                data: [{ info: { locale: 'en-US' }, messages: { hello: 'Hello' } }]
            });
            const { entity: sourceEntity } = createElement(app, {
                type: ELEMENTTYPE_TEXT,
                key: 'hello',
                width: 20,
                height: 30
            });
            const cloneEntity = new Entity('clone', app);

            const clone = system.cloneComponent(sourceEntity, cloneEntity);

            expect(clone.type).toBe(ELEMENTTYPE_TEXT);
            expect(clone.key).toBe('hello');
            expect(clone.text).toBe('Hello');
            expect(clone.width).toBe(20);
            expect(clone.height).toBe(30);
        });

        it('clones a literal text element', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const { entity: sourceEntity } = createElement(app, {
                type: ELEMENTTYPE_TEXT,
                text: 'Literal text'
            });
            const cloneEntity = new Entity('clone', app);

            const clone = system.cloneComponent(sourceEntity, cloneEntity);

            expect(clone.text).toBe('Literal text');
            expect(clone.key).toBeNull();
        });
    });

    describe('material caches', () => {
        it('returns a cached text material per flag combination', () => {
            const app = createTestApp();
            const system = app.systems.element;

            const bitmap = system.getTextElementMaterial(false, false, false);
            expect(system.getTextElementMaterial(false, false, false)).toBe(bitmap);
            expect(bitmap.name).toBe('defaultBitmapTextMaterial');
            expect(bitmap.emissiveMap).toBe(system._defaultTexture);
            expect(bitmap.opacityMap).toBe(system._defaultTexture);
            expect(bitmap.opacityMapChannel).toBe('a');
            expect(bitmap.blendType).toBe(BLEND_PREMULTIPLIED);
            expect(bitmap.depthWrite).toBe(false);
            expect(bitmap.useLighting).toBe(false);
            expect(bitmap.useFog).toBe(false);
            expect(bitmap.useSkybox).toBe(false);

            const screenSpace = system.getTextElementMaterial(true, false, false);
            expect(screenSpace.name).toBe('defaultScreenSpaceBitmapTextMaterial');
            expect(screenSpace.depthTest).toBe(false);
            expect(screenSpace).not.toBe(bitmap);

            const msdf = system.getTextElementMaterial(false, true, true);
            expect(msdf.name).toBe('defaultTextMaterial');
            expect(msdf.msdfMap).toBe(system._defaultTexture);
            expect(msdf.msdfTextAttribute).toBe(true);
            expect(msdf.emissive).toEqual(new Color(1, 1, 1, 1));
        });

        it('returns a cached image material for every screen/mask/slicing combination', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const cases = [
                [false, false, false, false, 'defaultImageMaterial'],
                [false, false, true, false, 'defaultImage9SlicedMaterial'],
                [false, false, false, true, 'defaultImage9TiledMaterial'],
                [false, true, false, false, 'defaultImageMaskMaterial'],
                [false, true, true, false, 'defaultImage9SlicedMaskMaterial'],
                [false, true, false, true, 'defaultImage9TiledMaskMaterial'],
                [true, false, false, false, 'defaultScreenSpaceImageMaterial'],
                [true, false, true, false, 'defaultScreenSpaceImage9SlicedMaterial'],
                [true, false, false, true, 'defaultScreenSpaceImage9TiledMaterial'],
                [true, true, false, false, 'defaultScreenSpaceImageMaskMaterial'],
                [true, true, true, false, 'defaultScreenSpaceImageMask9SlicedMaterial'],
                [true, true, false, true, 'defaultScreenSpaceImageMask9TiledMaterial']
            ];

            for (const [screenSpace, mask, sliced, tiled, name] of cases) {
                const material = system.getImageElementMaterial(screenSpace, mask, sliced, tiled);
                expect(material.name).toBe(name);
                expect(system.getImageElementMaterial(screenSpace, mask, sliced, tiled)).toBe(material);
                expect(system.defaultImageMaterials.filter(item => item === material)).toHaveLength(1);
            }

            expect(system.defaultImageMaterials).toHaveLength(cases.length);
        });

        it('configures mask image materials to write only stencil', () => {
            const app = createTestApp();
            const system = app.systems.element;

            const mask = system.getImageElementMaterial(false, true, false, false);

            expect(mask.alphaTest).toBe(1);
            expect(mask.redWrite).toBe(false);
            expect(mask.greenWrite).toBe(false);
            expect(mask.blueWrite).toBe(false);
            expect(mask.alphaWrite).toBe(false);
            expect(mask.depthWrite).toBe(false);
            expect(mask.blendType).toBe(BLEND_PREMULTIPLIED);
        });
    });

    describe('text conversion registration', () => {
        it('stores and returns the unicode converter', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const converter = text => text.toUpperCase();

            expect(system.getUnicodeConverter()).toBeNull();
            system.registerUnicodeConverter(converter);

            expect(system.getUnicodeConverter()).toBe(converter);
        });

        it('stores and returns the RTL reorder function', () => {
            const app = createTestApp();
            const system = app.systems.element;
            const reorder = symbols => ({ rtl: false, mapping: symbols.map((_, index) => index) });

            expect(system.getRtlReorder()).toBeNull();
            system.registerRtlReorder(reorder);

            expect(system.getRtlReorder()).toBe(reorder);
        });
    });
});
