import { Vec3 } from '../../../../src/core/math/vec3.js';
import { ELEMENTTYPE_IMAGE } from '../../../../src/framework/components/element/constants.js';
import { ElementDragHelper } from '../../../../src/framework/components/element/element-drag-helper.js';
import {
    createElement,
    createFakeScreen,
    createTestApp
} from './test-utils.js';

function createDraggable({ axis, screenSpace = true, mouse = true, screenScale = 1 } = {}) {
    const app = createTestApp();
    if (mouse) {
        app.mouse = {};
    }

    const { entity, component } = createElement(app, { type: ELEMENTTYPE_IMAGE });
    if (screenSpace) {
        component.screen = createFakeScreen(app, { screenSpace: true, scale: screenScale });
    }
    entity._enabledInHierarchy = true;

    const helper = new ElementDragHelper(component, axis);
    return { app, entity, component, helper };
}

const camera = {
    entity: {
        getPosition: () => new Vec3(0, 0, 10)
    },
    screenToWorld: () => new Vec3(0, 0, 0)
};

describe('ElementDragHelper', () => {
    describe('constructor', () => {
        it('exposes the drag event names', () => {
            expect(ElementDragHelper.EVENT_DRAGSTART).toBe('drag:start');
            expect(ElementDragHelper.EVENT_DRAGEND).toBe('drag:end');
            expect(ElementDragHelper.EVENT_DRAGMOVE).toBe('drag:move');
        });

        it('throws when no ElementComponent is supplied', () => {
            expect(() => new ElementDragHelper(null)).toThrow('Element was null or not an ElementComponent');
            expect(() => new ElementDragHelper({})).toThrow('Element was null or not an ElementComponent');
        });

        it('throws for an unsupported axis', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });

            expect(() => new ElementDragHelper(component, 'z')).toThrow('Unrecognized axis: z');
        });

        it('accepts x and y axes and starts enabled', () => {
            const app = createTestApp();
            const { component } = createElement(app, { type: ELEMENTTYPE_IMAGE });

            const xHelper = new ElementDragHelper(component, 'x');
            const yHelper = new ElementDragHelper(component, 'y');

            expect(xHelper._axis).toBe('x');
            expect(yHelper._axis).toBe('y');
            expect(xHelper.enabled).toBe(true);
            expect(xHelper.isDragging).toBe(false);
        });

        it('removes its listeners when destroyed', () => {
            const { component, helper } = createDraggable();

            helper.destroy();
            component.fire('mousedown', { x: 0, y: 0, camera });

            expect(helper.isDragging).toBe(false);
        });
    });

    describe('mouse drag', () => {
        it('moves the element by the screen-space delta and fires start, move and end', () => {
            const { entity, component, helper } = createDraggable();
            const events = [];
            helper.on(ElementDragHelper.EVENT_DRAGSTART, () => events.push('start'));
            helper.on(ElementDragHelper.EVENT_DRAGMOVE, position => events.push(['move', position.x, position.y, position.z]));
            helper.on(ElementDragHelper.EVENT_DRAGEND, () => events.push('end'));

            component.fire('mousedown', { x: 0, y: 0, camera });

            expect(helper.isDragging).toBe(true);
            expect(events).toEqual(['start']);

            component.fire('mousemove', { x: 10, y: 5, camera });

            expect(entity.getLocalPosition().x).toBe(10);
            expect(entity.getLocalPosition().y).toBe(-5);
            expect(events).toEqual(['start', ['move', 10, -5, 0]]);

            component.fire('mouseup', {});

            expect(helper.isDragging).toBe(false);
            expect(events).toEqual(['start', ['move', 10, -5, 0], 'end']);
        });

        it('constrains horizontal drags to the x axis', () => {
            const { entity, component, helper } = createDraggable({ axis: 'x' });

            component.fire('mousedown', { x: 0, y: 0, camera });
            component.fire('mousemove', { x: 10, y: 5, camera });

            expect(entity.getLocalPosition().x).toBe(10);
            expect(entity.getLocalPosition().y).toBe(0);
        });

        it('constrains vertical drags to the y axis', () => {
            const { entity, component, helper } = createDraggable({ axis: 'y' });

            component.fire('mousedown', { x: 0, y: 0, camera });
            component.fire('mousemove', { x: 10, y: 5, camera });

            expect(entity.getLocalPosition().x).toBe(0);
            expect(entity.getLocalPosition().y).toBe(-5);
        });

        it('does not start dragging when the helper is disabled', () => {
            const { component, helper } = createDraggable();
            helper.enabled = false;

            component.fire('mousedown', { x: 0, y: 0, camera });
            expect(helper.isDragging).toBe(false);

            helper.enabled = true;
            component.fire('mousedown', { x: 0, y: 0, camera });
            expect(helper.isDragging).toBe(true);
        });

        it('does not move a disabled element', () => {
            const { entity, component, helper } = createDraggable();

            component.fire('mousedown', { x: 0, y: 0, camera });
            component.enabled = false;
            component.fire('mousemove', { x: 10, y: 5, camera });

            expect(entity.getLocalPosition().x).toBe(0);
            expect(entity.getLocalPosition().y).toBe(0);
        });

        it('ignores mouse events that arrive while no drag is active', () => {
            const { entity, component, helper } = createDraggable();
            let moved = false;
            helper.on(ElementDragHelper.EVENT_DRAGMOVE, () => {
                moved = true;
            });

            component.fire('mousemove', { x: 10, y: 5, camera });

            expect(moved).toBe(false);
            expect(entity.getLocalPosition().x).toBe(0);
        });
    });

    describe('alternative input paths', () => {
        it('uses an XR input source origin and direction', () => {
            const { component, helper } = createDraggable();
            const events = [];
            helper.on(ElementDragHelper.EVENT_DRAGSTART, () => events.push('start'));

            component.fire('mousedown', {
                camera,
                inputSource: {
                    getOrigin: () => new Vec3(0, 0, 10),
                    getDirection: () => new Vec3(0, 0, -1)
                }
            });

            expect(helper.isDragging).toBe(true);
            expect(events).toEqual(['start']);
        });

        it('reads coordinates from changedTouches for touch events', () => {
            const app = createTestApp();
            const { entity, component } = createElement(app, { type: ELEMENTTYPE_IMAGE });
            component.screen = createFakeScreen(app, { screenSpace: true, scale: 1 });
            entity._enabledInHierarchy = true;
            const helper = new ElementDragHelper(component);
            const events = [];
            helper.on(ElementDragHelper.EVENT_DRAGSTART, () => events.push('start'));

            component.fire('touchstart', { changedTouches: [{ x: 4, y: 6 }], camera });

            expect(helper.isDragging).toBe(true);
            expect(events).toEqual(['start']);
        });

        it('applies the inverse screen scale to drag distances', () => {
            const { entity, component, helper } = createDraggable({ screenScale: 2 });

            component.fire('mousedown', { x: 0, y: 0, camera });
            component.fire('mousemove', { x: 20, y: 10, camera });

            expect(entity.getLocalPosition().x).toBe(10);
            expect(entity.getLocalPosition().y).toBe(-5);
        });

        it('uses a camera ray for a world-space element', () => {
            const { component, helper } = createDraggable({ screenSpace: false });
            const events = [];
            helper.on(ElementDragHelper.EVENT_DRAGSTART, () => events.push('start'));

            component.fire('mousedown', { x: 1, y: 2, camera });

            expect(component.screen).toBeNull();
            expect(helper.isDragging).toBe(true);
            expect(events).toEqual(['start']);
        });
    });
});
