/**
 * Minimal in-memory asset registry used by the element tests. It exposes the small part of the
 * AssetRegistry contract the element component uses: lookup by id, add notifications and load().
 */
class FakeAssetRegistry extends EventHandler {
    constructor() {
        super();
        this._assets = new Map();
        this.loaded = [];
    }

    get(id) {
        return this._assets.get(id) ?? null;
    }

    add(asset) {
        this._assets.set(asset.id, asset);
        this.fire(`add:${asset.id}`, asset);
        return asset;
    }

    remove(asset) {
        this._assets.delete(asset.id);
        this.fire(`remove:${asset.id}`, asset);
    }

    load(asset) {
        this.loaded.push(asset);
    }
}

/**
 * A single fake layer recording mesh instances added to it.
 */
class FakeLayer extends EventHandler {
    constructor(id) {
        super();
        this.id = id;
        this.meshInstances = [];
    }

    addMeshInstances(meshInstances) {
        this.meshInstances.push(...meshInstances);
    }

    removeMeshInstances(meshInstances) {
        this.meshInstances = this.meshInstances.filter(mi => !meshInstances.includes(mi));
    }
}

class FakeLayerComposition extends EventHandler {
    constructor() {
        super();
        this._layers = new Map();
    }

    addLayer(layer) {
        this._layers.set(layer.id, layer);
        return layer;
    }

    getLayerById(id) {
