    device.maxPixelRatio = 1;

    const app = new EventHandler();
    app.graphicsDevice = device;
    app.systems = {};
    app.assets = new FakeAssetRegistry();
    app.i18n = new I18n(app);
    app.scene = new EventHandler();
    app.scene.layers = new FakeLayerComposition();
    app.elementInput = null;
