 * Creates an entity that is fully inside the enabled hierarchy. Attaching it to a parent that is
 * itself enabled fires the normal GraphNode hierarchy events, which is what triggers component
 * onEnable/onDisable.
 */
function createEnabledEntity(app, name = 'entity') {
    const parent = new Entity(`${name}-parent`, app);
    parent._enabledInHierarchy = true;
    const entity = new Entity(name, app);
    parent.addChild(entity);
    return entity;
}

/**
 * Creates an element on a new entity.
 */
function createElement(app, data, { enabled = false, name = 'element' } = {}) {
    const entity = enabled ? createEnabledEntity(app, name) : new Entity(name, app);
    const component = entity.addComponent('element', data);
    return { entity, component };
}

