    screen._bindElement = function (element) {
        this.bound.push(element);
    };
    screen._unbindElement = function (element) {
        this.unbound.push(element);
    };
    screen.syncDrawOrder = function () {
        this.syncDrawOrderCalls = (this.syncDrawOrderCalls ?? 0) + 1;
    };

    entity.screen = screen;
    return entity;
