 * Creates a deterministic fake bitmap font. Each glyph is 8x8 units and advances 8 units, which
 * makes text layout results easy to reason about.
 */
function createFakeFont({ type = 'bitmap', advance = 8, size = 8, textures = [{ width: 128, height: 128 }] } = {}) {
    const chars = {};
    const characterSource = Array.from({ length: 95 }, (_, i) => String.fromCharCode(i + 32)).join('');
    for (const character of characterSource) {
        chars[character] = {
            width: size,
            height: size,
            xadvance: advance,
            xoffset: 0,
            yoffset: 0,
            bounds: [0, 0, 8, 8],
            map: 0
        };
    }

    return {
        type,
        intensity: 1,
        textures,
        data: {
            info: {
                face: 'test-font',
                maps: textures.map(texture => ({ width: texture.width, height: texture.height }))
            },
            chars
        }
    };
}

