        if (!format) {
            Debug.error(`This DDS pixel format is currently unsupported. Empty texture will be created instead of ${url}.`);
            texture = new Texture(device, {
                width: 4,
                height: 4,
                format: PIXELFORMAT_RGB8,
                name: 'dds-legacy-empty'
            });
            return texture;
