        let offset = 128;
        const faces = isCubemap ? 6 : 1;
        let mipSize;
        const DXT_BLOCK_WIDTH = 4;
        const DXT_BLOCK_HEIGHT = 4;
        const blockSize = fcc === FCC_DXT1 ? 8 : 16;
