function createFlatHdr(width,height,pixels,{magic='#?RADIANCE', format='32-bit_rle_rgbe', resolution='-Y h +X w'}) {
 const header = `${magic}\nFORMAT=${format}\n\n${resolution}\n`;
 const bytes = new TextEncoder().encode(header);
 const arr = new Uint8Array(bytes.length + pixels.length);
 arr.set(bytes); arr.set(pixels, bytes.length);
 return arr.buffer;
}
