import { afterEach, describe, expect, test, jest } from '@jest/globals';

import {
    ADDRESS_CLAMP_TO_EDGE,
    ADDRESS_REPEAT,
    FILTER_NEAREST,
    PIXELFORMAT_RGBA8,
    TEXTURETYPE_RGBE
} from '../../../../src/platform/graphics/constants.js';
import { Http } from '../../../../src/platform/net/http.js';
import { HdrParser } from '../../../../src/framework/parsers/texture/hdr.js';

import { createDevice, createHandler, createUrl, writeAscii } from './test-helpers.js';

/**
 * Builds a radiance HDR file with raw flat pixel data.
 */
function createFlatHdr({
    width = 4,
    height = 2,
    pixels = null,
    magic = '#?RADIANCE',
    format = '32-bit_rle_rgbe',
    resolution = `-Y ${height} +X ${width}`,
    extraVariables = []
} = {}) {
    const pixelData = pixels ?? new Uint8Array(width * height * 4).map((_, i) => (i + 1) & 0xff);
    const variableLines = [];
    if (format !== null) {
        variableLines.push(`FORMAT=${format}`);
    }
    variableLines.push(...extraVariables);

    const header = `${magic}\n${variableLines.map(line => `${line}\n`).join('')}\n${resolution}\n`;
    const headerBytes = new TextEncoder().encode(header);

    const buffer = new ArrayBuffer(headerBytes.length + pixelData.length);
    const bytes = new Uint8Array(buffer);
    bytes.set(headerBytes, 0);
    bytes.set(pixelData, headerBytes.length);

    return { buffer, pixelOffset: headerBytes.length };
}

/**
 * Builds a single RLE scanline: a 4-byte marker followed by one literal run per channel.
 */
function createRleScanline(width, values) {
    const bytes = [2, 2, (width >> 8) & 0xff, width & 0xff];
    for (let channel = 0; channel < 4; channel++) {
        bytes.push(width);
        for (let x = 0; x < width; x++) {
            bytes.push(values[channel][x]);
        }
    }
    return bytes;
}

/**
 * Builds a radiance HDR file whose scanlines use RGBE RLE encoding.
 */
function createRleHdr(width, height, rows, resolutionPrefix = '-Y') {
    const header = `#?RADIANCE\nFORMAT=32-bit_rle_rgbe\n\n${resolutionPrefix} ${height} +X ${width}\n`;
    const headerBytes = new TextEncoder().encode(header);
    const scanlines = [];
    for (let y = 0; y < height; y++) {
        scanlines.push(...createRleScanline(width, rows[y]));
    }

    const buffer = new ArrayBuffer(headerBytes.length + scanlines.length);
    const bytes = new Uint8Array(buffer);
    bytes.set(headerBytes, 0);
    bytes.set(scanlines, headerBytes.length);

    return buffer;
}

function createChannelValues(width, seed) {
    return [0, 1, 2, 3].map(channel => (
        new Array(width).fill(0).map((_, x) => (seed + channel * 16 + x) & 0xff)
    ));
}

