import { afterEach, describe, expect, test, jest } from '@jest/globals';

import {
    ADDRESS_CLAMP_TO_EDGE,
    ADDRESS_REPEAT,
    PIXELFORMAT_111110F,
    PIXELFORMAT_DXT1,
    PIXELFORMAT_DXT3,
    PIXELFORMAT_DXT5,
    PIXELFORMAT_ETC1,
    PIXELFORMAT_ETC2_RGB,
    PIXELFORMAT_ETC2_RGBA,
    PIXELFORMAT_PVRTC_2BPP_RGB_1,
    PIXELFORMAT_PVRTC_2BPP_RGBA_1,
    PIXELFORMAT_PVRTC_4BPP_RGB_1,
    PIXELFORMAT_PVRTC_4BPP_RGBA_1,
    PIXELFORMAT_RGB8,
    PIXELFORMAT_RGB16F,
    PIXELFORMAT_RGBA8,
    PIXELFORMAT_RGBA16F,
    PIXELFORMAT_SRGB8,
    PIXELFORMAT_SRGBA8
} from '../../../../src/platform/graphics/constants.js';
import { Http } from '../../../../src/platform/net/http.js';
import { KtxParser } from '../../../../src/framework/parsers/texture/ktx.js';

import { createDevice, createHandler, createUrl } from './test-helpers.js';

const KTX_IDENTIFIER = [0x58544BAB, 0xBB313120, 0x0A1A0A0D];

/**
 * Builds a KTX 1 file. `levelSizes` gives the byte size of each mip level, each repeated for
 * every face.
 */
function createKtxBuffer({
    width = 4,
    height = 4,
    internalFormat = 0x8058,
    faces = 1,
    mips = 1,
    pixelDepth = 0,
    arrayElements = 0,
    kvdBytes = 0,
    levelSizes = [64],
    identifier = KTX_IDENTIFIER
} = {}) {
    const sizes = levelSizes.slice(0, Math.max(1, mips));
    if (sizes.length === 0) {
        sizes.push(64);
    }

    const kvdWords = kvdBytes / 4;
    const levelWords = sizes.reduce((total, size) => total + 1 + faces * Math.ceil(size / 4), 0);
    const totalWords = 16 + kvdWords + levelWords;

    const buffer = new ArrayBuffer(totalWords * 4);
    const words = new Uint32Array(buffer);
    const bytes = new Uint8Array(buffer);

    words[0] = identifier[0];
    words[1] = identifier[1];
    words[2] = identifier[2];
    words[3] = 0x04030201;
    words[7] = internalFormat;
    words[9] = width;
    words[10] = height;
    words[11] = pixelDepth;
    words[12] = arrayElements;
    words[13] = faces;
    words[14] = mips;
    words[15] = kvdBytes;

    let offset = 16 + kvdWords;
    sizes.forEach((size, level) => {
        words[offset++] = size;
        for (let face = 0; face < faces; face++) {
            const start = offset * 4;
            for (let i = 0; i < size; i++) {
                bytes[start + i] = (i + level * 40 + face * 10 + 1) & 0xff;
            }
            offset += Math.ceil(size / 4);
        }
    });

    return buffer;
}

describe('KtxParser', () => {
    let createdTextures = [];

    const open = (data, options) => {
        const device = createDevice();
        const parser = new KtxParser();
        const texture = parser.open('texture.ktx', data, device, options);
        createdTextures.push(texture);
        return { device, parser, texture };
    };

    afterEach(() => {
        createdTextures.forEach(texture => texture?.destroy());
        createdTextures = [];
        jest.restoreAllMocks();
    });

    describe('#canParse()', () => {
        test('claims ktx files only', () => {
            const parser = new KtxParser();
            expect(parser.canParse({ ext: 'ktx' })).toBe(true);
            expect(parser.canParse({ ext: 'ktx2' })).toBe(false);
            expect(parser.canParse({ ext: 'dds' })).toBe(false);
        });
    });

    describe('#load()', () => {
        test('fetches the file as an array buffer', () => {
            const parser = new KtxParser();
            const handler = createHandler();
            parser.handler = handler;

            const url = createUrl('texture.ktx');
            const asset = { name: 'asset' };
            const callback = jest.fn();

            parser.load(url, callback, asset);

            expect(handler.fetch).toHaveBeenCalledWith(url, Http.ResponseType.ARRAY_BUFFER, callback, asset);
        });
    });

    describe('#parse()', () => {
        test('parses an RGBA8 texture', () => {
            const parser = new KtxParser();
            const data = createKtxBuffer({
                width: 4,
                height: 4,
                internalFormat: 0x8058,
                levelSizes: [64]
            });

            const result = parser.parse(data);

            expect(result.format).toBe(PIXELFORMAT_RGBA8);
            expect(result.width).toBe(4);
            expect(result.height).toBe(4);
            expect(result.cubemap).toBe(false);
            expect(result.levels).toHaveLength(1);
            expect(result.levels[0]).toBeInstanceOf(Uint8Array);
            expect(result.levels[0]).toHaveLength(64);
            expect(Array.from(result.levels[0].slice(0, 4))).toEqual([1, 2, 3, 4]);
        });

        test.each([
            [0x83F0, PIXELFORMAT_DXT1],
            [0x83F2, PIXELFORMAT_DXT3],
            [0x83F3, PIXELFORMAT_DXT5],
            [0x8D64, PIXELFORMAT_ETC1],
            [0x9274, PIXELFORMAT_ETC2_RGB],
            [0x9278, PIXELFORMAT_ETC2_RGBA],
            [0x8C00, PIXELFORMAT_PVRTC_4BPP_RGB_1],
            [0x8C01, PIXELFORMAT_PVRTC_2BPP_RGB_1],
            [0x8C02, PIXELFORMAT_PVRTC_4BPP_RGBA_1],
            [0x8C03, PIXELFORMAT_PVRTC_2BPP_RGBA_1],
            [0x8051, PIXELFORMAT_RGB8],
            [0x8058, PIXELFORMAT_RGBA8],
            [0x8C41, PIXELFORMAT_SRGB8],
            [0x8C43, PIXELFORMAT_SRGBA8],
            [0x881B, PIXELFORMAT_RGB16F],
            [0x881A, PIXELFORMAT_RGBA16F]
        ])('maps glInternalFormat 0x%s to the expected pixel format', (internalFormat, expectedFormat) => {
            const parser = new KtxParser();
            const result = parser.parse(createKtxBuffer({
                internalFormat,
                levelSizes: [16]
            }));

            expect(result.format).toBe(expectedFormat);
        });

        test('creates a Uint32Array container for 111110F data', () => {
            const parser = new KtxParser();
            const result = parser.parse(createKtxBuffer({
                internalFormat: 0x8C3A,
                levelSizes: [16]
            }));

            expect(result.format).toBe(PIXELFORMAT_111110F);
            expect(result.levels[0]).toBeInstanceOf(Uint32Array);
            expect(result.levels[0]).toHaveLength(4);
        });

        test('parses multiple mip levels', () => {
            const parser = new KtxParser();
            const result = parser.parse(createKtxBuffer({
                mips: 2,
                levelSizes: [64, 16]
            }));

            expect(result.levels).toHaveLength(2);
            expect(result.levels[0]).toHaveLength(64);
            expect(result.levels[1]).toHaveLength(16);
            expect(result.levels[1][0]).toBe(41);
        });

        test('defaults a zero mipmap level count to one level', () => {
            const parser = new KtxParser();
            const result = parser.parse(createKtxBuffer({
                mips: 0,
                levelSizes: [64]
            }));

            expect(result.levels).toHaveLength(1);
        });

        test('parses a cubemap into six face containers', () => {
            const parser = new KtxParser();
            const result = parser.parse(createKtxBuffer({
                faces: 6,
                levelSizes: [8]
            }));

            expect(result.cubemap).toBe(true);
            expect(result.levels).toHaveLength(1);
            expect(result.levels[0]).toHaveLength(6);
            result.levels[0].forEach((face) => {
                expect(face).toBeInstanceOf(Uint8Array);
                expect(face).toHaveLength(8);
            });

            expect(Array.from(result.levels[0].map(face => face[0]))).toEqual([1, 11, 21, 31, 41, 51]);
        });

        test('skips key/value data before the mip payload', () => {
            const parser = new KtxParser();
            const result = parser.parse(createKtxBuffer({
                kvdBytes: 8,
                levelSizes: [64]
            }));

            expect(result.width).toBe(4);
            expect(result.levels[0]).toHaveLength(64);
            expect(result.levels[0][0]).toBe(1);
        });

        test('returns null for an invalid identifier', () => {
            const parser = new KtxParser();
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});

            const result = parser.parse(createKtxBuffer({
                identifier: [1, 2, 3]
            }));

            expect(result).toBeNull();
            expect(warn).toHaveBeenCalledWith('Invalid definition header found in KTX file. Expected 0xAB4B5458, 0x203131BB, 0x0D0A1A0A');
        });

        test('rejects volume textures', () => {
            const parser = new KtxParser();
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});

            const result = parser.parse(createKtxBuffer({ pixelDepth: 2 }));

            expect(result).toBeNull();
            expect(warn).toHaveBeenCalledWith('More than 1 pixel depth not supported!');
        });

        test('rejects texture arrays', () => {
            const parser = new KtxParser();
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});

            const result = parser.parse(createKtxBuffer({ arrayElements: 1 }));

            expect(result).toBeNull();
            expect(warn).toHaveBeenCalledWith('Array texture not supported!');
        });

        test('rejects unknown glInternalFormat values', () => {
            const parser = new KtxParser();
            const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});

            const result = parser.parse(createKtxBuffer({ internalFormat: 0x1234 }));

            expect(result).toBeNull();
            expect(warn).toHaveBeenCalledWith('Unknown glInternalFormat: 4660');
        });
    });

    describe('#open()', () => {
        test('creates a single-level 2D texture and uploads it', () => {
            const { device, texture } = open(createKtxBuffer({
                width: 8,
                height: 4,
                internalFormat: 0x8058,
                levelSizes: [128]
            }));

            expect(texture.name).toBe('texture.ktx');
            expect(texture.device).toBe(device);
            expect(texture.width).toBe(8);
            expect(texture.height).toBe(4);
            expect(texture.format).toBe(PIXELFORMAT_RGBA8);
            expect(texture.cubemap).toBe(false);
            expect(texture.addressU).toBe(ADDRESS_REPEAT);
            expect(texture.addressV).toBe(ADDRESS_REPEAT);
            expect(texture.mipmaps).toBe(false);
            expect(texture.getSource(0)).toHaveLength(128);
            expect(device.texturesToUpload.has(texture)).toBe(true);
        });

        test('enables mipmaps when more than one level is present', () => {
            const { texture } = open(createKtxBuffer({
                mips: 2,
                levelSizes: [64, 16]
            }));

            expect(texture.mipmaps).toBe(true);
            expect(texture.getSource(0)).toHaveLength(64);
            expect(texture.getSource(1)).toHaveLength(16);
        });

        test('uses clamped addressing for cubemaps', () => {
            const { texture } = open(createKtxBuffer({
                faces: 6,
                levelSizes: [8]
            }));

            expect(texture.cubemap).toBe(true);
            expect(texture.addressU).toBe(ADDRESS_CLAMP_TO_EDGE);
            expect(texture.addressV).toBe(ADDRESS_CLAMP_TO_EDGE);
            expect(texture.getSource(0)).toHaveLength(6);
        });

        test('applies texture options', () => {
            const { texture } = open(createKtxBuffer({
                levelSizes: [64]
            }), {
                name: 'overridden.ktx',
                mipmaps: true
            });

            expect(texture.name).toBe('overridden.ktx');
            expect(texture.mipmaps).toBe(true);
        });

        test('returns null when parsing fails', () => {
            const { device, texture } = open(createKtxBuffer({
                internalFormat: 0x1234
            }));

            expect(texture).toBeNull();
            expect(device.texturesToUpload.size).toBe(0);
        });
    });
});
