    colorModel = 0,
    dfdByteLength = 16,
    kvdByteLength = 0,
    identifier = true
} = {}) {
    const magicBytes = 12;
    const headerBytes = 9 * 4;
    const indexBytes = 4 * 4 + 8 + 8;
    const levelBytes = Math.max(1, levelCount) * 24;
    const dfdOffset = magicBytes + headerBytes + indexBytes + levelBytes;

    const dfdTotalSize = 16;
    const kvdByteOffset = dfdOffset + dfdTotalSize;

    // reading a DFD consumes dfdByteLength + 4 bytes
    const totalBytes = Math.max(
        dfdOffset + dfdByteLength + 4,
        kvdByteOffset + kvdByteLength
    ) + 16;

    const buffer = new ArrayBuffer(totalBytes);
    const view = new DataView(buffer);
    const u32 = new Uint32Array(buffer);
    const u8 = new Uint8Array(buffer);

    if (identifier) {
        view.setUint32(0, 0xAB4B5458, false);
        view.setUint32(4, 0x203230BB, false);
        view.setUint32(8, 0x0D0A1A0A, false);
    } else {
        view.setUint32(0, 0x12345678, false);
    }

    let offset = 12;
    u32[offset / 4] = vkFormat; offset += 4;
    u32[offset / 4] = typeSize; offset += 4;
    u32[offset / 4] = width; offset += 4;
    u32[offset / 4] = height; offset += 4;
    u32[offset / 4] = pixelDepth; offset += 4;
    u32[offset / 4] = layerCount; offset += 4;
    u32[offset / 4] = faceCount; offset += 4;
    u32[offset / 4] = levelCount; offset += 4;
    u32[offset / 4] = supercompressionScheme; offset += 4;

    // index
    u32[offset / 4] = dfdOffset; offset += 4;
    u32[offset / 4] = dfdByteLength; offset += 4;
    u32[offset / 4] = kvdByteOffset; offset += 4;
    u32[offset / 4] = kvdByteLength; offset += 4;
    offset += 16; // sgd offset/length

