import { jest } from '@jest/globals';
import { SHADERLANGUAGE_GLSL, SHADERLANGUAGE_WGSL } from '../../../src/platform/graphics/constants.js';
import { ShaderChunks } from '../../../src/scene/shader-lib/shader-chunks.js';

const createShader = jest.fn((device, options) => ({
    device,
    options,
    uniqueName: options.uniqueName
}));

jest.unstable_mockModule('../../../src/scene/shader-lib/shader-utils.js', () => ({
    ShaderUtils: { createShader }
}));

const { LightmapFilters } = await import('../../../src/framework/lightmapper/lightmap-filters.js');

function createDevice() {
    const handles = new Map();
    return {
        isWebGPU: false,
        on: jest.fn(),
        scope: {
            resolve: jest.fn((name) => {
                if (!handles.has(name)) {
                    handles.set(name, { setValue: jest.fn() });
                }
                return handles.get(name);
            })
        },
        handles
    };
}

describe('LightmapFilters', () => {
    let device;
    let filters;

    beforeEach(() => {
        createShader.mockClear();
        device = createDevice();
        filters = new LightmapFilters(device);
    });

    it('registers its GLSL and WGSL chunks with the device', () => {
        const glslChunks = ShaderChunks.get(device, SHADERLANGUAGE_GLSL);
        const wgslChunks = ShaderChunks.get(device, SHADERLANGUAGE_WGSL);

        expect(glslChunks.has('glslBilateralDeNoisePS')).toBe(true);
        expect(glslChunks.has('glslDilatePS')).toBe(true);
        expect(wgslChunks.has('wgslBilateralDeNoisePS')).toBe(true);
        expect(wgslChunks.has('wgslDilatePS')).toBe(true);
    });

    it('sets the source texture uniform', () => {
        const texture = { name: 'lightmap' };

        filters.setSourceTexture(texture);

        expect(filters.constantTexSource.setValue).toHaveBeenCalledWith(texture);
    });

    it('converts texture dimensions into inverse pixel offsets', () => {
        filters.prepare(200, 400);

        expect(Array.from(filters.pixelOffset)).toEqual([0.005, 0.0025]);
        expect(filters.constantPixelOffset.setValue).toHaveBeenCalledWith(filters.pixelOffset);
    });

    it('creates and configures the HDR bilateral denoise shader once', () => {
        filters.prepareDenoise(2, 3, true);

        expect(createShader).toHaveBeenCalledTimes(1);
        const options = createShader.mock.calls[0][1];
        expect(options.uniqueName).toBe('lmBilateralDeNoise-hdr');
        expect(options.fragmentDefines.get('{MSIZE}')).toBe(15);
        expect(options.fragmentDefines.has('HDR')).toBe(true);
        expect(options.vertexGLSL).toBeTruthy();
        expect(options.fragmentGLSL).toBeTruthy();
        expect(options.vertexWGSL).toBeTruthy();
        expect(options.fragmentWGSL).toBeTruthy();

        expect(Array.from(filters.sigmas)).toEqual([2, 3]);
        expect(filters.constantSigmas.setValue).toHaveBeenCalledWith(filters.sigmas);
        expect(filters.kernel).toBeInstanceOf(Float32Array);
        expect(filters.kernel).toHaveLength(15);
        expect(filters.kernel[7]).toBeCloseTo(0.39894 / 2, 10);
        for (let i = 0; i < 7; i++) {
            expect(filters.kernel[i]).toBeCloseTo(filters.kernel[14 - i], 10);
        }
        expect(filters.bZnorm.setValue).toHaveBeenCalledWith(3 / 0.39894);
        expect(filters.getDenoise(true)).toBe(createShader.mock.results[0].value);
    });

    it('reuses a shader variant while updating its uniforms', () => {
        filters.prepareDenoise(2, 3, true);
        filters.prepareDenoise(1, 5, true);

        expect(createShader).toHaveBeenCalledTimes(1);
        expect(Array.from(filters.sigmas)).toEqual([1, 5]);
        expect(filters.kernel[7]).toBeCloseTo(0.39894, 10);
        expect(filters.bZnorm.setValue).toHaveBeenLastCalledWith(5 / 0.39894);
    });

    it('creates separate RGBM denoise and dilate shaders without the HDR define', () => {
        filters.prepareDenoise(1, 1, false);
        const denoiseOptions = createShader.mock.calls[0][1];
        expect(denoiseOptions.uniqueName).toBe('lmBilateralDeNoise-rgbm');
        expect(denoiseOptions.fragmentDefines.has('HDR')).toBe(false);
        expect(filters.getDenoise(false)).toBe(createShader.mock.results[0].value);
        expect(filters.getDenoise(true)).toBeUndefined();

        const dilateRGBM = filters.getDilate(device, false);
        const rgbmOptions = createShader.mock.calls[1][1];
        expect(rgbmOptions.uniqueName).toBe('lmDilate-rgbm');
        expect(rgbmOptions.fragmentGLSL.startsWith('#define HDR\n')).toBe(false);
        expect(filters.getDilate(device, false)).toBe(dilateRGBM);
        expect(createShader).toHaveBeenCalledTimes(2);

        const dilateHDR = filters.getDilate(device, true);
        const hdrOptions = createShader.mock.calls[2][1];
        expect(hdrOptions.uniqueName).toBe('lmDilate-hdr');
        expect(hdrOptions.fragmentGLSL.startsWith('#define HDR\n')).toBe(true);
        expect(dilateHDR).not.toBe(dilateRGBM);
    });
});
EOF

