import { jest } from '@jest/globals';
import { BoundingBox } from '../../../src/core/shape/bounding-box.js';
import { Vec3 } from '../../../src/core/math/vec3.js';
import { Lightmapper } from '../../../src/framework/lightmapper/lightmapper.js';
import { BakeMeshNode } from '../../../src/framework/lightmapper/bake-mesh-node.js';
import { MeshInstance } from '../../../src/scene/mesh-instance.js';
import {
    FILTER_LINEAR,
    MASK_AFFECT_LIGHTMAPPED,
    SHADERDEF_DIRLM,
    SHADERDEF_LM
} from '../../../src/scene/constants.js';

function createLightmapper(sceneOverrides = {}) {
    const scene = {
        lightmapSizeMultiplier: 16,
        lightmapMaxResolution: 2048,
        ambientBake: false,
        clusteredLightingEnabled: false,
        ...sceneOverrides
    };
    const renderer = { shadowMapCache: { name: 'shadow-cache' } };
    const assets = { get: jest.fn() };
    const lightmapper = new Lightmapper({}, { enabled: true, _children: [] }, scene, renderer, assets);
    return { lightmapper, scene, renderer, assets };
}

function createMesh(name = 'mesh', hasUv1 = true) {
    return {
        name,
        vertexBuffer: {
            format: {
                hasUv: jest.fn(() => hasUv1)
            }
        }
    };
}

function createMeshInstance(mesh = createMesh(), aabb = new BoundingBox()) {
    return {
        mesh,
        aabb,
        material: { name: 'original-material' },
        mask: 1,
        _shaderDefs: 0,
        setLightmapped: jest.fn(),
        setRealtimeLightmap: jest.fn(),
        node: { getWorldTransform: jest.fn() }
    };
}

function createRenderNode(meshInstances, overrides = {}) {
    return {
        name: 'render-node',
        enabled: true,
        _children: [],
        render: {
            enabled: true,
            lightmapped: true,
            castShadows: true,
            castShadowsLightmap: true,
            meshInstances,
            ...overrides
        }
    };
}

describe('Lightmapper collection and geometry helpers', () => {
    it('initializes public state and bake statistics', () => {
        const { lightmapper, scene, renderer, assets } = createLightmapper();

        expect(lightmapper.device).toEqual({});
        expect(lightmapper.root).toBeDefined();
        expect(lightmapper.scene).toBe(scene);
        expect(lightmapper.renderer).toBe(renderer);
        expect(lightmapper.assets).toBe(assets);
        expect(lightmapper.shadowMapCache).toBe(renderer.shadowMapCache);
        expect(lightmapper.passMaterials).toEqual([]);
        expect(lightmapper.ambientAOMaterial).toBeNull();
        expect(lightmapper.renderTargets).toBeInstanceOf(Map);
        expect(lightmapper.stats).toEqual({
            renderPasses: 0,
            lightmapCount: 0,
            totalRenderTime: 0,
            forwardTime: 0,
            fboTime: 0,
            shadowMapTime: 0,
            compileTime: 0,
            shadersLinked: 0
        });
    });

    it('collects lightmapped render components and records every bake mesh node', () => {
        const meshInstance = createMeshInstance();
        const node = createRenderNode([meshInstance]);

        const bakeNodes = [];
        const allNodes = [];
        const { lightmapper } = createLightmapper();

        lightmapper.collectModels(node, bakeNodes, allNodes);

        expect(allNodes).toHaveLength(1);
        expect(allNodes[0]).toBeInstanceOf(BakeMeshNode);
        expect(allNodes[0].node).toBe(node);
        expect(allNodes[0].component).toBe(node.render);
        expect(bakeNodes).toHaveLength(1);
        expect(bakeNodes[0]).not.toBe(allNodes[0]);
        expect(bakeNodes[0].meshInstances).toEqual([meshInstance]);
    });

    it('records non-lightmapped geometry in allNodes without adding it to the bake set', () => {
        const node = createRenderNode([createMeshInstance()], { lightmapped: false });
        const bakeNodes = [];
        const allNodes = [];
        const { lightmapper } = createLightmapper();

        lightmapper.collectModels(node, bakeNodes, allNodes);

        expect(allNodes).toHaveLength(1);
        expect(bakeNodes).toEqual([]);
    });

    it('walks enabled descendants and ignores disabled subtrees', () => {
        const rootMesh = createMeshInstance(createMesh('root'));
        const childMesh = createMeshInstance(createMesh('child'));
        const hiddenMesh = createMeshInstance(createMesh('hidden'));
        const root = createRenderNode([rootMesh]);
        const child = createRenderNode([childMesh]);
        const disabledChild = createRenderNode([hiddenMesh], {});
        disabledChild.enabled = false;
        root._children = [child, disabledChild];

        const bakeNodes = [];
        const { lightmapper } = createLightmapper();
        lightmapper.collectModels(root, bakeNodes, null);

        expect(bakeNodes).toHaveLength(2);
        expect(bakeNodes.flatMap(node => node.meshInstances)).toEqual([rootMesh, childMesh]);
        expect(bakeNodes.flatMap(node => node.meshInstances)).not.toContain(hiddenMesh);
    });

    it('excludes components whose meshes have no second UV set', () => {
        const meshInstance = createMeshInstance(createMesh('no-uv1', false));
        const node = createRenderNode([meshInstance]);
        const bakeNodes = [];
        const allNodes = [];
        const { lightmapper } = createLightmapper();

        lightmapper.collectModels(node, bakeNodes, allNodes);

        expect(meshInstance.mesh.vertexBuffer.format.hasUv).toHaveBeenCalledWith(1);
        expect(allNodes).toHaveLength(1);
        expect(bakeNodes).toEqual([]);
    });

    it('splits repeated mesh instances into separate bake nodes', () => {
        const sharedMesh = createMesh('shared');
        const first = createMeshInstance(sharedMesh);
        const second = createMeshInstance(sharedMesh);
        const unique = createMeshInstance(createMesh('unique'));
        const node = createRenderNode([first, second, unique]);
        const bakeNodes = [];
        const { lightmapper } = createLightmapper();

        lightmapper.collectModels(node, bakeNodes, null);

        expect(bakeNodes).toHaveLength(2);
        expect(bakeNodes[0].meshInstances).toEqual([first, unique]);
        expect(bakeNodes[1].meshInstances).toEqual([second]);
        // The temporary de-duplication set must not leak between invocations.
        expect(lightmapper._tempSet.size).toBe(0);
    });

    it('collects model-component geometry through the same bake path', () => {
        const meshInstance = createMeshInstance();
        const node = {
            name: 'model-node',
            enabled: true,
            _children: [],
            model: {
                enabled: true,
                lightmapped: true,
                model: { meshInstances: [meshInstance] }
            }
        };
        const bakeNodes = [];
        const allNodes = [];
        const { lightmapper } = createLightmapper();

        lightmapper.collectModels(node, bakeNodes, allNodes);

        expect(allNodes).toHaveLength(1);
        expect(allNodes[0].component).toBe(node.model);
        expect(bakeNodes).toHaveLength(1);
        expect(bakeNodes[0].meshInstances).toEqual([meshInstance]);
    });

    it('calculates a power-of-two lightmap size from area and world bounds', () => {
        const meshInstance = createMeshInstance(createMesh(), new BoundingBox(new Vec3(0, 0, 0), new Vec3(1, 2, 3)));
        const node = createRenderNode([meshInstance], {
            lightmapSizeMultiplier: 1,
            _area: { x: 1, y: 1, z: 1, uv: 1 },
            type: 'mesh'
        });
        const { lightmapper } = createLightmapper();

        expect(lightmapper.calculateLightmapSize(node)).toBe(64);
    });

    it('applies component and scene size multipliers and caps the result', () => {
        const meshInstance = createMeshInstance(createMesh(), new BoundingBox(new Vec3(0, 0, 0), new Vec3(1, 2, 3)));
        const node = createRenderNode([meshInstance], {
            lightmapSizeMultiplier: 2,
            _area: { x: 1, y: 1, z: 1, uv: 1 },
            type: 'mesh'
        });
        const { lightmapper } = createLightmapper({ lightmapSizeMultiplier: 16, lightmapMaxResolution: 64 });

        expect(lightmapper.calculateLightmapSize(node)).toBe(64);
    });

    it('reads model areas from assets and ignores render asset areas', () => {
        const meshInstance = createMeshInstance(createMesh(), new BoundingBox(new Vec3(0, 0, 0), new Vec3(1, 2, 3)));
        const modelNode = {
            model: {
                enabled: true,
                lightmapped: true,
                asset: { id: 'model-asset' },
                lightmapSizeMultiplier: 1,
                meshInstances: [meshInstance]
            }
        };
        const renderNode = createRenderNode([meshInstance], {
            type: 'asset',
            _area: { x: 100, y: 100, z: 100, uv: 1 },
            lightmapSizeMultiplier: 1
        });
        const { lightmapper, assets } = createLightmapper();
        assets.get.mockReturnValue({ data: { area: { x: 2, y: 1, z: 1, uv: 1 } } });

        expect(lightmapper.calculateLightmapSize(modelNode)).toBe(128);
        expect(assets.get).toHaveBeenCalledWith({ id: 'model-asset' });
        expect(lightmapper.calculateLightmapSize(renderNode)).toBe(64);
    });

    it('computes union bounds for nodes and mesh instance batches', () => {
        const first = createMeshInstance(createMesh(), new BoundingBox(new Vec3(0, 0, 0), new Vec3(1, 1, 1)));
        const second = createMeshInstance(createMesh(), new BoundingBox(new Vec3(4, 0, 0), new Vec3(1, 1, 1)));
        const { lightmapper } = createLightmapper();

        const bounds = lightmapper.computeBounds([first, second]);
        expect(bounds.center.x).toBeCloseTo(2, 6);
        expect(bounds.halfExtents.x).toBeCloseTo(3, 6);
        expect(bounds.halfExtents.y).toBeCloseTo(1, 6);

        const node = { meshInstances: [first, second], bounds: null };
        lightmapper.computeNodesBounds([node]);
        expect(node.bounds.center.x).toBeCloseTo(2, 6);
        expect(node.bounds.halfExtents.x).toBeCloseTo(3, 6);
    });

    it('marks shadow casters and restores their shadow settings through bake mesh nodes', () => {
        const caster = createMeshInstance();
        caster.visibleThisFrame = false;
        const nonCaster = createMeshInstance();
        nonCaster.visibleThisFrame = false;
        const casterNode = new BakeMeshNode(createRenderNode([caster], { castShadows: true, castShadowsLightmap: true }));
        const nonCasterNode = new BakeMeshNode(createRenderNode([nonCaster], { castShadows: true, castShadowsLightmap: false }));
        const { lightmapper } = createLightmapper();

        const casters = lightmapper.prepareShadowCasters([casterNode, nonCasterNode]);

        expect(casters).toEqual([caster]);
        expect(caster.visibleThisFrame).toBe(true);
        expect(nonCaster.visibleThisFrame).toBe(false);
        expect(casterNode.component.castShadows).toBe(true);
        expect(nonCasterNode.component.castShadows).toBe(false);
    });

    it('updates world transforms and can back up and restore materials', () => {
        const first = createMeshInstance();
        const second = createMeshInstance();
        const originalMaterials = [first.material, second.material];
        const { lightmapper } = createLightmapper();

        lightmapper.updateTransforms([{ meshInstances: [first, second] }]);
        expect(first.node.getWorldTransform).toHaveBeenCalledTimes(1);
        expect(second.node.getWorldTransform).toHaveBeenCalledTimes(1);

        lightmapper.backupMaterials([first, second]);
        first.material = { name: 'bake-0' };
        second.material = { name: 'bake-1' };
        lightmapper.restoreMaterials([first, second]);

        expect(first.material).toBe(originalMaterials[0]);
        expect(second.material).toBe(originalMaterials[1]);
    });

    it('enables and disables lightmap bindings on mesh instances', () => {
        const firstTexture = { minFilter: 0, magFilter: 0 };
        const secondTexture = { minFilter: 0, magFilter: 0 };
        const meshInstance = createMeshInstance();
        const bakeNode = {
            meshInstances: [meshInstance],
            renderTargets: [
                { colorBuffer: firstTexture },
                { colorBuffer: secondTexture }
            ]
        };
        const { lightmapper } = createLightmapper();
        const shaderDefs = SHADERDEF_LM | SHADERDEF_DIRLM;

        lightmapper.setLightmapping([bakeNode], true, 2, shaderDefs);

        expect(meshInstance.setLightmapped).toHaveBeenCalledWith(true);
        expect(meshInstance._shaderDefs).toBe(shaderDefs);
        expect(meshInstance.mask).toBe(MASK_AFFECT_LIGHTMAPPED);
        expect(firstTexture.minFilter).toBe(FILTER_LINEAR);
        expect(firstTexture.magFilter).toBe(FILTER_LINEAR);
        expect(secondTexture.minFilter).toBe(FILTER_LINEAR);
        expect(secondTexture.magFilter).toBe(FILTER_LINEAR);
        expect(meshInstance.setRealtimeLightmap).toHaveBeenNthCalledWith(1, MeshInstance.lightmapParamNames[0], firstTexture);
        expect(meshInstance.setRealtimeLightmap).toHaveBeenNthCalledWith(2, MeshInstance.lightmapParamNames[1], secondTexture);

        lightmapper.setLightmapping([bakeNode], false, 2);
        expect(meshInstance.setLightmapped).toHaveBeenLastCalledWith(false);
    });
});
