import { jest } from '@jest/globals';
import {
    ADDRESS_CLAMP_TO_EDGE,
    FILTER_NEAREST,
    PIXELFORMAT_RGBA8,
    TEXTURETYPE_DEFAULT,
    TEXTURETYPE_RGBM
} from '../../../src/platform/graphics/constants.js';
import { BlendState } from '../../../src/platform/graphics/blend-state.js';
import { DepthState } from '../../../src/platform/graphics/depth-state.js';
import { LightmapCache } from '../../../src/scene/graphics/lightmap-cache.js';

const textureInstances = [];
const renderTargetInstances = [];
const drawQuadWithShader = jest.fn();

jest.unstable_mockModule('../../../src/platform/graphics/texture.js', () => ({
    Texture: class Texture {
        constructor(device, options) {
            this.device = device;
            Object.assign(this, options);
            this.destroy = jest.fn();
            textureInstances.push(this);
        }
    }
}));

jest.unstable_mockModule('../../../src/platform/graphics/render-target.js', () => ({
    RenderTarget: class RenderTarget {
        constructor(options) {
            this.options = options;
            this.colorBuffer = options.colorBuffer;
            this.destroy = jest.fn();
            renderTargetInstances.push(this);
        }
    }
}));

jest.unstable_mockModule('../../../src/scene/graphics/quad-render-utils.js', () => ({
    drawQuadWithShader
}));

const { Lightmapper } = await import('../../../src/framework/lightmapper/lightmapper.js');

function createFixture(sceneOverrides = {}) {
    const scene = {
        lightmapPixelFormat: PIXELFORMAT_RGBA8,
        lightmapFilterEnabled: false,
        lightmapFilterRange: 2,
        lightmapFilterSmoothness: 3,
        clusteredLightingEnabled: false,
        ...sceneOverrides
    };
    const device = {
        setBlendState: jest.fn(),
        setDepthState: jest.fn(),
        setStencilState: jest.fn(),
        pushMarker: jest.fn(),
        popMarker: jest.fn()
    };
    return new Lightmapper(device, null, scene, { shadowMapCache: {} }, {});
}

function createTexture(size, name) {
    return {
        width: size,
        height: size,
        name,
        destroy: jest.fn()
    };
}

describe('Lightmapper texture allocation and post-processing', () => {
    beforeEach(() => {
        textureInstances.length = 0;
        renderTargetInstances.length = 0;
        drawQuadWithShader.mockClear();
    });

    it('creates RGBM or HDR textures from the scene format', () => {
        const lightmapper = createFixture();

        const rgbmTexture = lightmapper.createTexture(256, 'rgbm');
        lightmapper.bakeHDR = true;
        const hdrTexture = lightmapper.createTexture(512, 'hdr');

        expect(textureInstances).toEqual([rgbmTexture, hdrTexture]);
        expect(rgbmTexture).toEqual(expect.objectContaining({
            width: 256,
            height: 256,
            format: PIXELFORMAT_RGBA8,
            mipmaps: false,
            type: TEXTURETYPE_RGBM,
            minFilter: FILTER_NEAREST,
            magFilter: FILTER_NEAREST,
            addressU: ADDRESS_CLAMP_TO_EDGE,
            addressV: ADDRESS_CLAMP_TO_EDGE,
            name: 'rgbm'
        }));
        expect(hdrTexture.type).toBe(TEXTURETYPE_DEFAULT);
        expect(hdrTexture.width).toBe(512);
    });

    it('allocates per-pass node targets and one pooled temporary target per size', () => {
        const lightmapper = createFixture();
        const incRef = jest.spyOn(LightmapCache, 'incRef').mockImplementation(() => {});
        const sizes = new Map([[64, 64], [128, 128]]);
        jest.spyOn(lightmapper, 'calculateLightmapSize').mockImplementation(node => sizes.get(node.node.name));
        lightmapper.createTexture = jest.fn(createTexture);
        const firstNode = { node: { name: 64 }, renderTargets: [] };
        const secondNode = { node: { name: 128 }, renderTargets: [] };

        lightmapper.allocateTextures([firstNode, secondNode], 2);

        expect(firstNode.renderTargets).toHaveLength(2);
        expect(secondNode.renderTargets).toHaveLength(2);
        expect(firstNode.renderTargets[0].colorBuffer.name).toBe('lightmapper_lightmap_0');
        expect(firstNode.renderTargets[0].colorBuffer.name).toBe('lightmapper_lightmap_0');
        expect(secondNode.renderTargets[1].colorBuffer.name).toBe('lightmapper_lightmap_1');
        expect(firstNode.renderTargets[0].options).toEqual({
            colorBuffer: firstNode.renderTargets[0].colorBuffer,
            depth: false
        });
        expect(lightmapper.renderTargets.size).toBe(2);
        expect(lightmapper.renderTargets.get(64).colorBuffer.name).toBe('lightmapper_temp_lightmap_64');
        expect(lightmapper.renderTargets.get(128).colorBuffer.name).toBe('lightmapper_temp_lightmap_128');
        expect(lightmapper.createTexture).toHaveBeenCalledTimes(6);
        expect(incRef).toHaveBeenCalledTimes(6);
        expect(renderTargetInstances).toHaveLength(6);
        incRef.mockRestore();
    });

    it('runs denoise then dilate for each lightmap pass', () => {
        const lightmapper = createFixture({
            lightmapFilterEnabled: true,
            lightmapFilterRange: 4,
            lightmapFilterSmoothness: 5
        });
        const denoiseShader = { name: 'denoise' };
        const dilateShader = { name: 'dilate' };
        const filters = {
            getDilate: jest.fn(() => dilateShader),
            prepareDenoise: jest.fn(),
            getDenoise: jest.fn(() => denoiseShader),
            prepare: jest.fn(),
            setSourceTexture: jest.fn()
        };
        lightmapper.lightmapFilters = filters;
        const tempTexture = createTexture(64, 'temp');
        const tempRT = { colorBuffer: tempTexture };
        lightmapper.renderTargets.set(64, tempRT);
        const colorTexture = createTexture(64, 'color');
        const dirTexture = createTexture(64, 'dir');
        const colorRT = { colorBuffer: colorTexture };
        const dirRT = { colorBuffer: dirTexture };
        const bakeNode = { renderTargets: [colorRT, dirRT] };
        const device = lightmapper.device;

        lightmapper.postprocessTextures(device, [bakeNode], 2);

        expect(filters.getDilate).toHaveBeenCalledWith(device, false);
        expect(filters.prepareDenoise).toHaveBeenCalledWith(4, 5, false);
        expect(filters.getDenoise).toHaveBeenCalledWith(false);
        expect(device.setBlendState).toHaveBeenCalledWith(BlendState.NOBLEND);
        expect(device.setDepthState).toHaveBeenCalledWith(DepthState.NODEPTH);
        expect(device.setStencilState).toHaveBeenCalledWith(null, null);
        expect(filters.prepare).toHaveBeenNthCalledWith(1, 64, 64);
        expect(filters.prepare).toHaveBeenNthCalledWith(2, 64, 64);
        expect(filters.setSourceTexture.mock.calls).toEqual([
            [colorTexture], [tempTexture],
            [dirTexture], [tempTexture]
        ]);
        expect(drawQuadWithShader.mock.calls).toEqual([
            [device, tempRT, denoiseShader, undefined, undefined, 'LightmapDenoise'],
            [device, colorRT, dilateShader, undefined, undefined, 'LightmapDilate'],
            [device, tempRT, dilateShader, undefined, undefined, 'LightmapDilate'],
            [device, dirRT, dilateShader, undefined, undefined, 'LightmapDilate']
        ]);
        expect(device.pushMarker).toHaveBeenCalledWith('LMPost:0');
        expect(device.popMarker).toHaveBeenCalledTimes(1);
    });

    it('skips denoise when lightmap filtering is disabled', () => {
        const lightmapper = createFixture({ lightmapFilterEnabled: false });
        const dilateShader = { name: 'dilate' };
        const filters = {
            getDilate: jest.fn(() => dilateShader),
            prepareDenoise: jest.fn(),
            getDenoise: jest.fn(),
            prepare: jest.fn(),
            setSourceTexture: jest.fn()
        };
        lightmapper.lightmapFilters = filters;
        const tempRT = { colorBuffer: createTexture(16, 'temp') };
        lightmapper.renderTargets.set(16, tempRT);
        const nodeRT = { colorBuffer: createTexture(16, 'node') };

        lightmapper.postprocessTextures(lightmapper.device, [{ renderTargets: [nodeRT] }], 1);

        expect(filters.prepareDenoise).not.toHaveBeenCalled();
        expect(filters.getDenoise).not.toHaveBeenCalled();
        expect(drawQuadWithShader).toHaveBeenCalledTimes(2);
        expect(drawQuadWithShader.mock.calls.every(call => call[2] === dilateShader)).toBe(true);
        expect(drawQuadWithShader.mock.calls[0][5]).toBe('LightmapDilate');
        expect(drawQuadWithShader.mock.calls[1][5]).toBe('LightmapDilate');
    });
});
