                    if (!dynamic && stream.numComponents >= 3) {
                        if (semantic === SEMANTIC_POSITION) {
                            const m = transform.data;
                            const m0 = m[0];

                                const m0 = m[0];
                                const m1 = m[1];
                                const m2 = m[2];
                                const m4 = m[4];
                                const m5 = m[5];
                                const m6 = m[6];
                                const m8 = m[8];
                                const m9 = m[9];
                                const m10 = m[10];
                                const m12 = m[12];
                                const m13 = m[13];
                                const m14 = m[14];

                                let x, y, z;

                                for (let j = 0; j < totalComponents; j += stream.numComponents) {
                                    x = subarray[j];
                                    y = subarray[j + 1];
                                    z = subarray[j + 2];

