            const meshInstance = { name: 'batched' };
            const batch = new Batch([], false, 1);
            batch.meshInstance = meshInstance;

            batch.addToLayers(scene, [0, 1, 2]);

            expect(scene.layers.getLayerById.mock.calls.map(call => call[0])).toEqual([0, 1, 2]);
            expect(first.addMeshInstances).toHaveBeenCalledWith([meshInstance]);
            expect(second.addMeshInstances).toHaveBeenCalledWith([meshInstance]);
        });
    });

    describe('#removeFromLayers()', () => {
        it('removes the batched mesh instance from every layer that exists', () => {
            const first = layerMock();
            const second = layerMock();
            const scene = sceneMock({ 3: first, 5: second });
            const meshInstance = { name: 'batched' };
            const batch = new Batch([], true, 1);
            batch.meshInstance = meshInstance;

            batch.removeFromLayers(scene, [3, 4, 5]);

            expect(first.removeMeshInstances).toHaveBeenCalledWith([meshInstance]);
            expect(second.removeMeshInstances).toHaveBeenCalledWith([meshInstance]);
        });
    });

    describe('#destroy()', () => {
        it('removes the mesh instance from the layers and destroys it', () => {
            const layer = layerMock();
            const scene = sceneMock({ 0: layer });
            const meshInstance = { destroy: jest.fn() };
            const batch = new Batch([], false, 1);
            batch.meshInstance = meshInstance;

            batch.destroy(scene, [0]);

            expect(layer.removeMeshInstances).toHaveBeenCalledWith([meshInstance]);
            expect(meshInstance.destroy).toHaveBeenCalledTimes(1);
            expect(batch.meshInstance).toBeNull();
        });

