    });

    function boneWithTransform(name, position, scale = [1, 1, 1], parent = null) {
        const bone = new GraphNode(name);
        bone.setLocalPosition(...position);
        bone.setLocalScale(...scale);
        if (parent) {
            parent.addChild(bone);
        }
        bone.getWorldTransform();
        return bone;
    }

    it('initializes a palette for the supplied bones and stores its batching context', () => {
