            boneWithTransform('head', [4, 5, 6], [1, 1, 1], root)
        ];

        const skin = new SkinBatchInstance(device, bones, root);

        expect(skin.device).toBe(device);
        expect(skin.rootNode).toBe(root);
        expect(skin.bones).toBe(bones);
        expect(skin.boneTexture).toBeDefined();
        expect(skin.matrixPalette).toBeInstanceOf(Float32Array);
        expect(skin.matrixPalette).toHaveLength(24);

        skin.destroy();
    });

