        const uploadBones = jest.spyOn(skin, 'uploadBones');

        skin.updateMatrices(root, 42);

        expect(Array.from(skin.matrixPalette)).toEqual(before);
        expect(uploadBones).not.toHaveBeenCalled();

        skin.destroy();
    });

    it('writes transposed 4x3 world transforms into the bone palette in bone order', () => {
        const root = new GraphNode('root');
        const parent = boneWithTransform('parent', [10, 20, 30], [1, 1, 1], root);
        const first = boneWithTransform('first', [1, 2, 3], [2, 3, 4], parent);
        const second = boneWithTransform('second', [-5, 6, 7], [1, 1, 1], root);
        const skin = new SkinBatchInstance(device, [first, second], root);
        const uploadBones = jest.spyOn(skin, 'uploadBones').mockImplementation(() => {});

        skin.updateMatrixPalette(root, 9);

        expect(Array.from(skin.matrixPalette.slice(0, 12))).toEqual([
            2, 0, 0, 11,
            0, 3, 0, 22,
            0, 0, 4, 33
        ]);
        expect(Array.from(skin.matrixPalette.slice(12, 24))).toEqual([
            1, 0, 0, -5,
            0, 1, 0, 6,
            0, 0, 1, 7
        ]);
        expect(uploadBones).toHaveBeenCalledTimes(1);
        expect(uploadBones).toHaveBeenCalledWith(device);

        skin.destroy();
    });

