        jest.spyOn(skin, 'uploadBones').mockImplementation(() => {});

        skin.updateMatrixPalette(root, 1);
        expect(skin.matrixPalette[3]).toBe(1);
        expect(skin.matrixPalette[7]).toBe(2);
        expect(skin.matrixPalette[11]).toBe(3);

        bone.setLocalPosition(8, 9, 10);
        bone.getWorldTransform();
        skin.updateMatrixPalette(root, 1);

        expect(skin.matrixPalette[3]).toBe(8);
        expect(skin.matrixPalette[7]).toBe(9);
        expect(skin.matrixPalette[11]).toBe(10);

        skin.destroy();
    });
});
