    return new Map([[name, { data: new Float32Array([value]) }]]);
}

function makeMeshInstance({
    centerX = 0,
    half = 1,
    material = sharedMaterial,
    layer = sharedLayer,
    vertices = 3,
    batchingHash = 1,
    indexed = true,
    shaderDefs = 0,
    parameters,
    scaleSign = 1,
    castShadow = false,
    shadowCascadeMask = 0,
    stencilFront = null,
    drawOrder = 0
} = {}) {
    return {
        material,
        layer,
        mesh: {
            vertexBuffer: {
                getNumVertices: () => vertices,
                format: { batchingHash }
            },
            primitive: [{ indexed }]
        },
        _shaderDefs: shaderDefs,
        parameters: parameters ?? new Map(),
        aabb: new BoundingBox(new Vec3(centerX, 0, 0), new Vec3(half, half, half)),
        node: { worldTransform: { scaleSign } },
        castShadow,
        shadowCascadeMask,
        stencilFront,
        drawOrder
    };
}

