    let manager;

    beforeEach(() => {
        manager = new BatchManager({}, {}, {});
    });

    it('returns no draw lists for an empty input', () => {
        expect(manager.prepare([])).toEqual([]);
    });

    it('keeps compatible instances together in their original order', () => {
        const first = makeMeshInstance();
        const second = makeMeshInstance();
        const third = makeMeshInstance();

        expect(manager.prepare([first, second, third])).toEqual([[first, second, third]]);
    });

    it('splits when materials differ', () => {
        const first = makeMeshInstance();
        const second = makeMeshInstance({ material: {} });

        expect(manager.prepare([first, second])).toEqual([[first], [second]]);
    });

    it('splits when layers differ', () => {
        const first = makeMeshInstance();
        const second = makeMeshInstance({ layer: {} });

        expect(manager.prepare([first, second])).toEqual([[first], [second]]);
    });

    it('splits when vertex formats are batching-incompatible', () => {
        const first = makeMeshInstance();
        const second = makeMeshInstance({ batchingHash: 2 });

        expect(manager.prepare([first, second])).toEqual([[first], [second]]);
    });

    it('splits indexed and non-indexed geometry', () => {
        const first = makeMeshInstance();
        const second = makeMeshInstance({ indexed: false });

        expect(manager.prepare([first, second])).toEqual([[first], [second]]);
    });

    it('splits when shader defines differ', () => {
        const first = makeMeshInstance({ shaderDefs: 1 });
        const second = makeMeshInstance({ shaderDefs: 2 });

        expect(manager.prepare([first, second])).toEqual([[first], [second]]);
    });

    it('splits instanced bounds larger than maxAabbSize but allows the exact limit', () => {
        const left = makeMeshInstance({ centerX: -1 });
        const right = makeMeshInstance({ centerX: 1 });
        const tooFar = makeMeshInstance({ centerX: 1.5 });

        // Union half extent is exactly 2 for left/right, and 2.25 for left/tooFar.
        expect(manager.prepare([left, right], false, 4)).toEqual([[left, right]]);
        expect(manager.prepare([left, tooFar], false, 4)).toEqual([[left], [tooFar]]);
    });

    it('splits instances whose stencil settings are missing or different', () => {
        const first = makeMeshInstance({ stencilFront: { func: 1, zpass: 2 } });
        const same = makeMeshInstance({ stencilFront: { func: 1, zpass: 2 } });
        const different = makeMeshInstance({ stencilFront: { func: 1, zpass: 3 } });
        const missing = makeMeshInstance({ stencilFront: null });

        expect(manager.prepare([first, same])).toEqual([[first, same]]);
        expect(manager.prepare([first, different])).toEqual([[first], [different]]);
