    });

    it('splits instances with opposite world scale signs', () => {
        const positive = makeMeshInstance();
        const negative = makeMeshInstance({ scaleSign: -1 });

        expect(manager.prepare([positive, negative])).toEqual([[positive], [negative]]);
    });

