        const normal = makeMeshInstance();
        const caster = makeMeshInstance({ castShadow: true });
        const cascaded = makeMeshInstance({ shadowCascadeMask: 4 });
        const sameCascade = makeMeshInstance({ shadowCascadeMask: 4 });

        expect(manager.prepare([normal, caster])).toEqual([[normal], [caster]]);
        expect(manager.prepare([normal, cascaded])).toEqual([[normal], [cascaded]]);
        expect(manager.prepare([cascaded, sameCascade])).toEqual([[cascaded, sameCascade]]);
    });

    it('splits on parameter sets and accepts equal parameter data from distinct arrays', () => {
        const first = makeMeshInstance({ parameters: parameter(1) });
        const same = makeMeshInstance({ parameters: parameter(1) });
        const differentValue = makeMeshInstance({ parameters: parameter(2) });
        const differentName = makeMeshInstance({ parameters: parameter(1, 'u_other') });

        expect(manager.prepare([first, same])).toEqual([[first, same]]);
        expect(manager.prepare([first, differentValue])).toEqual([[first], [differentValue]]);
        expect(manager.prepare([first, differentName])).toEqual([[first], [differentName]]);
    });

