        const huge = makeMeshInstance({ vertices: 0xffffffff });
        const extra = makeMeshInstance({ vertices: 1 });

        expect(manager.prepare([huge, extra])).toEqual([[huge], [extra]]);
    });

    it('limits dynamic batches to 1024 instances', () => {
        const instances = Array.from({ length: 1025 }, () => makeMeshInstance());
        const lists = manager.prepare(instances, true);

        expect(lists).toHaveLength(2);
        expect(lists[0]).toHaveLength(1024);
        expect(lists[1]).toHaveLength(1);
        expect(lists.flat()).toEqual(instances);
    });

    it('does not apply the dynamic instance limit to static batches', () => {
        const instances = Array.from({ length: 1025 }, () => makeMeshInstance());
        const lists = manager.prepare(instances, false);

        expect(lists).toHaveLength(1);
        expect(lists[0]).toHaveLength(1025);
    });

    it('sorts translucent input by drawOrder', () => {
        const later = makeMeshInstance({ drawOrder: 10, centerX: 100 });
        const earlier = makeMeshInstance({ drawOrder: -2, centerX: -100 });

        const lists = manager.prepare([later, earlier], false, Infinity, true);

        expect(lists).toEqual([[earlier, later]]);
        expect([later, earlier]).toEqual([earlier, later]);
    });

    it('separates overlapping translucent instances with different draw orders', () => {
        const first = makeMeshInstance({ drawOrder: 0 });
        const second = makeMeshInstance({ drawOrder: 1 });
        const sameOrder = makeMeshInstance({ drawOrder: 0 });

        expect(manager.prepare([first, second], false, Infinity, true)).toEqual([[first], [second]]);
        expect(manager.prepare([first, sameOrder], false, Infinity, true)).toEqual([[first, sameOrder]]);
    });

    it('handles batches split by several independent constraints', () => {
        const first = makeMeshInstance({ centerX: -5 });
        const same = makeMeshInstance({ centerX: -5 });
        const otherMaterial = makeMeshInstance({ centerX: -5, material: {} });
        const otherLayer = makeMeshInstance({ centerX: -5, layer: {} });
        const farAway = makeMeshInstance({ centerX: 20 });

        const lists = manager.prepare([first, same, otherMaterial, otherLayer, farAway], false, 10);

        expect(lists).toEqual([
            [first, same],
            [otherMaterial],
            [otherLayer],
            [farAway]
        ]);
    });
});
