            const node = modelNode({ groupId: 4, meshInstances: [instance] });
            const existing = [meshInstance('existing')];
            const groupMeshInstances = {};

            const result = manager._extractModel(node, existing, {}, groupMeshInstances);

            expect(result).toBe(existing);
            expect(groupMeshInstances).toEqual({});
            expect(node.model.removeModelFromLayers).not.toHaveBeenCalled();
            expect(node.model.addModelToLayers).toHaveBeenCalledTimes(1);
