                add(this.cameraParams, UNIFORMTYPE_VEC4);
                if (type === LIGHTTYPE_DIRECTIONAL) {
                    add(this.softShadowParams, UNIFORMTYPE_VEC4);
                    add(this.shadowCascadeParams, UNIFORMTYPE_MAT4);
                }
