    'LIGHTSHAPE_PUNCTUAL': `${LIGHTSHAPE_PUNCTUAL}u`,
    'LIGHTSHAPE_RECT': `${LIGHTSHAPE_RECT}u`,
    'LIGHTSHAPE_DISK': `${LIGHTSHAPE_DISK}u`,
    'LIGHTSHAPE_SPHERE': `${LIGHTSHAPE_SPHERE}u`,
    'LIGHT_COLOR_DIVIDER': `${LIGHT_COLOR_DIVIDER}.0`
