        this.updateParams(lightingParams);
        this.updateCells();
        this.collectLights(lights);
        this.evaluateBounds();
        this.updateClusters(lightingParams);
        this.uploadTextures();
    }

    // called on already updated clusters, activates for rendering by setting up uniforms / textures on the device
    activate() {
        this.updateUniforms();
    }
