        }

        if (deviceType === DEVICETYPE_WEBGL2 || deviceType === DEVICETYPE_WEBGL2_BARE) {
            deviceCreateFuncs.push(() => {
                return new WebglGraphicsDevice(canvas, { ...options, deviceType });
