                // WebGL device when WebGL 2 is unavailable) is handled below as a rejection,
                // rather than escaping from next
                new Promise((resolveAttempt) => {
                    resolveAttempt(deviceCreateFuncs[attempt++]());
                }).then((device) => {
                    if (device) {
                        resolve(device);
                    } else {
                        next();
                    }
                }).catch((err) => {
                    console.log(err);
                    errors.push(err);
                    next();
                });
