import { describe, expect, it } from '@jest/globals';

import { LightList } from '../../../src/scene/lighting/light-list.js';
import {
    LIGHTTYPE_DIRECTIONAL,
    LIGHTTYPE_OMNI,
    LIGHTTYPE_SPOT,
    MASK_AFFECT_DYNAMIC,
    MASK_AFFECT_LIGHTMAPPED,
    MASK_AFFECT_RUNTIME
} from '../../../src/scene/constants.js';

const makeLight = (type, key, {
    enabled = true,
    mask = MASK_AFFECT_DYNAMIC
} = {}) => ({
    _type: type,
    key,
    enabled,
    mask
});

describe('LightList', () => {
    it('starts with empty observable state', () => {
        const list = new LightList();

        expect(list.slots).toEqual([]);
        expect(list.directional).toEqual([]);
        expect(list.key).toBe('');
        expect(list.hash).toBe(0);
        expect(list.clustered).toBe(true);
    });

    it('partitions enabled directional lights and orders runtime slots by type, reach and key', () => {
        const list = new LightList();
        const directional = makeLight(LIGHTTYPE_DIRECTIONAL, 7, { mask: MASK_AFFECT_RUNTIME });
        const omniBoth = makeLight(LIGHTTYPE_OMNI, 1, { mask: MASK_AFFECT_RUNTIME });
        const omniDynamic = makeLight(LIGHTTYPE_OMNI, 10, { mask: MASK_AFFECT_DYNAMIC });
        const omniLightmapped = makeLight(LIGHTTYPE_OMNI, 3, { mask: MASK_AFFECT_LIGHTMAPPED });
        const spot = makeLight(LIGHTTYPE_SPOT, 5, { mask: MASK_AFFECT_DYNAMIC });
        const disabled = makeLight(LIGHTTYPE_OMNI, 2, { enabled: false, mask: MASK_AFFECT_RUNTIME });

        list.update([omniDynamic, directional, spot, omniLightmapped, disabled, omniBoth], false);

        expect(list.slots.map(light => light.key)).toEqual([7, 1, 10, 3, 5]);
        expect(list.directional).toEqual([directional]);
        expect(list.key).toBe('7,1,10,3,5,');
        expect(Number.isInteger(list.hash)).toBe(true);
        expect(list.hash).not.toBe(0);
        expect(list.clustered).toBe(false);
    });

    it('keeps only directional lights in slots when clustered lighting is enabled', () => {
        const list = new LightList();
        const dirRuntime = makeLight(LIGHTTYPE_DIRECTIONAL, 4, { mask: MASK_AFFECT_RUNTIME });
        const dirNoRuntime = makeLight(LIGHTTYPE_DIRECTIONAL, 8, { mask: 0 });
        const omni = makeLight(LIGHTTYPE_OMNI, 2, { mask: MASK_AFFECT_RUNTIME });

        list.update([dirRuntime, omni, dirNoRuntime], true);

        expect(list.slots).toEqual([dirRuntime]);
        expect(list.directional).toEqual([dirRuntime, dirNoRuntime]);
        expect(list.key).toBe('4,');
        expect(list.clustered).toBe(true);
    });

    it('excludes lights that have no runtime mask even when they are otherwise eligible', () => {
        const list = new LightList();
        const lightmapped = makeLight(LIGHTTYPE_SPOT, 11, { mask: MASK_AFFECT_LIGHTMAPPED });
        const both = makeLight(LIGHTTYPE_SPOT, 12, { mask: MASK_AFFECT_RUNTIME });

        list.update([lightmapped, both], false);

        expect(list.slots).toEqual([both]);
        expect(list.key).toBe('12,');
    });

    it('produces the same layout for the same light set in any input order', () => {
        const list = new LightList();
        const a = makeLight(LIGHTTYPE_OMNI, 30, { mask: MASK_AFFECT_RUNTIME });
        const b = makeLight(LIGHTTYPE_OMNI, 10, { mask: MASK_AFFECT_DYNAMIC });
        const c = makeLight(LIGHTTYPE_OMNI, 20, { mask: MASK_AFFECT_LIGHTMAPPED });

        list.update([a, b, c], false);
        const key = list.key;
        const hash = list.hash;

        list.update([c, a, b], false);

        expect(list.key).toBe(key);
        expect(list.key).toBe('30,10,20,');
        expect(list.hash).toBe(hash);
    });

    it('reuses its arrays and resets the layout on an empty update', () => {
        const list = new LightList();
        const slots = list.slots;
        const directional = list.directional;
        const light = makeLight(LIGHTTYPE_DIRECTIONAL, 9, { mask: MASK_AFFECT_RUNTIME });

        list.update([light], false);
        expect(list.slots).toBe(slots);
        expect(list.directional).toBe(directional);

        list.update([], true);

        expect(list.slots).toBe(slots);
        expect(list.directional).toBe(directional);
        expect(list.slots).toHaveLength(0);
        expect(list.directional).toHaveLength(0);
        expect(list.key).toBe('');
        expect(list.hash).toBe(0);
    });
});
