import { afterEach, beforeEach, describe, expect, it, jest } from '@jest/globals';

import { LightsBuffer } from '../../../src/scene/lighting/lights-buffer.js';
import { NullGraphicsDevice } from '../../../src/platform/graphics/null/null-graphics-device.js';
import { Mat4 } from '../../../src/core/math/mat4.js';
import { Vec3 } from '../../../src/core/math/vec3.js';
import { Vec4 } from '../../../src/core/math/vec4.js';
import { FloatPacking } from '../../../src/core/math/float-packing.js';
import {
    FILTER_NEAREST,
    PIXELFORMAT_RGBA32F
} from '../../../src/platform/graphics/constants.js';
import {
    LIGHTSHAPE_PUNCTUAL,
    LIGHTSHAPE_RECT,
    LIGHTTYPE_OMNI,
    LIGHTTYPE_SPOT
} from '../../../src/scene/constants.js';

const FLOATS_PER_LIGHT = 9;
const ROW = 4;
const POSITION_RANGE = 0;
const DIRECTION_FLAGS = 1;
const COLOR_ANGLES_BIAS = 2;
const PROJ_MAT_0 = 3;
const ATLAS_VIEWPORT = 3;
const AREA_DATA_WIDTH = 7;
const AREA_DATA_HEIGHT = 8;

const makeWtm = (position = new Vec3(), scale = new Vec3(1, 1, 1)) => {
    const wtm = new Mat4();
    wtm.data[0] = scale.x;
    wtm.data[5] = scale.y;
    wtm.data[10] = scale.z;
    wtm.data[12] = position.x;
    wtm.data[13] = position.y;
    wtm.data[14] = position.z;
    return wtm;
};

const makeLight = (overrides = {}) => {
    const position = overrides.position ?? new Vec3(1, 2, 3);
    const wtm = overrides.wtm ?? makeWtm(position);
    const light = {
        _type: LIGHTTYPE_OMNI,
        _node: {
            getWorldTransform: () => wtm,
            getPosition: () => position
        },
        _cookie: null,
        _shape: LIGHTSHAPE_PUNCTUAL,
        attenuationEnd: 10,
        atlasViewportAllocated: false,
        atlasViewport: new Vec4(0.25, 0.5, 0.75, 0.25),
        castShadows: false,
        clusteredData: new Uint32Array([0x1111, 0x2222, 0x3333]),
        getClusteredFlags: jest.fn(() => 0xabcd),
        getRenderData: jest.fn(() => ({
            shadowMatrix: { data: new Float32Array(16) }
        })),
        _getUniformBiasValues: jest.fn(() => ({ bias: 0.25, normalBias: 1.5 }))
    };
    return Object.assign(light, overrides);
};

describe('LightsBuffer', () => {
    let device;
    let buffer;

    beforeEach(() => {
        device = new NullGraphicsDevice();
        buffer = new LightsBuffer(device);
    });

    afterEach(() => {
        buffer?.destroy();
        device?.destroy();
    });

    it('allocates a texture with one row for every light slot', () => {
        expect(buffer.maxLights).toBe(256);
        expect(buffer.lightsFloat).toBeInstanceOf(Float32Array);
        expect(buffer.lightsFloat).toHaveLength(4 * FLOATS_PER_LIGHT * 256);
        expect(buffer.lightsUint).toHaveLength(4 * FLOATS_PER_LIGHT * 256);
        expect(buffer.lightsTexture.name).toBe('LightsTexture');
        expect(buffer.lightsTexture.width).toBe(FLOATS_PER_LIGHT);
        expect(buffer.lightsTexture.height).toBe(256);
        expect(buffer.lightsTexture.format).toBe(PIXELFORMAT_RGBA32F);
        expect(buffer.lightsTexture.mipmaps).toBe(false);
        expect(buffer.lightsTexture.magFilter).toBe(FILTER_NEAREST);
        expect(buffer.lightsTexture.minFilter).toBe(FILTER_NEAREST);
    });

    it('reallocates storage only when the light count changes', () => {
        const initialTexture = buffer.lightsTexture;
        buffer.maxLights = 256;

        expect(buffer.lightsTexture).toBe(initialTexture);

        buffer.maxLights = 3;

        expect(buffer.maxLights).toBe(3);
        expect(buffer.lightsTexture).not.toBe(initialTexture);
        expect(initialTexture.device).toBeNull();
        expect(buffer.lightsTexture.width).toBe(FLOATS_PER_LIGHT);
        expect(buffer.lightsTexture.height).toBe(3);
        expect(buffer.lightsFloat).toHaveLength(4 * FLOATS_PER_LIGHT * 3);
    });

    it('stores the bounds used by the GPU shader', () => {
        buffer.setBounds(new Vec3(-2, 3, 4), new Vec3(8, 9, 10));

        expect(buffer.boundsMin.toArray()).toEqual([-2, 3, 4]);
        expect(buffer.boundsDelta.toArray()).toEqual([8, 9, 10]);
    });

    it('derives spot directions from the light world transform', () => {
        const direction = new Vec3();
        const rotated = new Mat4().setFromEulerAngles(0, 0, 90);
        const spot = {
            _node: {
                getWorldTransform: () => rotated
            }
        };

        buffer.getSpotDirection(direction, spot);

        expect(direction.x).toBeCloseTo(-1);
        expect(direction.y).toBeCloseTo(0);
        expect(direction.z).toBeCloseTo(0);
        expect(direction.length()).toBeCloseTo(1);
    });

    it('returns world-space half extents for area lights', () => {
        const light = {
            _node: {
                getWorldTransform: () => makeWtm(new Vec3(5, 6, 7), new Vec3(2, 2, 3))
            }
        };

        const sizes = buffer.getLightAreaSizes(light);

        expect(Array.from(sizes)).toEqual([-1, 0, 0, 0, 0, 1.5]);
    });

    it('encodes an omni light position, range, color data and clustered flags', () => {
        buffer.maxLights = 4;
        const light = makeLight();
        const lightIndex = 2;
