    const position = overrides.position ?? new Vec3(1, 2, 3);
    const wtm = overrides.wtm ?? makeWtm(position);
    return Object.assign({
        _type: LIGHTTYPE_OMNI,
        _shape: LIGHTSHAPE_PUNCTUAL,
        _node: {
            getWorldTransform: () => wtm,
            getPosition: () => position
        },
        _colorLinear: new Vec3(0.1, 0.2, 0.3),
        _direction: new Vec3(),
