        expect(clusters.lightsBuffer.maxLights).toBe(256);
        expect(clusters.maxCellLightCount).toBe(4);
        expect(clusters.cells.toArray()).toEqual([1, 1, 1]);
        expect(clusters.boundsMin.toArray()).toEqual([0, 0, 0]);
        expect(clusters.boundsMax.toArray()).toEqual([0, 0, 0]);
        expect(clusters.boundsDelta.toArray()).toEqual([0, 0, 0]);
        expect(clusters.usedLights).toHaveLength(1);
        expect(clusters.usedLights[0].light).toBeNull();
        expect(clusters.clusterTexture).toBeUndefined();
    });

    it('floors cell counts and updates the cell limit', () => {
        const cells = clusters.cells;

        clusters.cells = new Vec3(2.9, 3.1, 4.8);

        expect(clusters.cells).toBe(cells);
