        expect(clusters.clusters).toBeInstanceOf(Uint8ClampedArray);
        expect(clusters.counts).toHaveLength(2 * 3 * 4);
        expect(clusters.clusterTexture.width).toBe(14);
        expect(clusters.clusterTexture.height).toBe(12);
        expect(Array.from(clusters._clusterCellsMaxData)).toEqual([2, 3, 4]);
        expect(Array.from(clusters._clusterCellsDotData)).toEqual([7, 2 * 4 * 7, 2 * 7]);

        const storage = clusters.clusters;
        clusters.updateCells();
        expect(clusters.clusters).toBe(storage);
    });

    it('uses 16-bit cluster indices above 255 lights', () => {
        clusters.cells = new Vec3(1, 1, 1);
        clusters.maxCellLightCount = 2;
        clusters.maxLights = 256;
        clusters.updateCells();

        expect(clusters.clusters).toBeInstanceOf(Uint16Array);
        expect(clusters.clusters).toHaveLength(2);
        expect(clusters.lightsBuffer.lightsTexture.height).toBe(257);
    });

    it('propagates lighting parameters to clustering and the light buffer', () => {
        const params = createParams({
            cells: new Vec3(2.8, 3.9, 4.2),
            maxLightsPerCell: 7,
            maxLights: 12,
            cookiesEnabled: true,
            shadowsEnabled: false,
            areaLightsEnabled: true
        });

        clusters.updateParams(params);

        expect(clusters.cells.toArray()).toEqual([2, 3, 4]);
        expect(clusters.maxCellLightCount).toBe(7);
        expect(clusters.maxLights).toBe(12);
        expect(clusters.lightsBuffer.cookiesEnabled).toBe(true);
        expect(clusters.lightsBuffer.shadowsEnabled).toBe(false);
        expect(clusters.lightsBuffer.areaLightsEnabled).toBe(true);

        clusters.updateParams(null);
        expect(clusters.cells.toArray()).toEqual([2, 3, 4]);
        expect(clusters.lightsBuffer.cookiesEnabled).toBe(true);
    });

    it('collects only eligible local runtime lights and reuses cluster-light records', () => {
        const validOmni = makeClusterLight({ min: new Vec3(-2, -2, -2), max: new Vec3(0, 0, 0) });
        const validSpot = makeClusterLight({
            type: LIGHTTYPE_SPOT,
            min: new Vec3(1, 1, 1),
            max: new Vec3(3, 3, 3)
        });
        const excluded = [
            makeClusterLight({ type: LIGHTTYPE_DIRECTIONAL }),
            makeClusterLight({ enabled: false }),
            makeClusterLight({ visible: false }),
            makeClusterLight({ intensity: 0 }),
            makeClusterLight({ mask: 0 }),
            makeClusterLight({ type: LIGHTTYPE_SPOT, outerConeAngle: 0 })
        ];

        clusters.collectLights([validOmni, ...excluded, validSpot]);

        expect(clusters.usedLights).toHaveLength(3);
        expect(clusters.usedLights[0].light).toBeNull();
        expect(clusters.usedLights[1].light).toBe(validOmni);
        expect(clusters.usedLights[1].min.toArray()).toEqual([-2, -2, -2]);
        expect(clusters.usedLights[1].max.toArray()).toEqual([0, 0, 0]);
        expect(clusters.usedLights[2].light).toBe(validSpot);

        const record = clusters.usedLights[1];
        clusters.collectLights([validOmni]);
        expect(clusters.usedLights).toHaveLength(2);
        expect(clusters.usedLights[1]).toBe(record);
    });

    it('stops collecting once the light limit is reached', () => {
        clusters.maxLights = 1;
        const first = makeClusterLight();
        const second = makeClusterLight();

        clusters.collectLights([first, second]);

        expect(clusters.usedLights).toHaveLength(2);
        expect(clusters.usedLights[1].light).toBe(first);
    });

    it('evaluates the union of collected light bounds', () => {
        const first = makeClusterLight({ min: new Vec3(-4, 1, 2), max: new Vec3(-1, 3, 6) });
        const second = makeClusterLight({ min: new Vec3(0, -2, 4), max: new Vec3(5, 1, 8) });
        clusters.collectLights([first, second]);

        clusters.evaluateBounds();

        expect(clusters.boundsMin.toArray()).toEqual([-4, -2, 2]);
        expect(clusters.boundsMax.toArray()).toEqual([5, 3, 8]);
        expect(clusters.boundsDelta.toArray()).toEqual([9, 5, 6]);
        expect(clusters.lightsBuffer.boundsMin.toArray()).toEqual([-4, -2, 2]);
        expect(clusters.lightsBuffer.boundsDelta.toArray()).toEqual([9, 5, 6]);
    });

    it('uses a unit fallback volume when no lights were collected', () => {
        clusters.evaluateBounds();

        expect(clusters.boundsMin.toArray()).toEqual([0, 0, 0]);
        expect(clusters.boundsMax.toArray()).toEqual([1, 1, 1]);
        expect(clusters.boundsDelta.toArray()).toEqual([1, 1, 1]);
    });

    it('clamps world-space light bounds to cluster cells', () => {
        clusters.cells = new Vec3(2, 2, 2);
        clusters.boundsMin.set(0, 0, 0);
        clusters.boundsDelta.set(10, 10, 10);
        const inside = { min: new Vec3(1, 1, 1), max: new Vec3(6, 6, 6) };
        const outside = { min: new Vec3(-50, 6, 9), max: new Vec3(50, 100, 100) };
        const min = new Vec3();
        const max = new Vec3();

        clusters.evalLightCellMinMax(inside, min, max);
        expect(min.toArray()).toEqual([0, 0, 0]);
        expect(max.toArray()).toEqual([1, 1, 1]);

        clusters.evalLightCellMinMax(outside, min, max);
        expect(min.toArray()).toEqual([0, 1, 1]);
        expect(max.toArray()).toEqual([1, 1, 1]);
    });

    it('fills every covered cell with the light index up to the per-cell limit', () => {
        clusters.cells = new Vec3(2, 2, 2);
        clusters.maxCellLightCount = 2;
        clusters.updateCells();
        const light = makeClusterLight({ min: new Vec3(0, 0, 0), max: new Vec3(10, 10, 10) });
        clusters.collectLights([light]);
        clusters.evaluateBounds();

        clusters.updateClusters(null);

        expect(Array.from(clusters.counts)).toEqual(Array(8).fill(1));
        for (let cell = 0; cell < 8; cell++) {
            expect(clusters.clusters[cell * 2]).toBe(1);
            expect(clusters.clusters[cell * 2 + 1]).toBe(0);
        }
    });

    it('reports when a cell exceeds its light limit and caps the report count', () => {
        clusters.cells = new Vec3(1, 1, 1);
        clusters.maxCellLightCount = 1;
        clusters.updateCells();
        const first = makeClusterLight({ min: new Vec3(0, 0, 0), max: new Vec3(10, 10, 10) });
        const second = makeClusterLight({ min: new Vec3(0, 0, 0), max: new Vec3(10, 10, 10) });
        clusters.collectLights([first, second]);
        clusters.evaluateBounds();
        const warn = jest.spyOn(console, 'warn').mockImplementation(() => {});

        try {
            for (let i = 0; i < 6; i++) {
                clusters.updateClusters(null);
            }

            expect(clusters.counts[0]).toBe(1);
            expect(clusters.clusters[0]).toBe(1);
            expect(warn).toHaveBeenCalledTimes(5);
            expect(warn.mock.calls[4][0]).toContain('Giving up on reporting it.');
            expect(clusters.reportCount).toBe(5);
        } finally {
            warn.mockRestore();
        }
    });

    it('runs the complete update workflow and activates its uniforms', () => {
        const params = createParams({ cells: new Vec3(2, 1, 1), maxLightsPerCell: 2, maxLights: 4 });
        const light = makeClusterLight({ min: new Vec3(0, 0, 0), max: new Vec3(10, 10, 10) });

        clusters.update([light], params);

        expect(clusters.usedLights).toHaveLength(2);
        expect(clusters.boundsMin.toArray()).toEqual([0, 0, 0]);
        expect(clusters.boundsDelta.toArray()).toEqual([10, 10, 10]);
        expect(clusters.counts).toHaveLength(2);
        expect(Array.from(clusters.counts)).toEqual([1, 1]);
        expect(clusters.clusters).toHaveLength(4);
        expect(clusters.clusterTexture).not.toBeNull();
        expect(clusters.lightsBuffer.lightsTexture.height).toBe(5);

        clusters.activate();

        expect(device.scope.resolve('numClusteredLights').getValue()).toBe(2);
        expect(device.scope.resolve('clusterMaxCells').getValue()).toBe(2);
        expect(device.scope.resolve('clusterWorldTexture').getValue()).toBe(clusters.clusterTexture);
        expect(Array.from(device.scope.resolve('clusterBoundsMin').getValue())).toEqual([0, 0, 0]);
        expect(Array.from(device.scope.resolve('clusterBoundsDelta').getValue())).toEqual([10, 10, 10]);
        expect(Array.from(device.scope.resolve('clusterCellCountByBoundsSize').getValue?.() ?? []))
            .toEqual([]);
        expect(Array.from(device.scope.resolve('clusterCellsCountByBoundsSize').getValue()))
            .toEqual([0.2, 0.1, 0.1].map(value => expect.closeTo(value, 6)));
        expect(Array.from(device.scope.resolve('clusterCellsDot').getValue())).toEqual([2, 4, 4]);
        expect(Array.from(device.scope.resolve('clusterCellsMax').getValue())).toEqual([2, 1, 1]);
        expect(device.scope.resolve('clusterTextureWidth').getValue()).toBe(clusters.clusterTexture.width);
        expect(device.scope.resolve('lightsTexture').getValue()).toBe(clusters.lightsBuffer.lightsTexture);
    });

    it('handles an update with no lights', () => {
        clusters.update([], createParams());

        expect(clusters.usedLights).toHaveLength(1);
        expect(clusters.boundsMin.toArray()).toEqual([0, 0, 0]);
        expect(clusters.boundsMax.toArray()).toEqual([1, 1, 1]);
        expect(Array.from(clusters.counts).every(value => value === 0)).toBe(true);
        expect(Array.from(clusters.clusters).every(value => value === 0)).toBe(true);
    });

    it('releases its cluster texture and buffer on destroy', () => {
        clusters.update([], createParams());
        const texture = clusters.clusterTexture;
        const lightsTexture = clusters.lightsBuffer.lightsTexture;

        clusters.destroy();

        expect(texture.device).toBeNull();
        expect(lightsTexture.device).toBeNull();
        expect(clusters.clusterTexture).toBeNull();
        expect(clusters.lightsBuffer.lightsTexture).toBeNull();
        expect(() => clusters.destroy()).not.toThrow();
    });
});
