import { afterEach, describe, expect, it, jest } from '@jest/globals';

import { WorldClustersDebug } from '../../../src/scene/lighting/world-clusters-debug.js';
import { NullGraphicsDevice } from '../../../src/platform/graphics/null/null-graphics-device.js';
import { Vec3 } from '../../../src/core/math/vec3.js';
import { BLEND_ADDITIVEALPHA } from '../../../src/scene/constants.js';

const makeWorldClusters = ({
    cells = new Vec3(2, 1, 2),
    boundsMin = new Vec3(0, 0, 0),
    boundsDelta = new Vec3(2, 1, 2),
    countLimit = 2
} = {}) => {
    const counts = new Int32Array(cells.x * cells.y * cells.z);
    return {
        cells,
        _cells: cells,
        counts,
        _maxCellLightCount: countLimit,
        lightsBuffer: {
            boundsMin,
            boundsDelta
        }
    };
};

const makeScene = () => {
    const defaultDrawLayer = { name: 'draw-layer' };
    return {
        device: new NullGraphicsDevice(),
        defaultDrawLayer,
        drawLineArrays: jest.fn()
    };
};

describe('WorldClustersDebug', () => {
    let debug;

    afterEach(() => {
        debug?.destroy();
    });

    it('has an empty initial state and default occupancy colors', () => {
        debug = new WorldClustersDebug();

        expect(debug.gridPositions).toEqual([]);
        expect(debug.gridColors).toEqual([]);
        expect(debug.mesh).toBeNull();
        expect(debug.meshInstance).toBeNull();
        expect(debug._pendingMeshInstance).toBeNull();
        expect(debug._layer).toBeNull();
        expect(debug.colorLow.toArray()).toEqual([1, 1, 1]);
        expect(debug.colorHigh.toArray()).toEqual([40, 0, 0]);
    });

    it('only injects a pending mesh instance into its own layer and clears it', () => {
        debug = new WorldClustersDebug();
        const pending = { name: 'pending' };
        const layerA = { name: 'A' };
        const layerB = { name: 'B' };
        debug._pendingMeshInstance = pending;
        debug._layer = layerA;

        const otherVisible = [];
        debug.onPreRenderLayer(layerB, otherVisible);
        expect(otherVisible).toEqual([]);
        expect(debug._pendingMeshInstance).toBe(pending);

        const matchingVisible = [];
        debug.onPreRenderLayer(layerA, matchingVisible);
        expect(matchingVisible).toEqual([pending]);
        expect(debug._pendingMeshInstance).toBeNull();
        expect(debug._layer).toBeNull();
    });

    it('frameUpdate discards a pending mesh instance and layer', () => {
        debug = new WorldClustersDebug();
        debug._pendingMeshInstance = {};
        debug._layer = {};

        debug.frameUpdate();

        expect(debug._pendingMeshInstance).toBeNull();
        expect(debug._layer).toBeNull();
    });

    it('draws the complete cell grid and consumes the position buffer', () => {
        debug = new WorldClustersDebug();
        const scene = makeScene();
        const worldClusters = makeWorldClusters();

        try {
            debug.render(worldClusters, scene);

            const [positions, colors] = scene.drawLineArrays.mock.calls[0];
            expect(positions).toHaveLength(126);
            expect(colors).toHaveLength(168);
            expect(positions.slice(0, 12)).toEqual([
                0, 0, 0, 0, 1, 0,
                0, 0, 1, 0, 1, 1
            ]);
            expect(colors.slice(0, 4)).toEqual([0.3, 0.3, 0.3, 1]);
            expect(debug.gridPositions).toHaveLength(0);
            expect(debug.gridColors).toHaveLength(168);
            expect(debug.mesh).not.toBeNull();
            expect(debug.meshInstance).toBeNull();
            expect(debug._pendingMeshInstance).toBeNull();
            expect(debug._layer).toBeNull();
        } finally {
            scene.device.destroy();
        }
    });

    it('creates a cube mesh and renderable instance for occupied cells', () => {
        debug = new WorldClustersDebug();
        const scene = makeScene();
        const worldClusters = makeWorldClusters();
        worldClusters.counts[0] = 1;
        debug.colorLow.set(0, 0, 0);
        debug.colorHigh.set(10, 20, 30);

        try {
            debug.render(worldClusters, scene);

            expect(debug.mesh).not.toBeNull();
            expect(debug.meshInstance).not.toBeNull();
            expect(debug.meshInstance.cull).toBe(false);
            expect(debug.meshInstance.castShadow).toBe(false);
            expect(debug.meshInstance.material.useLighting).toBe(false);
            expect(debug.meshInstance.material.emissiveVertexColor).toBe(true);
            expect(debug.meshInstance.material.blendType).toBe(BLEND_ADDITIVEALPHA);
            expect(debug.meshInstance.material.depthWrite).toBe(false);
            expect(debug._pendingMeshInstance).toBe(debug.meshInstance);
            expect(debug._layer).toBe(scene.defaultDrawLayer);

            const positions = [];
            const colors = [];
            const indices = [];
            expect(debug.mesh.getPositions(positions)).toBe(8);
            expect(positions.slice(0, 3)).toEqual([0, 0, 1]);
            expect(debug.mesh.getColors(colors)).toBe(8);
            expect(colors.slice(0, 8)).toEqual([5, 10, 15, 1, 5, 10, 15, 1]);
            expect(debug.mesh.getIndices(indices)).toBe(36);
            expect(indices.slice(0, 6)).toEqual([0, 1, 3, 3, 1, 2]);
        } finally {
            scene.device.destroy();
        }
    });

    it('encodes one cube per occupied cell and reuses the mesh across frames', () => {
        debug = new WorldClustersDebug();
        const scene = makeScene();
        const worldClusters = makeWorldClusters();
        worldClusters.counts[0] = 1;
        worldClusters.counts[3] = 2;

        try {
            debug.render(worldClusters, scene);
            const mesh = debug.mesh;
            const instance = debug.meshInstance;

            const positions = [];
            const indices = [];
            expect(debug.mesh.getPositions(positions)).toBe(16);
            expect(debug.mesh.getIndices(indices)).toBe(72);
            expect(indices[36]).toBe(8);

            debug.render(worldClusters, scene);

            expect(debug.mesh).toBe(mesh);
            expect(debug.meshInstance).toBe(instance);
            expect(debug._pendingMeshInstance).toBe(instance);
        } finally {
            scene.device.destroy();
        }
    });

    it('pushes the generated mesh instance into the next matching layer render', () => {
        debug = new WorldClustersDebug();
        const scene = makeScene();
        const worldClusters = makeWorldClusters();
        worldClusters.counts[0] = 1;

        try {
            debug.render(worldClusters, scene);
            const instance = debug.meshInstance;
            const visibleList = [];

            debug.onPreRenderLayer(scene.defaultDrawLayer, visibleList);

            expect(visibleList).toEqual([instance]);
            expect(debug._pendingMeshInstance).toBeNull();
            expect(debug._layer).toBeNull();
        } finally {
            scene.device.destroy();
        }
    });

    it('destroys a mesh created without occupied cells', () => {
        debug = new WorldClustersDebug();
        const scene = makeScene();
        const worldClusters = makeWorldClusters();

        try {
            debug.render(worldClusters, scene);
            const mesh = debug.mesh;
            expect(mesh).not.toBeNull();

            debug.destroy();

            expect(debug.mesh).toBeNull();
            expect(debug.meshInstance).toBeNull();
        } finally {
            scene.device.destroy();
        }
    });

    it('destroys an instance, its material and pending layer state', () => {
        debug = new WorldClustersDebug();
        const scene = makeScene();
        const worldClusters = makeWorldClusters();
        worldClusters.counts[0] = 1;

        try {
            debug.render(worldClusters, scene);
            const instance = debug.meshInstance;
            const material = instance.material;

            debug.destroy();
            debug.destroy();

            expect(instance.__alreadyDestroyed).toBe(true);
            expect(material.__alreadyDestroyed).toBe(true);
            expect(debug.meshInstance).toBeNull();
            expect(debug.mesh).toBeNull();
            expect(debug._pendingMeshInstance).toBeNull();
            expect(debug._layer).toBeNull();
        } finally {
            scene.device.destroy();
        }
    });
});
