                // let alpha =              tex1D(emitter.qAlpha, nlife);
                a = emitter.qAlpha[cf];
                b = emitter.qAlpha[cc];
                alpha = a + (b - a) * c;

                // let alpha2 =             tex1D(emitter.qAlpha2, nlife);
                a = emitter.qAlpha2[cf];
                b = emitter.qAlpha2[cc];
