/**
 * Creates a fully initialized null graphics device with the program library and
 * shader chunks required to build particle emitters in a Node environment.
 *
 * @param {object} [options] - Options.
 * @param {boolean} [options.supportsGpuParticles] - Whether the device advertises GPU particles.
 * @returns {NullGraphicsDevice} The graphics device.
 */
export function createTestDevice({ supportsGpuParticles = false } = {}) {
    const device = new NullGraphicsDevice();
    device.supportsGpuParticles = supportsGpuParticles;
    setProgramLibrary(device, new ProgramLibrary(device));

    const chunks = ShaderChunks.get(device, SHADERLANGUAGE_GLSL);
    chunks.add(shaderChunksGLSL);
    chunks.add(particleChunksGLSL);

    return device;
}

/**
 * Creates a particle emitter attached to a freshly created graph node.
 *
 * @param {NullGraphicsDevice} device - The graphics device.
 * @param {object} [options] - Particle emitter options.
 * @param {GraphNode} [node] - Optional node to attach the emitter to.
 * @returns {ParticleEmitter} The particle emitter.
 */
export function createTestEmitter(device, options = {}, node = new GraphNode('particle-emitter')) {
    return new ParticleEmitter(device, {
        node,
        ...options
    });
}
