function readVec3(array, offset = 0) {
    return new Vec3(array[offset], array[offset + 1], array[offset + 2]);
}

const identitySpawnMatrix = () => new Mat4();
const noEmitterPos = () => new Vec3();
const noInnerRatios = () => new Float32Array(3);

let randomSpy;
afterEach(() => {
    randomSpy?.mockRestore();
    randomSpy = null;
});

describe('ParticleCPUUpdater', () => {

    describe('#calcSpawnPosition()', () => {

        test('spawns on a normalized sphere and records the per-particle random state', () => {
            randomSpy = jest.spyOn(Math, 'random')
                .mockReturnValueOnce(0.25)
                .mockReturnValueOnce(0.75)
                .mockReturnValueOnce(0.5)
                .mockReturnValueOnce(0.1);

            const emitter = makeEmitter({
                numParticlesPot: 2,
                emitterShape: EMITTERSHAPE_SPHERE,
                emitterRadius: 10,
                emitterRadiusInner: 0,
                rate: 2,
                rate2: 4,
                startAngle: 0,
                startAngle2: 90
            });
            const tex = emitter.particleTex;
            const i = 1;

            new ParticleCPUUpdater(emitter).calcSpawnPosition(
                tex, identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), i
            );

            const expectedDir = new Vec3(-0.25, 0.25, 0).normalize();
            const base = i * 4;
            expect(tex[base]).toBeCloseTo(expectedDir.x, 5);
            expect(tex[base + 1]).toBeCloseTo(expectedDir.y, 5);
            expect(tex[base + 2]).toBeCloseTo(expectedDir.z, 5);

            // start angle is lerped with the first random value
            expect(tex[base + 3]).toBeCloseTo(22.5 * Math.PI / 180, 6);

            // random state is stored in the third texture row
            const randomOffset = base + emitter.numParticlesPot * 2 * 4;
            expect(tex[randomOffset]).toBeCloseTo(0.25, 6);
            expect(tex[randomOffset + 1]).toBeCloseTo(0.75, 6);
            expect(tex[randomOffset + 2]).toBeCloseTo(0.5, 6);

            // start spawn time is minus the particle rate times the particle index
            const lifeOffset = base + 3 + emitter.numParticlesPot * 4;
            expect(tex[lifeOffset]).toBeCloseTo(-2.5, 6);
        });

        test('respects the inner radius of a spherical emitter', () => {
            randomSpy = jest.spyOn(Math, 'random')
                .mockReturnValueOnce(0.25)
                .mockReturnValueOnce(0.75)
                .mockReturnValueOnce(0.5)
                .mockReturnValueOnce(1);

            const emitter = makeEmitter({
                emitterShape: EMITTERSHAPE_SPHERE,
                emitterRadius: 10,
                emitterRadiusInner: 5
            });
            const tex = emitter.particleTex;

            new ParticleCPUUpdater(emitter).calcSpawnPosition(
                tex, identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0
            );

            const expectedDir = new Vec3(-0.25, 0.25, 0).normalize();
            expect(readVec3(tex).x).toBeCloseTo(expectedDir.x * 10, 5);
            expect(readVec3(tex).y).toBeCloseTo(expectedDir.y * 10, 5);
            expect(readVec3(tex).z).toBeCloseTo(0, 5);
        });

        test('handles a zero-radius sphere without producing NaN coordinates', () => {
            randomSpy = jest.spyOn(Math, 'random').mockReturnValue(0.3);

            const emitter = makeEmitter({
                emitterShape: EMITTERSHAPE_SPHERE,
                emitterRadius: 0
            });
            const tex = emitter.particleTex;

            new ParticleCPUUpdater(emitter).calcSpawnPosition(
                tex, identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0
            );

            expect(tex[0]).toBe(0);
            expect(tex[1]).toBe(0);
            expect(tex[2]).toBe(0);
        });

        test('places box emitter particles on the contour surface and transforms by the spawn matrix', () => {
            randomSpy = jest.spyOn(Math, 'random')
                .mockReturnValueOnce(0.25)
                .mockReturnValueOnce(0.75)
                .mockReturnValueOnce(0.5)
                .mockReturnValueOnce(0.5);

            const emitter = makeEmitter({
                localSpace: true,
                emitterShape: EMITTERSHAPE_BOX
            });
            const spawnMatrix = new Mat4().setTRS(Vec3.ZERO, Quat.IDENTITY, new Vec3(2, 4, 6));
            const tex = emitter.particleTex;
            const ratio = new Float32Array([0, 0, 0]);

            new ParticleCPUUpdater(emitter).calcSpawnPosition(
                tex, spawnMatrix, ratio, noEmitterPos(), 0
            );

            // random position (-0.25, 0.25, 0): max component is 0.25, so the
            // contour point is (-0.25, 0.25, 0), then scaled by the spawn matrix
            expect(tex[0]).toBeCloseTo(-0.5, 6);
            expect(tex[1]).toBeCloseTo(1, 6);
            expect(tex[2]).toBeCloseTo(0, 6);
        });

        test('moves contour points towards the outer shell when the inner ratio is one', () => {
            randomSpy = jest.spyOn(Math, 'random').mockReturnValue(0.75);

            const emitter = makeEmitter({
                localSpace: true,
                emitterShape: EMITTERSHAPE_BOX
