            );

            expect(tex[0]).toBeCloseTo(1, 6);
            expect(tex[1]).toBeCloseTo(2, 6);
            expect(tex[2]).toBeCloseTo(3, 6);
        });

        test('adds the emitter position for world-space emitters', () => {
            randomSpy = jest.spyOn(Math, 'random').mockReturnValue(0.75);

            const emitter = makeEmitter({
                localSpace: false,
                emitterShape: EMITTERSHAPE_BOX
            });
            const spawnMatrix = new Mat4().setTRS(Vec3.ZERO, Quat.IDENTITY, new Vec3(2, 4, 6));
            const tex = emitter.particleTex;

            new ParticleCPUUpdater(emitter).calcSpawnPosition(
                tex, spawnMatrix, new Float32Array([1, 1, 1]), new Vec3(10, 20, 30), 0
            );

            expect(tex[0]).toBeCloseTo(11, 6);
            expect(tex[1]).toBeCloseTo(22, 6);
            expect(tex[2]).toBeCloseTo(33, 6);
        });

        test('does not write random state when the emitter uses GPU particles', () => {
            randomSpy = jest.spyOn(Math, 'random').mockReturnValue(0.75);

            const emitter = makeEmitter({ useCpu: false });
