            emitter.qLocalVelocity[3] = 1;
            emitter.qLocalVelocity[4] = 2;
            emitter.qLocalVelocity[5] = 3;
            emitter.qLocalVelocity2[3] = 1;
            emitter.qLocalVelocity2[4] = 2;
            emitter.qLocalVelocity2[5] = 3;

            emitter.qRotSpeed[1] = 2;
            emitter.qScale[0] = 1;
            emitter.qScale[1] = 3;
            emitter.qScale2[0] = 1;
            emitter.qScale2[1] = 3;
            emitter.qAlpha[0] = 0.2;
            emitter.qAlpha[1] = 1;
            emitter.qAlpha2[0] = 0.2;
            emitter.qAlpha2[1] = 2;

            const data = new Float32Array(4 * 15);
            new ParticleCPUUpdater(emitter).update(
                data, emitter.vbToSort, emitter.particleTex,
                identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0.5, false
            );

            // particle position advanced by velocity * delta
            expect(emitter.particleTex[0]).toBeCloseTo(0.375, 6);
            expect(emitter.particleTex[1]).toBeCloseTo(0.75, 6);
            expect(emitter.particleTex[2]).toBeCloseTo(1.125, 6);
            expect(emitter.particleTex[3]).toBeCloseTo(0.75, 6);

            // first vertex attributes
            expect(data[0]).toBeCloseTo(0.375, 6);
            expect(data[1]).toBeCloseTo(0.75, 6);
            expect(data[2]).toBeCloseTo(1.125, 6);
            expect(data[3]).toBeCloseTo(0.25, 6); // normalized life 2.5 / 10
            expect(data[4]).toBeCloseTo(0.75, 6); // rotation
            expect(data[5]).toBeCloseTo(2.5, 6); // interpolated scale
            expect(data[6]).toBe(0); // alpha divergence with zero random factor
            expect(data[7]).toBeCloseTo(0.75, 6);
            expect(data[8]).toBe(10);
            expect(data[9]).toBe(20);
            expect(data[10]).toBe(30);
            expect(data[11]).toBeCloseTo(1.5, 6);
            expect(data[12]).toBe(0); // particle id
            expect(data[13]).toBeCloseTo(2.25, 6);
            expect(data[14]).toBe(0);

            // second vertex keeps its own quad coordinates
            expect(data[15 + 8]).toBe(40);
            expect(data[15 + 9]).toBe(50);
            expect(data[15 + 10]).toBe(60);
        });

        test('uses zero angle when aligned to motion', () => {
            const emitter = makeEmitter({ alignToMotion: true });
            emitter.particleTex[7] = 2;
            emitter.qRotSpeed[1] = 2;

            const data = new Float32Array(4 * 15);
            new ParticleCPUUpdater(emitter).update(
