            emitter.particleTex[3 + 2 * 4] = 2; // life particle 0
            emitter.particleTex[3 + 3 * 4] = 2; // life particle 1
            emitter.vbCPU[3] = 0;
            emitter.vbCPU[1 * 4 * 4 + 3] = 1;

            const data = new Float32Array(2 * 4 * 15);
            new ParticleCPUUpdater(emitter).update(
                data, emitter.vbToSort, emitter.particleTex,
                identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0, false
            );

            expect(emitter.particleDistance[0]).toBeCloseTo(-1, 6);
            expect(emitter.particleDistance[1]).toBeCloseTo(-25, 6);
