            const emitter = makeEmitter({ sort: 2 });
            emitter.particleTex[7] = 2;

            new ParticleCPUUpdater(emitter).update(
                new Float32Array(4 * 15), emitter.vbToSort, emitter.particleTex,
                identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0, false
            );
            expect(emitter.particleDistance[0]).toBeCloseTo(2, 6);

            emitter.sort = 3;
            emitter.particleTex[7] = 2;
            new ParticleCPUUpdater(emitter).update(
                new Float32Array(4 * 15), emitter.vbToSort, emitter.particleTex,
                identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0, false
            );
            expect(emitter.particleDistance[0]).toBeCloseTo(-2, 6);
        });

        test('writes mesh UV attributes for mesh-based particles', () => {
            const emitter = makeEmitter({
                useMesh: true,
                numParticleVerts: 2,
                numParticlesPot: 1,
                vbCPU: new Float32Array([
                    10, 20, 30, 0, 7, 8,
                    40, 50, 60, 0, 9, 10
                ])
            });
            emitter.particleTex[7] = 2;

            const data = new Float32Array(2 * 17);
            new ParticleCPUUpdater(emitter).update(
                data, emitter.vbToSort, emitter.particleTex,
                identitySpawnMatrix(), noInnerRatios(), noEmitterPos(), 0, false
            );

            expect(data[14]).toBe(0);
            expect(data[15]).toBe(7);
            expect(data[16]).toBe(8);
            expect(data[17 + 14]).toBe(0);
            expect(data[17 + 15]).toBe(9);
            expect(data[17 + 16]).toBe(10);
        });
    });
});
