import { jest, describe, test, expect, afterEach } from '@jest/globals';

import { Vec3 } from '../../../src/core/math/vec3.js';
import { GraphNode } from '../../../src/scene/graph-node.js';
import { EMITTERSHAPE_SPHERE } from '../../../src/scene/constants.js';
import { createTestDevice, createTestEmitter } from './test-utils.js';

let randomSpy;
afterEach(() => {
    randomSpy?.mockRestore();
    randomSpy = null;
});

function createGpuEmitter(options = {}, nodeSetup) {
    const device = createTestDevice({ supportsGpuParticles: true });
    const node = new GraphNode('fx');
    if (nodeSetup) {
        nodeSetup(node);
    }
    const emitter = createTestEmitter(device, {
        initialVelocity: 0,
        ...options
    }, node);
    return { device, node, emitter };
}

describe('ParticleGPUUpdater', () => {

    describe('#constructor()', () => {

        test('resolves the particle simulation uniforms on the device scope', () => {
            const { emitter } = createGpuEmitter({ numParticles: 4 });
            const updater = emitter._gpuUpdater;

            expect(updater.constantParticleTexIN.name).toBe('particleTexIN');
            expect(updater.constantParticleTexOUT.name).toBe('particleTexOUT');
            expect(updater.constantEmitterPos.name).toBe('emitterPos');
            expect(updater.constantEmitterScale.name).toBe('emitterScale');
            expect(updater.constantSpawnBounds.name).toBe('spawnBounds');
            expect(updater.constantSpawnPosInnerRatio.name).toBe('spawnPosInnerRatio');
            expect(updater.constantSpawnBoundsSphere.name).toBe('spawnBoundsSphere');
            expect(updater.constantSpawnBoundsSphereInnerRatio.name).toBe('spawnBoundsSphereInnerRatio');
            expect(updater.constantInitialVelocity.name).toBe('initialVelocity');
            expect(updater.constantFrameRandom.name).toBe('frameRandom');
            expect(updater.constantDelta.name).toBe('delta');
            expect(updater.constantRate.name).toBe('rate');
            expect(updater.constantRateDiv.name).toBe('rateDiv');
            expect(updater.constantLifetime.name).toBe('lifetime');
            expect(updater.constantGraphSampleSize.name).toBe('graphSampleSize');
            expect(updater.constantGraphNumSamples.name).toBe('graphNumSamples');
            expect(updater.constantInternalTex0.name).toBe('internalTex0');
            expect(updater.constantInternalTex1.name).toBe('internalTex1');
            expect(updater.constantInternalTex2.name).toBe('internalTex2');
            expect(updater.constantInternalTex3.name).toBe('internalTex3');
            expect(updater.constantEmitterMatrix.name).toBe('emitterMatrix');
            expect(updater.constantEmitterMatrixInv.name).toBe('emitterMatrixInv');
            expect(updater.constantNumParticles.name).toBe('numParticles');
            expect(updater.constantNumParticlesPot.name).toBe('numParticlesPot');
            expect(updater.constantLocalVelocityDivMult.name).toBe('localVelocityDivMult');
            expect(updater.constantVelocityDivMult.name).toBe('velocityDivMult');
            expect(updater.constantRotSpeedDivMult.name).toBe('rotSpeedDivMult');
            expect(updater.constantSeed.name).toBe('seed');
            expect(updater.constantStartAngle.name).toBe('startAngle');
            expect(updater.constantStartAngle2.name).toBe('startAngle2');
            expect(updater.constantFaceTangent.name).toBe('faceTangent');
            expect(updater.constantFaceBinorm.name).toBe('faceBinorm');
            expect(updater.constantRadialSpeedDivMult.name).toBe('radialSpeedDivMult');
        });

        test('initializes the per-frame random uniform array', () => {
            const { emitter } = createGpuEmitter({ numParticles: 2 });
            const updater = emitter._gpuUpdater;

            expect(updater.frameRandomUniform).toHaveLength(3);
            expect(updater.constantFrameRandom.value).toBe(updater.frameRandomUniform);
            for (const value of updater.frameRandomUniform) {
                expect(value).toBeGreaterThanOrEqual(0);
                expect(value).toBeLessThan(1);
            }
        });
    });

    describe('#randomize()', () => {

        test('fills the frame random uniform with three fresh random values', () => {
            const { emitter } = createGpuEmitter({ numParticles: 2 });
            const updater = emitter._gpuUpdater;

            randomSpy = jest.spyOn(Math, 'random')
                .mockReturnValueOnce(0.1)
                .mockReturnValueOnce(0.2)
                .mockReturnValueOnce(0.3);

            updater.randomize();

            expect(Array.from(updater.frameRandomUniform)).toEqual([
                expect.closeTo(0.1, 8),
                expect.closeTo(0.2, 8),
                expect.closeTo(0.3, 8)
            ]);
        });
    });

    describe('#update()', () => {

        test('publishes the emitter simulation state to the shader uniforms', () => {
            const { emitter } = createGpuEmitter({
                numParticles: 4,
                rate: 2,
                rate2: 5,
                lifetime: 7,
                startAngle: 30,
                startAngle2: 90
            });

            emitter.addTime(0.25, false);
            const updater = emitter._gpuUpdater;

            expect(updater.constantDelta.value).toBeCloseTo(0.25, 8);
            expect(updater.constantRate.value).toBe(2);
            expect(updater.constantRateDiv.value).toBe(3);
            expect(updater.constantLifetime.value).toBe(7);
            expect(updater.constantNumParticles.value).toBe(4);
            expect(updater.constantNumParticlesPot.value).toBe(4);
            expect(updater.constantGraphSampleSize.value).toBeCloseTo(1 / 32, 8);
            expect(updater.constantGraphNumSamples.value).toBe(32);
            expect(updater.constantStartAngle.value).toBeCloseTo(Math.PI / 6, 8);
            expect(updater.constantStartAngle2.value).toBeCloseTo(Math.PI / 2, 8);
            expect(updater.constantSeed.value).toBe(emitter.seed);
            expect(updater.constantInternalTex0.value).toBe(emitter.internalTex0);
            expect(updater.constantInternalTex1.value).toBe(emitter.internalTex1);
            expect(updater.constantInternalTex2.value).toBe(emitter.internalTex2);
            expect(updater.constantInternalTex3.value).toBe(emitter.internalTex3);
            expect(updater.constantLocalVelocityDivMult.value).toBe(emitter.localVelocityUMax);
            expect(updater.constantVelocityDivMult.value).toBe(emitter.velocityUMax);
            expect(updater.constantRotSpeedDivMult.value).toBe(emitter.rotSpeedUMax[0]);
        });

        test('ping-pongs the particle state textures and material bindings', () => {
            const { emitter } = createGpuEmitter({ numParticles: 4 });

            // constructor runs one update with swapTex = false
            expect(emitter.swapTex).toBe(true);
            expect(emitter.material.getParameter('particleTexOUT').data).toBe(emitter.particleTexIN);
            expect(emitter.material.getParameter('particleTexIN').data).toBe(emitter.particleTexOUT);
            expect(emitter._gpuUpdater.constantParticleTexIN.value).toBe(emitter.particleTexIN);

            emitter.addTime(0.25, false);

            expect(emitter.swapTex).toBe(false);
            expect(emitter.material.getParameter('particleTexOUT').data).toBe(emitter.particleTexOUT);
            expect(emitter.material.getParameter('particleTexIN').data).toBe(emitter.particleTexIN);
            expect(emitter._gpuUpdater.constantParticleTexIN.value).toBe(emitter.particleTexOUT);

            emitter.addTime(0.25, false);

            expect(emitter.swapTex).toBe(true);
            expect(emitter.material.getParameter('particleTexOUT').data).toBe(emitter.particleTexIN);
            expect(emitter.material.getParameter('particleTexIN').data).toBe(emitter.particleTexOUT);
            expect(emitter._gpuUpdater.constantParticleTexIN.value).toBe(emitter.particleTexIN);
        });

        test('refreshes the frame random uniform on every update', () => {
            const { emitter } = createGpuEmitter({ numParticles: 2 });

            randomSpy = jest.spyOn(Math, 'random')
                .mockReturnValueOnce(0.11)
                .mockReturnValueOnce(0.22)
                .mockReturnValueOnce(0.33);

            emitter.addTime(0, false);

            expect(emitter._gpuUpdater.frameRandomUniform[0]).toBeCloseTo(0.11, 8);
            expect(emitter._gpuUpdater.frameRandomUniform[1]).toBeCloseTo(0.22, 8);
            expect(emitter._gpuUpdater.frameRandomUniform[2]).toBeCloseTo(0.33, 8);
        });

        test('publishes emitter position and scale for world-space emitters', () => {
            const { emitter } = createGpuEmitter({ numParticles: 2 }, (node) => {
                node.setPosition(4, 5, 6);
                node.setLocalScale(2, 3, 4);
            });

            emitter.addTime(0, false);
            const updater = emitter._gpuUpdater;

            expect(Array.from(updater.constantEmitterPos.value)).toEqual([4, 5, 6]);
            expect(Array.from(updater.constantEmitterScale.value)).toEqual([2, 3, 4]);

            // an identity rotation with the node scale becomes a diagonal 3x3 matrix
            expect(Array.from(updater.constantEmitterMatrix.value.slice(0, 3))).toEqual([2, 0, 0]);
            expect(updater.constantEmitterMatrix.value[4]).toBe(3);
            expect(updater.constantEmitterMatrix.value[8]).toBe(4);
            expect(updater.constantEmitterMatrixInv.value[0]).toBeCloseTo(0.5, 6);
            expect(updater.constantEmitterMatrixInv.value[4]).toBeCloseTo(1 / 3, 6);
            expect(updater.constantEmitterMatrixInv.value[8]).toBeCloseTo(0.25, 6);
        });

        test('uses the origin for local-space emitters while preserving node scale', () => {
            const { emitter } = createGpuEmitter({
                numParticles: 2,
                localSpace: true
            }, (node) => {
                node.setPosition(4, 5, 6);
                node.setLocalScale(2, 3, 4);
            });

            emitter.addTime(0, false);

            expect(Array.from(emitter._gpuUpdater.constantEmitterPos.value)).toEqual([0, 0, 0]);
            expect(Array.from(emitter._gpuUpdater.constantEmitterScale.value)).toEqual([2, 3, 4]);
        });

        test('publishes box spawn bounds and inner ratios', () => {
            const { emitter } = createGpuEmitter({
                numParticles: 2,
                emitterExtents: new Vec3(2, 4, 6),
                emitterExtentsInner: new Vec3(1, 2, 3),
                localSpace: true
            });

            emitter.addTime(0, false);
            const updater = emitter._gpuUpdater;

            expect(updater.constantSpawnBounds.value).toHaveLength(9);
            expect(updater.constantSpawnBounds.value[0]).toBeCloseTo(2, 6);
            expect(updater.constantSpawnBounds.value[4]).toBeCloseTo(4, 6);
            expect(updater.constantSpawnBounds.value[8]).toBeCloseTo(6, 6);
            expect(Array.from(updater.constantSpawnPosInnerRatio.value)).toEqual([0.5, 0.5, 0.5]);
            expect(updater.constantSpawnBoundsSphere.value).toBeNull();
        });

        test('publishes sphere radius and inner ratio', () => {
            const { emitter } = createGpuEmitter({
                numParticles: 2,
                emitterShape: EMITTERSHAPE_SPHERE,
                emitterRadius: 10,
                emitterRadiusInner: 2
            });

            emitter.addTime(0, false);
            const updater = emitter._gpuUpdater;

            expect(updater.constantSpawnBoundsSphere.value).toBe(10);
            expect(updater.constantSpawnBoundsSphereInnerRatio.value).toBeCloseTo(0.2, 8);
            expect(updater.constantSpawnBounds.value).toBeNull();
        });

        test('uses the start texture after a reset and clears the reset flag', () => {
            const { emitter } = createGpuEmitter({ numParticles: 2 });

            emitter.reset();

            expect(emitter.beenReset).toBe(false);
            expect(emitter.material.getParameter('particleTexOUT').data).toBe(emitter.particleTexStart);
        });

        test('delegates emitter updates to the GPU updater with the stop flag', () => {
            const { device, emitter } = createGpuEmitter({ numParticles: 2 });
