    SEMANTIC_TEXCOORD4, SEMANTIC_TEXCOORD5, SEMANTIC_TEXCOORD6, SEMANTIC_TEXCOORD7,
    SHADERLANGUAGE_GLSL,
    SHADERLANGUAGE_WGSL,
    primitiveGlslToWgslTypeMap,
    semanticToLocation
