import { particleChunksGLSL } from '../../../../../src/scene/shader-lib/glsl/collections/particle-chunks-glsl.js';
import { particleChunksWGSL } from '../../../../../src/scene/shader-lib/wgsl/collections/particle-chunks-wgsl.js';

/**
 * Creates a headless null graphics device with the engine shader chunks registered on it, so that
 * the shader program generators can be exercised without a GPU. The registration mirrors what the
 * engine does when an application starts up (see `AppBase#init`).
