import { LIGHTTYPE_DIRECTIONAL, LIGHTTYPE_OMNI } from '../../../../src/scene/constants.js';
import { LitOptionsUtils } from '../../../../src/scene/shader-lib/programs/lit-options-utils.js';

const directionalLight = (key) => {
    return { key, _type: LIGHTTYPE_DIRECTIONAL };
};

const omniLight = (key) => {
    return { key, _type: LIGHTTYPE_OMNI };
};

describe('LitOptionsUtils', () => {

    describe('#generateKey()', () => {

        it('prefixes the key with "lit"', () => {
            expect(LitOptionsUtils.generateKey({})).toBe('lit');
        });

        it('serializes every option in sorted order', () => {
            expect(LitOptionsUtils.generateKey({ b: 2, a: 1, c: true })).toBe('lit\na1\nb2\nctrue');
        });

        it('produces the same key regardless of property insertion order', () => {
            const keyA = LitOptionsUtils.generateKey({ alpha: 1, beta: false, gamma: 'x' });
            const keyB = LitOptionsUtils.generateKey({ gamma: 'x', alpha: 1, beta: false });

            expect(keyA).toBe(keyB);
        });

        it('produces different keys for different option values', () => {
            const keyA = LitOptionsUtils.generateKey({ blendType: 1 });
            const keyB = LitOptionsUtils.generateKey({ blendType: 2 });

            expect(keyA).not.toBe(keyB);
        });

        it('uses the key of the shaderChunks object instead of serializing it', () => {
            const key = LitOptionsUtils.generateKey({
                shaderChunks: { key: 'CHUNKS-KEY', glsl: new Map([['someChunk', 'code']]) }
            });

            expect(key).toBe('lit\nCHUNKS-KEY');
            expect(key).not.toContain('[object Object]');
        });

        it('handles a null shaderChunks value', () => {
            expect(LitOptionsUtils.generateKey({ shaderChunks: null })).toBe('lit');
        });

        it('delegates the lights to generateLightsKey', () => {
            const options = {
                lights: [directionalLight('A')],
                clusteredLightingEnabled: false
            };

            expect(LitOptionsUtils.generateKey(options)).toBe(`lit\n${LitOptionsUtils.generateLightsKey(options)}`);
            expect(LitOptionsUtils.generateKey(options)).toContain('lights:0:A,');
        });

    });

    describe('#generateLightsKey()', () => {

        it('returns an empty lights list for no lights', () => {
            expect(LitOptionsUtils.generateLightsKey({ lights: [] })).toBe('lights:');
        });

        it('includes the slot index and the key of every light when clustered lighting is disabled', () => {
            const options = {
                lights: [directionalLight('A'), omniLight('B')],
                clusteredLightingEnabled: false
            };

            expect(LitOptionsUtils.generateLightsKey(options)).toBe('lights:0:A,1:B,');
        });

        it('distinguishes the same lights placed in different slots', () => {
            const compact = {
                lights: [directionalLight('A'), directionalLight('B')],
                clusteredLightingEnabled: false
            };
            const sparse = {
                lights: [directionalLight('A'), null, directionalLight('B')],
                clusteredLightingEnabled: false
            };

            expect(LitOptionsUtils.generateLightsKey(compact)).toBe('lights:0:A,1:B,');
            expect(LitOptionsUtils.generateLightsKey(sparse)).toBe('lights:0:A,2:B,');
        });

        it('skips holes in the sparse lights array', () => {
            const options = {
                lights: [null, undefined, directionalLight('C')],
                clusteredLightingEnabled: false
            };

            expect(LitOptionsUtils.generateLightsKey(options)).toBe('lights:2:C,');
        });

        it('only includes directional lights when clustered lighting is enabled', () => {
            const options = {
                lights: [directionalLight('A'), omniLight('B'), directionalLight('C')],
                clusteredLightingEnabled: true
            };

            expect(LitOptionsUtils.generateLightsKey(options)).toBe('lights:0:A,2:C,');
        });

        it('includes all light types when clustered lighting is not enabled', () => {
            const options = {
                lights: [omniLight('A')]
            };

            expect(LitOptionsUtils.generateLightsKey(options)).toBe('lights:0:A,');
        });

    });

});
