import { ShaderGenerator } from '../../../../src/scene/shader-lib/programs/shader-generator.js';

describe('ShaderGenerator', () => {

    describe('#definesHash()', () => {

        it('returns a number', () => {
            const hash = ShaderGenerator.definesHash(new Map([['A', 1]]));

            expect(typeof hash).toBe('number');
            expect(Number.isFinite(hash)).toBe(true);
        });

        it('returns the same hash for identical defines', () => {
            const hashA = ShaderGenerator.definesHash(new Map([['A', 1], ['B', 'two']]));
            const hashB = ShaderGenerator.definesHash(new Map([['A', 1], ['B', 'two']]));

            expect(hashA).toBe(hashB);
        });

        it('is insensitive to the insertion order of the defines', () => {
            const hashA = ShaderGenerator.definesHash(new Map([['A', 1], ['B', 2], ['C', 3]]));
            const hashB = ShaderGenerator.definesHash(new Map([['C', 3], ['A', 1], ['B', 2]]));

            expect(hashA).toBe(hashB);
        });

        it('returns different hashes for different define values', () => {
            const hashA = ShaderGenerator.definesHash(new Map([['A', 1]]));
            const hashB = ShaderGenerator.definesHash(new Map([['A', 2]]));

            expect(hashA).not.toBe(hashB);
        });

        it('distinguishes a changed define name from a changed value', () => {
            const valueChanged = ShaderGenerator.definesHash(new Map([['A', 'TRUE']]));
            const nameChanged = ShaderGenerator.definesHash(new Map([['B', 'TRUE']]));

            expect(valueChanged).not.toBe(nameChanged);
        });

        it('distinguishes a boolean define from its string representation', () => {
            const booleanValue = ShaderGenerator.definesHash(new Map([['A', true]]));
            const stringValue = ShaderGenerator.definesHash(new Map([['A', 'true']]));

            expect(booleanValue).not.toBe(stringValue);
        });

        it('returns a stable hash for an empty define set', () => {
            const hashA = ShaderGenerator.definesHash(new Map());
            const hashB = ShaderGenerator.definesHash(new Map());

            expect(hashA).toBe(hashB);
        });

        it('changes as soon as a define is added', () => {
            const empty = ShaderGenerator.definesHash(new Map());
            const oneDefine = ShaderGenerator.definesHash(new Map([['A', 1]]));

            expect(empty).not.toBe(oneDefine);
        });

    });

});
