import {
    BLEND_NONE, DITHER_NONE, FOG_NONE, GAMMA_NONE, REFLECTIONSRC_NONE, SHADER_FORWARD
} from '../../../../src/scene/constants.js';
import { LitShaderOptions } from '../../../../src/scene/shader-lib/programs/lit-shader-options.js';

describe('LitShaderOptions', () => {

    it('has no custom shader chunks by default', () => {
        expect(new LitShaderOptions().shaderChunks).toBeNull();
    });

    it('defaults to the forward pass', () => {
        expect(new LitShaderOptions().pass).toBe(SHADER_FORWARD);
    });

    it('defaults to disabled blend, fog, gamma and reflection modes', () => {
        const options = new LitShaderOptions();

        expect(options.blendType).toBe(BLEND_NONE);
        expect(options.opacityDither).toBe(DITHER_NONE);
        expect(options.opacityShadowDither).toBe(DITHER_NONE);
        expect(options.fog).toBe(FOG_NONE);
        expect(options.gamma).toBe(GAMMA_NONE);
        expect(options.reflectionSource).toBe(REFLECTIONSRC_NONE);
    });

    it('defaults to the constant ambient source and a skybox intensity of one', () => {
        const options = new LitShaderOptions();

        expect(options.ambientSource).toBe('constant');
        expect(options.skyboxIntensity).toBe(1);
    });

    it('defaults to no lights and no user attributes', () => {
        const options = new LitShaderOptions();

        expect(options.lights).toEqual([]);
        expect(options.userAttributes).toEqual({});
        expect(options.lightMaskDynamic).toBe(0);
    });

    it('defaults to clustered lighting being enabled', () => {
        const options = new LitShaderOptions();

        expect(options.clusteredLightingEnabled).toBe(true);
        expect(options.clusteredLightingCookiesEnabled).toBe(false);
        expect(options.clusteredLightingShadowsEnabled).toBe(false);
        expect(options.clusteredLightingAreaLightsEnabled).toBe(false);
    });

    it('defaults all feature switches to false', () => {
        const options = new LitShaderOptions();
        const featureSwitches = [
            'hasTangents', 'alphaTest', 'separateAmbient', 'screenSpace', 'skin', 'batch',
            'useInstancing', 'useMorphPosition', 'useMorphNormal', 'useMorphTextureBasedInt',
            'vertexColors', 'useVertexColorGamma', 'lightMapEnabled', 'dirLightMapEnabled',
            'useHeights', 'useNormals', 'useClearCoatNormals', 'useAo', 'pixelSnap', 'ambientSH',
            'ssao', 'twoSidedLighting', 'occludeDirect', 'occludeSpecularFloat', 'useMsdf',
            'alphaToCoverage', 'opacityFadesSpecular', 'useSpecular', 'useSpecularityFactor',
            'enableGGXSpecular', 'useRefraction', 'useClearCoat', 'useSheen', 'useIridescence',
            'useMetalness', 'useDynamicRefraction', 'dispersion', 'noShadow', 'linearDepth',
            'shadowCatcher', 'useClipPlanes', 'useSceneEnv', 'lightMapWithoutAmbient',
            'useCubeMapRotation', 'msdfTextAttribute'
        ];

        for (const name of featureSwitches) {
            expect({ name, value: options[name] }).toEqual({ name, value: false });
        }
    });

    it('creates an independent set of options per instance', () => {
        const first = new LitShaderOptions();
        const second = new LitShaderOptions();

        first.lights.push({ key: 'light' });
        first.userAttributes.attr = 'POSITION';
        first.useSpecular = true;

        expect(second.lights).toEqual([]);
        expect(second.userAttributes).toEqual({});
        expect(second.useSpecular).toBe(false);
    });

});
