            const shader = new LitShader(device, createOptions());

            expect(shader.vshader).toBeNull();
            expect(shader.fshader).toBeNull();
        });

        it('uses GLSL on a device that is not WebGPU', () => {
            expect(new LitShader(device, createOptions()).shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
        });

        it('uses WGSL on a WebGPU device', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            const shader = new LitShader(webgpuDevice, createOptions());

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
            webgpuDevice.destroy();
        });

        it('uses GLSL on a WebGPU device when WGSL is not allowed', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            webgpuDevice.hasTranspilers = true;
            const shader = new LitShader(webgpuDevice, createOptions(), false);

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
            webgpuDevice.destroy();
        });

        it('uses WGSL on a WebGPU device when the custom chunks only override WGSL chunks', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            const shaderChunks = new ShaderChunks();
            shaderChunks.wgsl.set('someWGSLChunkPS', '// wgsl only override');

            const shader = new LitShader(webgpuDevice, createOptions({ shaderChunks }));

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
            webgpuDevice.destroy();
        });

        it('uses GLSL on a WebGPU device when the custom chunks override GLSL chunks', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            webgpuDevice.hasTranspilers = true;
            const shaderChunks = new ShaderChunks();
            shaderChunks.glsl.set('someGLSLChunkPS', '// glsl only override');

            const shader = new LitShader(webgpuDevice, createOptions({ shaderChunks }));

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
            webgpuDevice.destroy();
        });

        it('reports an error when GLSL is requested on a WebGPU device without transpilers', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            expect(webgpuDevice.hasTranspilers).toBeFalsy();

            const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
            try {
                const shader = new LitShader(webgpuDevice, createOptions(), false);

                expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
                expect(errorSpy.mock.calls.flat().join(' ')).toContain('Cannot use GLSL shader on WebGPU without transpilers');
            } finally {
                errorSpy.mockRestore();
                webgpuDevice.destroy();
            }
        });

        it('provides the position attribute and the engine chunks', () => {
            const shader = new LitShader(device, createOptions());

            expect(shader.attributes).toEqual({ vertex_position: 'POSITION' });
            expect(shader.chunks).toBeInstanceOf(Map);
            expect(shader.chunks.has('litMainVS')).toBe(true);
            expect(shader.chunks.has('litMainPS')).toBe(true);
        });

        it('maps the user attributes onto the vertex attributes', () => {
            const shader = new LitShader(device, createOptions({
                userAttributes: { [SEMANTIC_COLOR]: 'my_color' }
            }));

            expect(shader.attributes.my_color).toBe(SEMANTIC_COLOR);
        });

        it('adds custom shader chunks and picks up the attributes they reference', () => {
            const shaderChunks = {
