                wgsl: new Map()
            };

            const shader = new LitShader(device, createOptions({ shaderChunks }));

            expect(shader.chunks.get('diffusePS')).toContain('vertex_texCoord1');
            expect(shader.attributes.vertex_texCoord1).toBe(SEMANTIC_TEXCOORD1);
        });

