 * Creates lit shader options initialized with the supplied values.
 *
 * @param {object} [values] - Values assigned to the default lit shader options.
 * @returns {LitShaderOptions} The options.
 */
const createOptions = (values = {}) => {
    return Object.assign(new LitShaderOptions(), values);
};

describe('LitShader', () => {

    let device;

    beforeEach(() => {
        device = createTestDevice();
    });

    afterEach(() => {
        device.destroy();
        device = null;
    });

    describe('#constructor()', () => {

        it('stores the device and the lit options', () => {
            const options = createOptions();
            const shader = new LitShader(device, options);

            expect(shader.device).toBe(device);
            expect(shader.options).toBe(options);
        });

        it('starts with no generated shader code', () => {
            const shader = new LitShader(device, createOptions());

            expect(shader.vshader).toBeNull();
            expect(shader.fshader).toBeNull();
        });

        it('uses GLSL on a device that is not WebGPU', () => {
            expect(new LitShader(device, createOptions()).shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
        });

        it('uses WGSL on a WebGPU device', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            const shader = new LitShader(webgpuDevice, createOptions());

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
            webgpuDevice.destroy();
        });

        it('uses GLSL on a WebGPU device when WGSL is not allowed', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            webgpuDevice.hasTranspilers = true;
            const shader = new LitShader(webgpuDevice, createOptions(), false);

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
            webgpuDevice.destroy();
        });

        it('uses WGSL on a WebGPU device when the custom chunks only override WGSL chunks', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            const shaderChunks = new ShaderChunks();
            shaderChunks.wgsl.set('someWGSLChunkPS', '// wgsl only override');

            const shader = new LitShader(webgpuDevice, createOptions({ shaderChunks }));

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
            webgpuDevice.destroy();
        });

        it('uses GLSL on a WebGPU device when the custom chunks override GLSL chunks', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            webgpuDevice.hasTranspilers = true;
            const shaderChunks = new ShaderChunks();
            shaderChunks.glsl.set('someGLSLChunkPS', '// glsl only override');

            const shader = new LitShader(webgpuDevice, createOptions({ shaderChunks }));

            expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
            webgpuDevice.destroy();
        });

        it('reports an error when GLSL is requested on a WebGPU device without transpilers', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            expect(webgpuDevice.hasTranspilers).toBeFalsy();

            const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});
            try {
                const shader = new LitShader(webgpuDevice, createOptions(), false);

                expect(shader.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
                expect(errorSpy.mock.calls.flat().join(' ')).toContain('Cannot use GLSL shader on WebGPU without transpilers');
            } finally {
                errorSpy.mockRestore();
                webgpuDevice.destroy();
            }
        });

        it('provides the position attribute and the engine chunks', () => {
            const shader = new LitShader(device, createOptions());

            expect(shader.attributes).toEqual({ vertex_position: 'POSITION' });
            expect(shader.chunks).toBeInstanceOf(Map);
            expect(shader.chunks.has('litMainVS')).toBe(true);
            expect(shader.chunks.has('litMainPS')).toBe(true);
        });

        it('maps the user attributes onto the vertex attributes', () => {
            const shader = new LitShader(device, createOptions({
                userAttributes: { [SEMANTIC_COLOR]: 'my_color' }
            }));

            expect(shader.attributes.my_color).toBe(SEMANTIC_COLOR);
        });

        it('adds custom shader chunks and picks up the attributes they reference', () => {
            const shaderChunks = {
                version: '99.0',
                glsl: new Map([['diffusePS', 'vec4 c = texture2D(texture_diffuseMap, vertex_texCoord1);']]),
                wgsl: new Map()
            };

            const shader = new LitShader(device, createOptions({ shaderChunks }));

            expect(shader.chunks.get('diffusePS')).toContain('vertex_texCoord1');
            expect(shader.attributes.vertex_texCoord1).toBe(SEMANTIC_TEXCOORD1);
        });

        it('warns when an override of a versioned chunk has no API version', () => {
            const shaderChunks = {
                version: '',
                glsl: new Map([['opacityPS', '// opacity override']]),
                wgsl: new Map()
            };

            const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
            try {
                new LitShader(device, createOptions({ shaderChunks }));

                expect(warnSpy.mock.calls.flat().join(' ')).toContain('Shader chunk \'opacityPS\' is API version');
            } finally {
                warnSpy.mockRestore();
            }
        });

        it('warns when a removed chunk is supplied', () => {
            const shaderChunks = {
                version: '99.0',
                glsl: new Map([['refractionPS', '// removed chunk']]),
                wgsl: new Map()
            };

            const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});
            try {
                new LitShader(device, createOptions({ shaderChunks }));

                expect(warnSpy.mock.calls.flat().join(' ')).toContain('was removed');
            } finally {
                warnSpy.mockRestore();
            }
        });

        it('resolves the shader pass info of the configured pass', () => {
            const forward = new LitShader(device, createOptions());
            const pick = new LitShader(device, createOptions({ pass: 3 }));

            expect(forward.shaderPassInfo.name).toBe('forward');
            expect(forward.shaderPassInfo.isForward).toBe(true);
            expect(forward.shadowPass).toBeFalsy();
            expect(pick.shaderPassInfo.name).toBe('pick');
            expect(pick.shaderPassInfo.isForward).toBeFalsy();
        });

        it('enables lighting and normals when clustered lighting is on', () => {
