            expect(shader.reflections).toBe(false);
            expect(shader.needsSceneColor).toBe(false);
            expect(shader.needsScreenSize).toBe(false);
            expect(shader.needsTransforms).toBe(false);
        });

        it('disables lighting and normals when there is no light source', () => {
            const shader = new LitShader(device, createOptions({ clusteredLightingEnabled: false }));

            expect(shader.lighting).toBe(false);
            expect(shader.needsNormal).toBe(false);
        });

        it('enables lighting when a directional light map is used', () => {
            const shader = new LitShader(device, createOptions({ clusteredLightingEnabled: false, dirLightMapEnabled: true }));

            expect(shader.lighting).toBe(true);
        });

        it('enables lighting when lights are supplied', () => {
            const shader = new LitShader(device, createOptions({ clusteredLightingEnabled: false, lights: [{ key: 'light' }] }));

            expect(shader.lighting).toBe(true);
        });

        it('enables reflections when a reflection source is configured', () => {
            const shader = new LitShader(device, createOptions({ reflectionSource: 'envAtlas' }));

            expect(shader.reflections).toBe(true);
            expect(shader.needsNormal).toBe(true);
        });

        it('requests the scene color, screen size and transforms for dynamic refraction', () => {
            const shader = new LitShader(device, createOptions({ useDynamicRefraction: true }));

            expect(shader.needsSceneColor).toBe(true);
            expect(shader.needsScreenSize).toBe(true);
            expect(shader.needsTransforms).toBe(true);
        });

    });

    describe('#generateVertexShader()', () => {

        it('generates the lit vertex shader include and the varyings includes', () => {
            const shader = new LitShader(device, createOptions());

            shader.generateVertexShader([true], [true], []);

            expect(shader.vshader).toContain('#include "litMainVS"');
            expect(shader.includes.get('varyingsVS')).toBe(shader.varyingsCode);
            expect(shader.includes.get('varyingsPS')).toBe(shader.varyingsCode);
        });

        it('writes varyings in GLSL syntax', () => {
            const shader = new LitShader(device, createOptions());

            shader.generateVertexShader([true], [true], []);

            expect(shader.varyingsCode).toContain('#define VARYING_VPOSITIONW');
            expect(shader.varyingsCode).toContain('varying vec3 vPositionW;');
            expect(shader.varyingsCode).toContain('varying vec3 vNormalW;');
            expect(shader.varyingsCode).toContain('varying vec2 vUv0;');
        });

        it('writes varyings in WGSL syntax on a WebGPU device', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            const shader = new LitShader(webgpuDevice, createOptions());

            shader.generateVertexShader([true], [true], []);

            expect(shader.varyingsCode).toContain('varying vPositionW: vec3f;');
            webgpuDevice.destroy();
        });

        it('declares the normal attribute and the normals define only when normals are needed', () => {
            const withNormals = new LitShader(device, createOptions());
            withNormals.generateVertexShader([true], [true], []);

            expect(withNormals.vDefines.get('NORMALS')).toBe(true);
            expect(withNormals.attributes.vertex_normal).toBe('NORMAL');

            const withoutNormals = new LitShader(device, createOptions({ clusteredLightingEnabled: false }));
            withoutNormals.generateVertexShader([true], [true], []);

            expect(withoutNormals.vDefines.has('NORMALS')).toBe(false);
            expect(withoutNormals.attributes.vertex_normal).toBeUndefined();
            expect(withoutNormals.varyingsCode).not.toContain('vNormalW');
        });

        it('declares a UV attribute and define for each used UV set', () => {
