            expect(shader.vDefines.get('UV3')).toBe(true);
            expect(shader.attributes.vertex_texCoord0).toBe('TEXCOORD0');
            expect(shader.attributes.vertex_texCoord3).toBe('TEXCOORD3');
            expect(shader.vDefines.get('UV1_UNMODIFIED')).toBe(true);
            expect(shader.vDefines.get('UV3_UNMODIFIED')).toBe(true);
            expect(shader.vDefines.has('UV0_UNMODIFIED')).toBe(false);
        });

        it('expands the looped UV set includes only for UV sets 2 and above', () => {
            const shader = new LitShader(device, createOptions());

