            expect(shader.vDefines.get('{UV_SET_0}')).toBe(2);
            expect(shader.vDefines.get('UV_VARYING_SET_COUNT')).toBe(1);
            expect(shader.vDefines.get('{UV_VARYING_SET_0}')).toBe(2);
