/**
 * Creates lit shader options initialized with the supplied values.
 *
 * @param {object} [values] - Values assigned to the default lit shader options.
 * @returns {LitShaderOptions} The options.
 */
const createOptions = (values = {}) => {
    return Object.assign(new LitShaderOptions(), values);
};

/**
 * Generates a lit shader with the supplied options.
 *
 * @param {object} device - The graphics device.
 * @param {object} [values] - Values assigned to the default lit shader options.
 * @param {string} [frontendDecl] - The front end declarations passed to the fragment generator.
 * @param {string} [frontendCode] - The front end code passed to the fragment generator.
 * @param {string} [lightingUv] - The lighting UV expression.
 * @returns {LitShader} The generated shader.
 */
const generate = (device, values = {}, frontendDecl = 'float dAlpha;', frontendCode = 'void getOpacity() {}', lightingUv = 'vUv0') => {
    const shader = new LitShader(device, createOptions(values));
    shader.generateFragmentShader(frontendDecl, frontendCode, lightingUv);
    return shader;
};

