        });

        it('defaults the front end includes to empty strings', () => {
            const shader = new LitShader(device, createOptions());
            shader.generateFragmentShader(undefined, undefined);

            expect(shader.includes.get('frontendDeclPS')).toBe('');
            expect(shader.includes.get('frontendCodePS')).toBe('');
        });

        it('always emits the enumerated option defines', () => {
            const shader = generate(device, {
                fresnelModel: FRESNEL_SCHLICK,
                nineSlicedMode: SPRITE_RENDERMODE_TILED,
                blendType: BLEND_ADDITIVE,
