            expect(shader.fDefines.get('LIT_OCCLUDE_SPECULAR')).toBe('AO');
            expect(shader.fDefines.get('LIT_REFLECTION_SOURCE')).toBe('ENVATLAS');
            expect(shader.fDefines.get('LIT_AMBIENT_SOURCE')).toBe('AMBIENTSH');
        });

        it('defaults the enumerated option defines', () => {
            const shader = generate(device);

            expect(shader.fDefines.get('LIT_FRESNEL_MODEL')).toBe('NONE');
            expect(shader.fDefines.get('LIT_NONE_SLICE_MODE')).toBe('SIMPLE');
            expect(shader.fDefines.get('LIT_BLEND_TYPE')).toBe('NONE');
