            expect(shader.fDefines.get('LIT_AMBIENT_SOURCE')).toBe('CONSTANT');
        });

        it('injects the environment sampler names owned by the material', () => {
            const shader = generate(device);

            expect(shader.fDefines.get('{LIT_ENV_ATLAS}')).toBe('texture_envAtlas');
