            const shader = generate(device);

            expect(shader.fshader).toContain('#include "litMainPS"');
        });

        it('exposes the supplied front end code as includes', () => {
            const shader = generate(device, {}, 'float dAlpha;', 'void getOpacity() { dAlpha = 1.0; }', 'vUv2');

            expect(shader.includes.get('frontendDeclPS')).toBe('float dAlpha;');
            expect(shader.includes.get('frontendCodePS')).toBe('void getOpacity() { dAlpha = 1.0; }');
            expect(shader.fDefines.get('{lightingUv}')).toBe('vUv2');
        });

        it('defaults the front end includes to empty strings', () => {
            const shader = new LitShader(device, createOptions());
            shader.generateFragmentShader(undefined, undefined);

            expect(shader.includes.get('frontendDeclPS')).toBe('');
            expect(shader.includes.get('frontendCodePS')).toBe('');
        });

        it('always emits the enumerated option defines', () => {
            const shader = generate(device, {
                fresnelModel: FRESNEL_SCHLICK,
                nineSlicedMode: SPRITE_RENDERMODE_TILED,
                blendType: BLEND_ADDITIVE,
                cubeMapProjection: CUBEPROJ_BOX,
                occludeSpecular: SPECOCC_AO,
                reflectionSource: REFLECTIONSRC_ENVATLAS,
                ambientSource: 'ambientSH'
            });

            expect(shader.fDefines.get('LIT_FRESNEL_MODEL')).toBe('SCHLICK');
            expect(shader.fDefines.get('LIT_NONE_SLICE_MODE')).toBe('TILED');
            expect(shader.fDefines.get('LIT_BLEND_TYPE')).toBe('ADDITIVE');
            expect(shader.fDefines.get('LIT_CUBEMAP_PROJECTION')).toBe('BOX');
            expect(shader.fDefines.get('LIT_OCCLUDE_SPECULAR')).toBe('AO');
            expect(shader.fDefines.get('LIT_REFLECTION_SOURCE')).toBe('ENVATLAS');
            expect(shader.fDefines.get('LIT_AMBIENT_SOURCE')).toBe('AMBIENTSH');
        });

        it('defaults the enumerated option defines', () => {
            const shader = generate(device);

            expect(shader.fDefines.get('LIT_FRESNEL_MODEL')).toBe('NONE');
            expect(shader.fDefines.get('LIT_NONE_SLICE_MODE')).toBe('SIMPLE');
