            expect(shader.fDefines.has('SHADOW_KIND_PCF3')).toBe(false);
        });

        it('emits the clustered lighting feature defines', () => {
            const shader = generate(device, {
                clusteredLightingCookiesEnabled: true,
                clusteredLightingAreaLightsEnabled: true,
