            expect(shader.fDefines.get('CLUSTER_SHADOW_TYPE_PCF3')).toBe(true);
        });

        it('suppresses the clustered shadow defines when shadows are off', () => {
            const shader = generate(device, {
                clusteredLightingShadowsEnabled: true,
                clusteredLightingShadowType: SHADOW_PCF3_32F,
                noShadow: true
            });

            expect(shader.fDefines.has('CLUSTER_SHADOWS')).toBe(false);
        });

