            expect(shader.fDefines.get('LIT_ALPHA_TEST')).toBe('');
            expect(shader.fDefines.has('LIT_LIGHTING')).toBe(false);
            expect(shader.fDefines.has('LIT_NEEDS_NORMAL')).toBe(false);
        });

        it('prepares no defines for the pick pass', () => {
            const shader = generate(device, { pass: SHADER_PICK });

            expect(shader.fDefines.size).toBe(0);
        });

    });

});
