import { createTestDevice } from './helpers/device.js';

/**
 * Creates the options accepted by the particle shader generator.
 *
 * @param {object} [values] - Values overriding the defaults.
 * @returns {object} The generator options.
 */
const createOptions = (values = {}) => {
    return {
        defines: new Map(),
        mesh: false,
        meshUv: false,
        localSpace: false,
        screenSpace: false,
        animTex: false,
        animTexLoop: false,
        wrap: false,
        alignToMotion: false,
        soft: 0,
        stretch: 0,
        customFace: false,
        normal: 0,
        halflambert: false,
        blend: BLEND_NORMAL,
        useCpu: false,
        ...values
    };
};

/**
 * Returns the entry keys of a define map that are present.
 *
 * @param {Map<string, any>} defines - The define map.
