const createOptions = (values = {}) => {
    return {
        defines: new Map(),
        mesh: false,
        meshUv: false,
        localSpace: false,
        screenSpace: false,
        animTex: false,
        animTexLoop: false,
        wrap: false,
        alignToMotion: false,
        soft: 0,
        stretch: 0,
        customFace: false,
        normal: 0,
        halflambert: false,
        blend: BLEND_NORMAL,
        useCpu: false,
        ...values
    };
};

/**
 * Returns the entry keys of a define map that are present.
 *
 * @param {Map<string, any>} defines - The define map.
 * @returns {string[]} The define names.
 */
const defineNames = (defines) => {
    return Array.from(defines.keys());
};

describe('particle', () => {

    let device;

    beforeEach(() => {
        device = createTestDevice();
    });

    afterEach(() => {
        device.destroy();
        device = null;
    });

    describe('#generateKey()', () => {

        it('prefixes the key with "particle_"', () => {
            expect(particle.generateKey(createOptions())).toMatch(/^particle_/);
        });

        it('produces the same key for equivalent options', () => {
            expect(particle.generateKey(createOptions())).toBe(particle.generateKey(createOptions()));
        });

        it('includes the defines hash', () => {
            const withoutDefines = particle.generateKey(createOptions());
            const withDefines = particle.generateKey(createOptions({ defines: new Map([['X', 1]]) }));

            expect(withoutDefines).not.toBe(withDefines);
        });

        it('changes when a non define option changes', () => {
            const off = particle.generateKey(createOptions({ soft: 0 }));
            const on = particle.generateKey(createOptions({ soft: 1 }));

            expect(off).not.toBe(on);
        });

        it('changes when the shader flags change', () => {
            const local = particle.generateKey(createOptions({ localSpace: true }));
            const world = particle.generateKey(createOptions({ localSpace: false }));

            expect(local).not.toBe(world);
        });

    });

    describe('#createVertexDefines()', () => {

        it('copies the supplied defines', () => {
            const options = createOptions({ defines: new Map([['MY_DEFINE', '7']]) });
            const defines = particle.createVertexDefines(options, {});

            expect(defines.get('MY_DEFINE')).toBe('7');
            expect(defines).not.toBe(options.defines);
        });

        it('does not modify the source defines', () => {
            const options = createOptions({ defines: new Map([['MY_DEFINE', '7']]), mesh: true });
            particle.createVertexDefines(options, {});

            expect(Array.from(options.defines.keys())).toEqual(['MY_DEFINE']);
        });

        it('maps the vertex flags onto defines', () => {
            const options = createOptions({
                mesh: true,
                meshUv: true,
                localSpace: true,
                screenSpace: true,
                animTex: true,
                animTexLoop: true,
                wrap: true,
                alignToMotion: true,
                customFace: true,
                soft: 1,
                stretch: 0.5
            });

            const names = defineNames(particle.createVertexDefines(options, {}));

            ['USE_MESH', 'USE_MESH_UV', 'LOCAL_SPACE', 'SCREEN_SPACE', 'ANIMTEX', 'ANIMTEX_LOOP',
                'WRAP', 'ALIGN_TO_MOTION', 'CUSTOM_FACE', 'SOFT', 'STRETCH'].forEach((name) => {
                expect(names).toContain(name);
            });
        });

        it('only adds the soft and stretch defines for positive values', () => {
            const names = defineNames(particle.createVertexDefines(createOptions({ soft: 0, stretch: 0 }), {}));

            expect(names).not.toContain('SOFT');
            expect(names).not.toContain('STRETCH');
        });

        it('adds the normal type define', () => {
            expect(particle.createVertexDefines(createOptions({ normal: 0 }), {}).get('NORMAL')).toBe('NONE');
            expect(particle.createVertexDefines(createOptions({ normal: 1 }), {}).get('NORMAL')).toBe('VERTEX');
            expect(particle.createVertexDefines(createOptions({ normal: 2 }), {}).get('NORMAL')).toBe('MAP');
        });

        it('declares the particle vertex data attribute', () => {
            const attributes = {};
            particle.createVertexDefines(createOptions(), attributes);

            expect(attributes.particle_vertexData).toBe('POSITION');
            expect(attributes.particle_uv).toBeUndefined();
        });

        it('declares the UV attribute only for meshes with UVs', () => {
            const meshAttributes = {};
            particle.createVertexDefines(createOptions({ mesh: true, meshUv: true }), meshAttributes);
            expect(meshAttributes.particle_uv).toBe('TEXCOORD0');

            const noUvAttributes = {};
            particle.createVertexDefines(createOptions({ mesh: true, meshUv: false }), noUvAttributes);
            expect(noUvAttributes.particle_uv).toBeUndefined();
        });

        it('declares the extra CPU particle attributes', () => {
            const cpuAttributes = {};
            particle.createVertexDefines(createOptions({ useCpu: true }), cpuAttributes);

            expect(cpuAttributes.particle_vertexData2).toBe('ATTR1');
            expect(cpuAttributes.particle_vertexData3).toBe('ATTR2');
            expect(cpuAttributes.particle_vertexData4).toBe('ATTR3');
            expect(cpuAttributes.particle_vertexData5).toBe('ATTR4');

            const gpuAttributes = {};
            particle.createVertexDefines(createOptions({ useCpu: false }), gpuAttributes);
            expect(gpuAttributes.particle_vertexData2).toBeUndefined();
        });

    });

    describe('#createFragmentDefines()', () => {

        it('adds the soft particles define', () => {
            const defines = particle.createFragmentDefines(createOptions({ soft: 1 }));

            expect(defines.get('SOFT')).toBe('');
            expect(particle.createFragmentDefines(createOptions({ soft: 0 })).has('SOFT')).toBe(false);
        });

        it('adds the half lambert define', () => {
            const defines = particle.createFragmentDefines(createOptions({ halflambert: true }));

            expect(defines.get('HALF_LAMBERT')).toBe('');
            expect(particle.createFragmentDefines(createOptions({ halflambert: false })).has('HALF_LAMBERT')).toBe(false);
        });

        it('adds the normal and blend mode names', () => {
            const defines = particle.createFragmentDefines(createOptions({ normal: 2, blend: BLEND_ADDITIVE }));

            expect(defines.get('NORMAL')).toBe('MAP');
            expect(defines.get('BLEND')).toBe('ADDITIVE');
        });

        it('copies the supplied defines', () => {
            const defines = particle.createFragmentDefines(createOptions({ defines: new Map([['MY_DEFINE', '1']]) }));

            expect(defines.get('MY_DEFINE')).toBe('1');
        });

    });

    describe('#createShaderDefinition()', () => {

        it('creates a GLSL particle shader definition on a non WebGPU device', () => {
            const definition = particle.createShaderDefinition(device, createOptions());

            expect(definition.name).toBe('ParticleShader');
            expect(definition.shaderLanguage).toBe(SHADERLANGUAGE_GLSL);
        });

        it('creates the shader from the engine particle chunks', () => {
            const definition = particle.createShaderDefinition(device, createOptions());

            expect(definition.vincludes.has('particle_shaderVS')).toBe(true);
            expect(definition.fincludes.has('particle_shaderPS')).toBe(true);
            expect(definition.attributes.particle_vertexData).toBe('POSITION');
        });

        it('adds the GPU execution define for GPU particles', () => {
            const definition = particle.createShaderDefinition(device, createOptions({ useCpu: false }));

            expect(definition.vshader).toMatch(/^#define PARTICLE_GPU\s*$/m);
            expect(definition.fshader).toMatch(/^#define PARTICLE_GPU\s*$/m);
            expect(definition.vshader).not.toMatch(/^#define PARTICLE_CPU\s*$/m);
        });

        it('adds the CPU execution define for CPU particles', () => {
            const definition = particle.createShaderDefinition(device, createOptions({ useCpu: true }));

            expect(definition.vshader).toMatch(/^#define PARTICLE_CPU\s*$/m);
            expect(definition.fshader).toMatch(/^#define PARTICLE_CPU\s*$/m);
            expect(definition.vshader).not.toMatch(/^#define PARTICLE_GPU\s*$/m);
        });

        it('passes the generator defines to both shader stages', () => {
            const definition = particle.createShaderDefinition(device, createOptions({
                defines: new Map([['MY_DEFINE', 1]])
            }));

            expect(definition.vshader).toContain('#define MY_DEFINE 1');
            expect(definition.fshader).toContain('#define MY_DEFINE 1');
        });

        it('passes the vertex and fragment flags to the corresponding defines', () => {
            const definition = particle.createShaderDefinition(device, createOptions({
                localSpace: true,
                halflambert: true,
                blend: BLEND_ADDITIVE,
                normal: 1
            }));

            expect(definition.vshader).toContain('#define LOCAL_SPACE');
            expect(definition.fshader).toContain('#define HALF_LAMBERT');
            expect(definition.fshader).toContain('#define BLEND ADDITIVE');
            expect(definition.fshader).toContain('#define NORMAL VERTEX');
            expect(definition.vshader).not.toContain('#define HALF_LAMBERT');
        });

        it('creates a WGSL particle shader definition on a WebGPU device', () => {
            const webgpuDevice = createTestDevice({ webgpu: true });
            const definition = particle.createShaderDefinition(webgpuDevice, createOptions());

            expect(definition.shaderLanguage).toBe(SHADERLANGUAGE_WGSL);
            expect(definition.fshader).toContain('#define NORMAL NONE');
            webgpuDevice.destroy();
        });

    });

});
